INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逃离", "is_correct": false, "explanation": "配价：“逃离”要直接带处所宾语，“逃离在……里”的结构不成立。"}, {"text": "争论", "is_correct": false, "explanation": "语义：争论是口角，与“比赛的紧张”描述的投入状态不符。"}, {"text": "厌倦", "is_correct": false, "explanation": "搭配：“厌倦”通常直接带对象，不说“厌倦在……里”，不能这样搭配。"}, {"text": "沉浸", "is_correct": true, "explanation": "沉浸指完全进入某种状态，与“比赛的紧张里”的投入感相符。"}], "explanations": {"逃离": "配价：“逃离”要直接带处所宾语，“逃离在……里”的结构不成立。", "争论": "语义：争论是口角，与“比赛的紧张”描述的投入状态不符。", "厌倦": "搭配：“厌倦”通常直接带对象，不说“厌倦在……里”，不能这样搭配。", "沉浸": "沉浸指完全进入某种状态，与“比赛的紧张里”的投入感相符。"}, "sentence_index": 6, "correct_answer": "沉浸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把身子沉浸到被子里，很快就睡着了。", "explanation": "这里应该用〈钻〉。〈沉浸〉指全身心投入，不用来说把身子放进被子里。"}, {"text": "他沉浸了三个月的亏损，却毫不着急。", "explanation": "这里应该用〈承受〉。〈沉浸〉不能直接带宾语，应说承受三个月的亏损。"}, {"text": "他把手机沉浸在桌上，就出门了。", "explanation": "这里应该用〈放〉。〈沉浸〉指全身心投入某种状态，不能用于把物品放在某处，应说把手机放在桌上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐沉浸菜香里，忘了关火。", "corrected_sentence": "姐姐沉浸在菜香里，忘了关火。", "error_description": "介词缺失：“沉浸”后面要用“在……里”引出所沉浸的对象，应说“沉浸在菜香里”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟沉浸了在动画片里，忘了写作业。", "corrected_sentence": "弟弟沉浸在动画片里，忘了写作业。", "error_description": "“了”的位置错误：“了”不能插在“沉浸”和“在”之间，应说“沉浸在动画片里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
