INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23692, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "场域是一个地方，人们在那里做事情或者互相影响。", "primary_collocate": null, "pronunciation": "chǎng yù", "ipa": "tʂʰaŋ˨˩˦ y˥˩", "syllable_count": 2, "sentences": [{"text": "学校是学生学习和交朋友的场域。", "target_word": "场域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络是年轻人聊天和玩游戏的场域。", "target_word": "场域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司是同事一起工作的场域。", "target_word": "场域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球场是大家一起运动的场域。", "target_word": "场域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个场域里，每个人都会影响别人。", "target_word": "场域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在艺术场域里认识了很多朋友。", "target_word": "场域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上商店是一个新的消费场域。", "target_word": "场域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家庭是孩子最早接触的场域。", "target_word": "场域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政治场域里的人，常常互相影响。", "target_word": "场域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社区是邻居见面和聊天的场域。", "target_word": "场域", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "文化场域", "label": "复合"}, {"form": "政治场域", "label": "复合"}], "register": "书面", "sense_fingerprint": "场域：人们做事并互相影响的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34bc2cc-089b-431f-93cf-0515a2573957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23692, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场域", "is_correct": true, "explanation": "正确。“学生学习和交朋友的场域”指学生学习、交友的地方，与句意相合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑的一部分，不是人们学习和交朋友的地方，句意不通。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是食物，不是地方，不能指学生学习和交朋友的场所。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时的物品，不能指学生学习和交朋友的地方。"}], "explanations": {"场域": "正确。“学生学习和交朋友的场域”指学生学习、交友的地方，与句意相合。", "窗户": "语义：窗户是建筑的一部分，不是人们学习和交朋友的地方，句意不通。", "早饭": "语义：早饭是食物，不是地方，不能指学生学习和交朋友的场所。", "闹钟": "语义：闹钟是计时的物品，不能指学生学习和交朋友的地方。"}, "sentence_index": 0, "correct_answer": "场域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提出的这个想法很好，是一个场域。", "explanation": "这里应该用〈观点〉。场域指地方，想法不是地方，不能用场域。"}, {"text": "这把椅子是一个场域。", "explanation": "场域指人们做事、互相影响的地方，椅子是物品，不符合这个意思。"}, {"text": "这份资料很有用，是一个场域。", "explanation": "这里应该用〈信息〉。场域指人们做事、互相影响的地方，资料表示的是内容，应说成信息，不能用场域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场域", "is_correct": true, "explanation": "正确。“新的消费场域”指人们购物、消费的新地方，网上商店正是这样的地方。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种病，不是地方，“新的消费感冒”说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，不能指购物发生的地方，句子不通。"}, {"text": "扫把", "is_correct": false, "explanation": "语义：扫把是打扫用的工具，不能作为购物活动的场所，句意不通。"}], "explanations": {"场域": "正确。“新的消费场域”指人们购物、消费的新地方，网上商店正是这样的地方。", "感冒": "语义：感冒是一种病，不是地方，“新的消费感冒”说不通。", "雨伞": "语义：雨伞是物品，不能指购物发生的地方，句子不通。", "扫把": "语义：扫把是打扫用的工具，不能作为购物活动的场所，句意不通。"}, "sentence_index": 6, "correct_answer": "场域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一刻是我最幸福的场域。", "explanation": "这里应该用〈时刻〉。场域指地方，表示某个时间点要用时刻。"}, {"text": "学习是一个长期的场域。", "explanation": "这里应该用〈过程〉。场域指地方，表示持续的进程要用过程。"}, {"text": "演讲是一项有趣的场域。", "explanation": "这里应该用〈活动〉。场域指活动发生的地方，演讲本身是活动，要用活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座公园是老人锻炼身体的一条重要场域。", "corrected_sentence": "这座公园是老人锻炼身体的一个重要场域。", "error_description": "量词错误：“场域”应配“个”，“条”用于细长之物，不能用来计量场域。应说“一个重要场域”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们这个场域里玩耍。", "corrected_sentence": "孩子们在这个场域里玩耍。", "error_description": "缺少介词“在”：表示处所的“……里”前需要“在”，应说“在这个场域里玩耍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
