INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23700, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "创造某个重要东西的人。", "primary_collocate": null, "pronunciation": "dì zào zhě", "ipa": "ti˥˩ tsɑʊ˥˩ ʈʂɤ˨˩", "syllable_count": 3, "sentences": [{"text": "他们是这个奇迹的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们每个人都是和平的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个团队是历史的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人是城市繁荣的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说他是幸福生活的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家是新时代的缔造者之一。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些工人是这座大桥的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不是旁观者，而是这个故事的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人是未来世界的缔造者。", "target_word": "缔造者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位建筑师是这座城市许多地标的缔造者。", "target_word": "缔造者", "complexity_tier": "T3", "furigana": "zhè wèi jiànzhùshī shì zhè zuò chéngshì xǔduō dìbiāo de dìzàozhě.", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "締造者", "label": "繁体"}], "register": "书面", "sense_fingerprint": "缔造者：创造和平、奇迹等重要事物的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81f83eb8-767f-466e-a846-5878bcd12e3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小偷", "is_correct": false, "explanation": "语义：“奇迹”是值得赞美的事物，小偷与“创造奇迹”的关系不合。"}, {"text": "缔造者", "is_correct": true, "explanation": "“缔造者”指创造重要事物的人，与“这个奇迹”搭配，符合句子语境。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人是患病的人，与“创造奇迹”的语义不合。"}, {"text": "垃圾", "is_correct": false, "explanation": "语域：“垃圾”是贬义口语词，与“奇迹”这种褒义的书面语域不合。"}], "explanations": {"小偷": "语义：“奇迹”是值得赞美的事物，小偷与“创造奇迹”的关系不合。", "缔造者": "“缔造者”指创造重要事物的人，与“这个奇迹”搭配，符合句子语境。", "病人": "语义：病人是患病的人，与“创造奇迹”的语义不合。", "垃圾": "语域：“垃圾”是贬义口语词，与“奇迹”这种褒义的书面语域不合。"}, "sentence_index": 0, "correct_answer": "缔造者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这张小纸条的缔造者。", "explanation": "这里应该用〈作者〉。缔造者指创造重大事物的人，一张小纸条是日常小事，应说“写纸条的人”或“作者”。"}, {"text": "妈妈是这顿午饭的缔造者。", "explanation": "这里应该用〈做饭的人〉。缔造者用于和平、奇迹、国家等重要事物，做一顿午饭不能说“缔造者”。"}, {"text": "弟弟是这杯果汁的缔造者。", "explanation": "这里应该用〈做果汁的人〉。缔造者指创造重要事物的人，一杯果汁太平常，不能用“缔造者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游客", "is_correct": false, "explanation": "语义：工人是建造者，游客是前来参观的人，二者身份不合。"}, {"text": "租客", "is_correct": false, "explanation": "搭配：“租客”需要被租住的对象，大桥不能被租住。"}, {"text": "废墟", "is_correct": false, "explanation": "语义：废墟是被毁坏后的遗迹，与“工人”作为创造者的身份矛盾。"}, {"text": "缔造者", "is_correct": true, "explanation": "“缔造者”指创造这座大桥的人，与“这些工人”的身份相符，符合句子语境。"}], "explanations": {"游客": "语义：工人是建造者，游客是前来参观的人，二者身份不合。", "租客": "搭配：“租客”需要被租住的对象，大桥不能被租住。", "废墟": "语义：废墟是被毁坏后的遗迹，与“工人”作为创造者的身份矛盾。", "缔造者": "“缔造者”指创造这座大桥的人，与“这些工人”的身份相符，符合句子语境。"}, "sentence_index": 6, "correct_answer": "缔造者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这盘炒鸡蛋的缔造者。", "explanation": "这里应该用〈厨师〉。缔造者用于重要事物，炒一盘鸡蛋是日常小事，不能用“缔造者”。"}, {"text": "我是这张便条的缔造者。", "explanation": "这里应该用〈写便条的人〉。缔造者指创造重要事物的人，写便条不能说“缔造”。"}, {"text": "她是这个雪人的缔造者。", "explanation": "这里应该用〈堆雪人的人〉。缔造者用于国家、事业、奇迹等重要事物，堆雪人是游戏，不能用“缔造者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是这座桥梁的一只缔造者。", "corrected_sentence": "他是这座桥梁的一位缔造者。", "error_description": "“缔造者”指人，量词应用“位”。“只”多用于动物，此处用“只”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是这个村庄的缔造者一。", "corrected_sentence": "他是这个村庄的缔造者之一。", "error_description": "“缔造者之一”是固定组合，“之”不能省略；这里漏掉了“之”，应为“缔造者之一”，“缔造者一”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
