INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23704, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "只有，没有别的。", "primary_collocate": null, "pronunciation": "jǐn", "ipa": "tɕin˨˩˦", "syllable_count": 1, "sentences": [{"text": "这家店仅卖早餐。", "target_word": "仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班仅有三个人迟到。", "target_word": "仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天仅有一节课，我下午可以休息。", "target_word": "仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书仅售二十元。", "target_word": "仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他仅用十分钟就做完了作业。", "target_word": "仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议室仅能坐十个人。", "target_word": "仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我仅去过一次北京。", "target_word": "仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他仅花了五块钱就买到了。", "target_word": "仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司仅有五名员工，但是大家都很努力。", "target_word": "仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他仅会说一点儿中文。", "target_word": "仅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "仅仅", "label": "重叠"}, {"form": "僅", "label": "繁体"}], "register": "书面", "sense_fingerprint": "限定数量或范围，表示只有这些", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5fcf5b-556e-47e4-b003-813f3f632225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23704, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仅", "is_correct": true, "explanation": "正确答案：仅 jǐn，意思是只有、没有别的。"}, {"text": "近", "is_correct": false, "explanation": "jìn（第四声）与 jǐn（第三声）声调不同，近意思是靠近。"}, {"text": "景", "is_correct": false, "explanation": "jǐng 与 jǐn 韵尾不同（-ng 与 -n），景意思是风景。"}, {"text": "今", "is_correct": false, "explanation": "jīn（第一声）与 jǐn（第三声）声调不同，今意思是现在、今天。"}], "explanations": {"仅": "正确答案：仅 jǐn，意思是只有、没有别的。", "近": "jìn（第四声）与 jǐn（第三声）声调不同，近意思是靠近。", "景": "jǐng 与 jǐn 韵尾不同（-ng 与 -n），景意思是风景。", "今": "jīn（第一声）与 jǐn（第三声）声调不同，今意思是现在、今天。"}, "sentence_index": null, "correct_answer": "仅"}, "level_3": {"options": [{"text": "仅", "is_correct": true, "explanation": "正确：“仅”表示只卖早餐、不卖别的，与“这家店”的限定语境相符。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示抓紧时间尽快做某事，用在“这家店……卖早餐”这类限定陈述里，意思不通。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”多用于叮嘱或劝阻，不能用来陈述店铺卖什么，句子不通。"}, {"text": "切勿", "is_correct": false, "explanation": "语域：“切勿”是严肃的禁令用语，用在店铺卖早餐的叙述中语体不合，句子不通。"}], "explanations": {"仅": "正确：“仅”表示只卖早餐、不卖别的，与“这家店”的限定语境相符。", "赶紧": "语义：“赶紧”表示抓紧时间尽快做某事，用在“这家店……卖早餐”这类限定陈述里，意思不通。", "千万": "语义：“千万”多用于叮嘱或劝阻，不能用来陈述店铺卖什么，句子不通。", "切勿": "语域：“切勿”是严肃的禁令用语，用在店铺卖早餐的叙述中语体不合，句子不通。"}, "sentence_index": 0, "correct_answer": "仅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他仅会说中文，还会说英文。", "explanation": "这里应该用〈不仅〉。仅表示只有，后面不能再接“还会说英文”，前后自相矛盾。"}, {"text": "他仅比我高很多。", "explanation": "这里应该删去〈仅〉。仅表示数量有限，与“很多”表示数量大的意思相矛盾。"}, {"text": "这个菜仅好吃。", "explanation": "这里应该用〈很〉。仅表示只有、没有别的，不能修饰形容词表示程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23704, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "仅", "is_correct": true, "explanation": "正确答案：仅 jǐn，意思是只有、没有别的。"}, {"text": "进", "is_correct": false, "explanation": "jìn（第四声）与 jǐn（第三声）声调不同，进意思是向里走。"}, {"text": "警", "is_correct": false, "explanation": "jǐng 与 jǐn 韵尾不同（-ng 与 -n），警意思是警察。"}, {"text": "金", "is_correct": false, "explanation": "jīn（第一声）与 jǐn（第三声）声调不同，金意思是金属。"}], "explanations": {"仅": "正确答案：仅 jǐn，意思是只有、没有别的。", "进": "jìn（第四声）与 jǐn（第三声）声调不同，进意思是向里走。", "警": "jǐng 与 jǐn 韵尾不同（-ng 与 -n），警意思是警察。", "金": "jīn（第一声）与 jǐn（第三声）声调不同，金意思是金属。"}, "sentence_index": null, "correct_answer": "仅"}, "level_3": {"options": [{"text": "仅", "is_correct": true, "explanation": "正确：“仅”表示只去过一次，与“去过一次”的限定语境相符。"}, {"text": "总是", "is_correct": false, "explanation": "搭配：“总是”表示经常，与“去过一次”这种限定次数的说法不搭配。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示没有必要，与已经发生的“去过”这一经历矛盾。"}, {"text": "务必", "is_correct": false, "explanation": "语义：“务必”用于要求将来一定要做，不能用来叙述已经发生的经历。"}], "explanations": {"仅": "正确：“仅”表示只去过一次，与“去过一次”的限定语境相符。", "总是": "搭配：“总是”表示经常，与“去过一次”这种限定次数的说法不搭配。", "不必": "语义：“不必”表示没有必要，与已经发生的“去过”这一经历矛盾。", "务必": "语义：“务必”用于要求将来一定要做，不能用来叙述已经发生的经历。"}, "sentence_index": 6, "correct_answer": "仅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全班仅来了。", "explanation": "这里应该用〈都〉。仅表示只有、没有别的，与“全班”表示全体的意思矛盾；全体到场要用“都”。"}, {"text": "他会说中文，仅会说英文。", "explanation": "这里应该用〈也〉。仅表示只有，与前句“会说中文”并列的意思不符，句子变成只会英文。"}, {"text": "这两件衣服仅一样。", "explanation": "这里应该用〈差不多〉。仅表示只有、没有别的，不能表示接近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张票仅不限学生使用。", "corrected_sentence": "这张票仅限学生使用。", "error_description": "错误：“仅不限学生使用”。正确：“仅限学生使用”。“仅限”是固定搭配，表示只限于某类人；加入“不”后意思自相矛盾，应删去“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用仅一天写完了报告。", "corrected_sentence": "她仅用一天写完了报告。", "error_description": "错误：“用仅一天写完”。正确：“仅用一天写完”。“仅”表示只有，应放在“用”之前修饰整个动作，不能夹在“用”和“一天”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
