INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23706, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "某个东西可以装下别的东西，比如盒子能装下玩具。", "primary_collocate": null, "pronunciation": "róng nà", "ipa": "ɻʊŋ˧˥ na˥˩", "syllable_count": 2, "sentences": [{"text": "这个盒子能容纳很多玩具。", "target_word": "容纳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小书包容纳不下这么多书。", "target_word": "容纳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的冰箱太小，容纳不了西瓜。", "target_word": "容纳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个大箱子可以容纳所有的衣服。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个篮子能容纳弟弟所有的球。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子只能容纳一杯水。", "target_word": "容纳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯很小，最多容纳六个人。", "target_word": "容纳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间不大，容纳不了三张床。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大背包能容纳我的所有东西。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的停车场容纳了很多汽车。", "target_word": "容纳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "容纳了", "label": "体标"}, {"form": "容纳着", "label": "体标"}, {"form": "容纳过", "label": "体标"}, {"form": "容纳不下", "label": "复合"}], "register": "中性", "sense_fingerprint": "容纳|容器或空间能装下别的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2591be7d-c461-4a95-9b42-c5a8240a6d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "购买", "is_correct": false, "explanation": "配价：“购买”的施事须是人，盒子不能购买玩具。"}, {"text": "容纳", "is_correct": true, "explanation": "容纳指容器能装下别的东西，盒子能容纳很多玩具，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "配价：“欣赏”的主体须是有感知能力的人，盒子不能欣赏玩具。"}, {"text": "生产", "is_correct": false, "explanation": "语义：盒子是容器，不能生产玩具。"}], "explanations": {"购买": "配价：“购买”的施事须是人，盒子不能购买玩具。", "容纳": "容纳指容器能装下别的东西，盒子能容纳很多玩具，符合句意。", "欣赏": "配价：“欣赏”的主体须是有感知能力的人，盒子不能欣赏玩具。", "生产": "语义：盒子是容器，不能生产玩具。"}, "sentence_index": 0, "correct_answer": "容纳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把衣服容纳进了箱子里。", "explanation": "这里应该用〈装〉。容纳强调空间能包含某物，把东西放进容器要用“装”。"}, {"text": "我把外套容纳在门后面。", "explanation": "这里应该用〈挂〉。容纳不表示悬挂，把衣物挂起来要用“挂”。"}, {"text": "这辆汽车容纳在车库里。", "explanation": "这里应该用〈停〉。容纳不表示停放车辆，车辆停放在某处要用“停”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浇灌", "is_correct": false, "explanation": "语义：“浇灌”针对植物，不能用于电梯装人。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”的宾语应是车辆，不能带人作宾语。"}, {"text": "容纳", "is_correct": true, "explanation": "容纳指空间能装下人数，电梯很小，最多容纳六个人，符合句意。"}, {"text": "辅导", "is_correct": false, "explanation": "语义：“辅导”是指导学习的行为，电梯不能辅导人。"}], "explanations": {"浇灌": "语义：“浇灌”针对植物，不能用于电梯装人。", "驾驶": "配价：“驾驶”的宾语应是车辆，不能带人作宾语。", "容纳": "容纳指空间能装下人数，电梯很小，最多容纳六个人，符合句意。", "辅导": "语义：“辅导”是指导学习的行为，电梯不能辅导人。"}, "sentence_index": 6, "correct_answer": "容纳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟弟正在容纳作业。", "explanation": "这里应该用〈写〉。容纳指空间能装下某物，写作业要用“写”，不能说“容纳作业”。"}, {"text": "这堵墙容纳了风。", "explanation": "这里应该用〈挡〉。容纳表示能装下，墙阻挡风要用“挡”。"}, {"text": "妈妈每天都容纳地板。", "explanation": "这里应该用〈擦〉。容纳表示能装下，擦洗地板要用“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个行李箱容纳下得两件外套。", "corrected_sentence": "这个行李箱容纳得下两件外套。", "error_description": "可能补语的语序错误：“容纳”后的可能补语应为“得下”，应说“容纳得下两件外套”，不能说“容纳下得两件外套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个鱼缸能容纳得十条金鱼。", "corrected_sentence": "这个鱼缸能容纳十条金鱼。", "error_description": "多余的“得”：“容纳得”后须接可能补语（如“容纳得下”），这里应直接说“能容纳十条金鱼”，去掉“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
