INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23710, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是很猛、很用力，像打架时很厉害的样子。", "primary_collocate": null, "pronunciation": "jī liè", "ipa": "tɕi˥ liɛ˥˩", "syllable_count": 2, "sentences": [{"text": "两只狗激烈地打了起来。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在街上激烈地打架，大家都不敢靠近。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拳击手在台上激烈地互相攻击。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子为了玩具激烈地争抢起来。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球员们在场上激烈地碰撞。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人打得很激烈，周围的人赶紧去劝。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人激烈地推来推去，谁也不让谁。", "target_word": "激烈", "complexity_tier": "T3", "furigana": "liǎng gè rén jī liè de tuī lái tuī qù, shéi yě bú ràng shéi.", "sentence_source": "generated"}, {"text": "昨晚的拳赛打得非常激烈。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员激烈地冲向终点。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们与敌人展开了激烈的战斗。", "target_word": "激烈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "激烈地", "label": "状语形式"}, {"form": "激烈的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "激烈：动作猛、用力，像打斗时的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2591be7d-c461-4a95-9b42-c5a8240a6d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23710, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "激烈", "is_correct": true, "explanation": "正确。激烈形容动作猛、用力，像打斗时的样子。"}, {"text": "机械", "is_correct": false, "explanation": "xiè（第四声）与 liè（第四声）声母不同，意思是机器、器械。"}, {"text": "激励", "is_correct": false, "explanation": "lì 与 liè 韵母不同（少一个 e），意思是鼓舞、鼓励。"}, {"text": "基业", "is_correct": false, "explanation": "yè 与 liè 声母不同，意思是事业的基础。"}, {"text": "积液", "is_correct": false, "explanation": "yè 与 liè 声母不同，意思是体内积存的液体。"}, {"text": "极力", "is_correct": false, "explanation": "jí 与 jī 声调不同，lì 与 liè 韵母不同，意思是尽力。"}], "explanations": {"激烈": "正确。激烈形容动作猛、用力，像打斗时的样子。", "机械": "xiè（第四声）与 liè（第四声）声母不同，意思是机器、器械。", "激励": "lì 与 liè 韵母不同（少一个 e），意思是鼓舞、鼓励。", "基业": "yè 与 liè 声母不同，意思是事业的基础。", "积液": "yè 与 liè 声母不同，意思是体内积存的液体。", "极力": "jí 与 jī 声调不同，lì 与 liè 韵母不同，意思是尽力。"}, "sentence_index": null, "correct_answer": "激烈"}, "level_3": {"options": [{"text": "激烈", "is_correct": true, "explanation": "正确。“激烈地”描述两只狗打斗时动作猛烈。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”与“打了起来”的动作相矛盾。"}, {"text": "悠闲", "is_correct": false, "explanation": "语义：“悠闲”描述状态从容，与“打了起来”的动作不符。"}, {"text": "礼貌", "is_correct": false, "explanation": "搭配：“礼貌”说的是态度，不能用来修饰“打”这种动作。"}], "explanations": {"激烈": "正确。“激烈地”描述两只狗打斗时动作猛烈。", "温柔": "语义：“温柔”与“打了起来”的动作相矛盾。", "悠闲": "语义：“悠闲”描述状态从容，与“打了起来”的动作不符。", "礼貌": "搭配：“礼貌”说的是态度，不能用来修饰“打”这种动作。"}, "sentence_index": 0, "correct_answer": "激烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全班同学激烈地欢迎转学生。", "explanation": "这里应该用〈热烈〉。激烈形容动作猛、用力，欢迎的热情要用热烈。"}, {"text": "她对音乐有激烈的兴趣。", "explanation": "这里应该用〈浓厚〉。激烈形容动作猛、用力，表示兴趣深要用浓厚。"}, {"text": "他的胃激烈地疼起来。", "explanation": "这里应该用〈剧烈〉。激烈形容动作猛、用力，身体疼痛要用剧烈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激烈", "is_correct": true, "explanation": "正确。“激烈地”描述两人推搡的动作猛烈。"}, {"text": "温和", "is_correct": false, "explanation": "语义：“温和”与“谁也不让谁”的态度相矛盾。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”说动作随意，与“谁也不让谁”的对抗不符。"}, {"text": "友好", "is_correct": false, "explanation": "搭配：“友好”说的是关系和态度，不用来修饰“推”这种动作。"}], "explanations": {"激烈": "正确。“激烈地”描述两人推搡的动作猛烈。", "温和": "语义：“温和”与“谁也不让谁”的态度相矛盾。", "轻松": "语义：“轻松”说动作随意，与“谁也不让谁”的对抗不符。", "友好": "搭配：“友好”说的是关系和态度，不用来修饰“推”这种动作。"}, "sentence_index": 6, "correct_answer": "激烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡的味道很激烈。", "explanation": "这里应该用〈浓烈〉。激烈形容很猛、很用力的动作，气味、味道的浓郁要用浓烈。"}, {"text": "这个房间的温度很激烈。", "explanation": "这里应该用〈高〉。激烈形容动作猛、用力，温度的高低要用高或低。"}, {"text": "这头狮子是一只激烈的野兽。", "explanation": "这里应该用〈凶猛〉。激烈形容很猛、很用力的动作，形容野兽的凶狠要用凶猛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两辆车在路口激烈的相撞。", "corrected_sentence": "两辆车在路口激烈地相撞。", "error_description": "错误：“激烈的相撞”，正确：“激烈地相撞”。修饰动词的状语要用“地”，“的”用于名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个人激烈得拉扯起来，谁也不肯松手。", "corrected_sentence": "两个人激烈地拉扯起来，谁也不肯松手。", "error_description": "错误：“激烈得”，正确：“激烈地”。“地”用于修饰动词“拉扯”的状语，“得”用于动词后的补语，这里不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f3c368d-00d4-4a6c-a492-be7f979f4ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23712, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主动", "is_correct": true, "explanation": "正确。“主动”与“被动”互为反义，指自己发起行动、不等待别人安排。"}, {"text": "聪明", "is_correct": false, "explanation": "与“被动”无反义关系，“聪明”描述才智，不是对义词。"}, {"text": "安静", "is_correct": false, "explanation": "与“被动”无反义关系，“安静”的对义词是“吵闹”。"}, {"text": "轻松", "is_correct": false, "explanation": "与“被动”无反义关系，“轻松”的对义词是“紧张”。"}], "correct_answer": "主动", "explanations": {"主动": "正确。“主动”与“被动”互为反义，指自己发起行动、不等待别人安排。", "聪明": "与“被动”无反义关系，“聪明”描述才智，不是对义词。", "安静": "与“被动”无反义关系，“安静”的对义词是“吵闹”。", "轻松": "与“被动”无反义关系，“轻松”的对义词是“紧张”。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23712, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主动", "is_correct": true, "explanation": "正确。“主动”与“被动”互为反义，指自己拿主意、发起行动。"}, {"text": "清楚", "is_correct": false, "explanation": "与“被动”无反义关系，“清楚”的对义词是“模糊”。"}, {"text": "热闹", "is_correct": false, "explanation": "与“被动”无反义关系，“热闹”的对义词是“冷清”。"}, {"text": "复杂", "is_correct": false, "explanation": "与“被动”无反义关系，“复杂”的对义词是“简单”。"}], "correct_answer": "主动", "explanations": {"主动": "正确。“主动”与“被动”互为反义，指自己拿主意、发起行动。", "清楚": "与“被动”无反义关系，“清楚”的对义词是“模糊”。", "热闹": "与“被动”无反义关系，“热闹”的对义词是“冷清”。", "复杂": "与“被动”无反义关系，“复杂”的对义词是“简单”。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23712, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "别人让你做什么，你就做什么。", "primary_collocate": null, "pronunciation": "bèi dòng", "ipa": "pei˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他很被动，老师说什么就做什么。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她性格太被动，父母让她报什么专业，她就报什么。", "target_word": "被动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被动的人总是等别人安排。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟学习很被动，妈妈不说他就不写作业。", "target_word": "被动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司很被动，经理不问，他就不说话。", "target_word": "被动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要这么被动，你也说说自己的想法。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他被动地听着大家的安排。", "target_word": "被动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子做事太被动，家长很着急。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友去哪儿，他就跟着去哪儿，很被动。", "target_word": "被动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别总是被动，自己决定一次吧。", "target_word": "被动", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "被动地", "label": "状语形式"}, {"form": "被动语态", "label": "复合"}], "register": "中性", "sense_fingerprint": "别人说什么就做什么，自己不主动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94b4d57c-ba46-40c9-9d83-b3978f6c429b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被动", "is_correct": true, "explanation": "正确。“被动”指别人让做什么就做什么，与“老师说什么就做什么”一致。"}, {"text": "固执", "is_correct": false, "explanation": "语义：“固执”指坚持己见、不肯变通，与“老师说什么就做什么”的顺从相矛盾。"}, {"text": "叛逆", "is_correct": false, "explanation": "语义：“叛逆”指反抗管束，与“老师说什么就做什么”的顺从正相反。"}, {"text": "独立", "is_correct": false, "explanation": "语义：“独立”指自己拿主意、不依赖别人，与“老师说什么就做什么”的顺从相矛盾。"}], "explanations": {"被动": "正确。“被动”指别人让做什么就做什么，与“老师说什么就做什么”一致。", "固执": "语义：“固执”指坚持己见、不肯变通，与“老师说什么就做什么”的顺从相矛盾。", "叛逆": "语义：“叛逆”指反抗管束，与“老师说什么就做什么”的顺从正相反。", "独立": "语义：“独立”指自己拿主意、不依赖别人，与“老师说什么就做什么”的顺从相矛盾。"}, "sentence_index": 0, "correct_answer": "被动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这孩子被动得很，连穿什么都要自己定，谁说都不听。", "explanation": "这里应用〈有主见〉。“被动”指听从别人、不自己拿主意，与“连穿什么都自己定、谁说都不听”相矛盾。"}, {"text": "他被动地反驳了老师的意见，谁劝都不改口。", "explanation": "这里应用〈固执〉。“被动”指别人让做什么就做什么，与“反驳老师、谁劝都不改口”的坚持态度不符。"}, {"text": "他很被动，从不依赖别人，做事都自己拿主意。", "explanation": "这里应用〈独立〉。“被动”指别人让做什么就做什么，与“从不依赖别人、自己拿主意”正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被动", "is_correct": true, "explanation": "正确。“听着大家的安排”即顺从他人安排，与“被动”相合。"}, {"text": "任性", "is_correct": false, "explanation": "语义：“任性”指随心所欲、不听劝，与“听着大家的安排”相矛盾。"}, {"text": "独断", "is_correct": false, "explanation": "语义：“独断”指擅自决定、不听他人意见，与“听着大家的安排”相悖。"}, {"text": "积极", "is_correct": false, "explanation": "搭配：“积极”多用于主动参与，与“听着安排”这种被动接受搭配不当。"}], "explanations": {"被动": "正确。“听着大家的安排”即顺从他人安排，与“被动”相合。", "任性": "语义：“任性”指随心所欲、不听劝，与“听着大家的安排”相矛盾。", "独断": "语义：“独断”指擅自决定、不听他人意见，与“听着大家的安排”相悖。", "积极": "搭配：“积极”多用于主动参与，与“听着安排”这种被动接受搭配不当。"}, "sentence_index": 6, "correct_answer": "被动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次聚会的安排，他被动地一手包办了，还负责拉赞助。", "explanation": "这里应用〈主导〉。“被动”指别人让做什么就做什么，与“一手包办、还负责拉赞助”的主动操办相矛盾。"}, {"text": "他在班里很被动，每次班会都抢着上台主持。", "explanation": "这里应用〈踊跃〉。“被动”指别人让做什么就做什么，与“抢着上台主持”的主动表现相矛盾。"}, {"text": "这份报告他被动地熬了三个通宵，把每一页都检查了一遍。", "explanation": "这里应用〈自觉〉。“被动”指别人让做什么就做什么，与“熬了三个通宵、逐页检查”的主动投入相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她被动的听从了父母的决定。", "corrected_sentence": "她被动地听从了父母的决定。", "error_description": "“被动”作状语修饰动词“听从”，应用“地”；此处误用“的”（定语标记）。正确：她被动地听从了父母的决定。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她被动地很，朋友不催，她就不动。", "corrected_sentence": "她被动得很，朋友不催，她就不动。", "error_description": "“被动”后作补语，应用“得”，此处误用“地”（状语标记）。正确：她被动得很，朋友不催，她就不动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
