INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23718, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "打仗的地方，有很多士兵。", "primary_collocate": null, "pronunciation": "zhàn chǎng", "ipa": "ʈ͡ʂan˥˩ ʈ͡ʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "战场上有很多士兵。", "target_word": "战场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷年轻时去过战场。", "target_word": "战场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战场上的士兵又累又饿。", "target_word": "战场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电影里的战场看起来非常可怕。", "target_word": "战场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "士兵们拿着枪走向战场。", "target_word": "战场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战场上很吵，到处都是枪声。", "target_word": "战场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不想让哥哥去战场。", "target_word": "战场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "士兵们在战场上睡得很少。", "target_word": "战场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争结束了，战场上安静下来。", "target_word": "战场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老兵常常说起他在战场上的朋友。", "target_word": "战场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "戰場", "label": "繁体"}, {"form": "主战场", "label": "复合"}], "register": "中性", "sense_fingerprint": "打仗的地方，士兵很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f2f380-84e6-4cc1-b3ea-516ce01c2dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23718, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "战场", "is_correct": true, "explanation": "正确。战场指打仗的地方，有很多士兵。"}, {"text": "展场", "is_correct": false, "explanation": "声调不同：展场（zhǎn chǎng）与战场只有第一音节声调不同（第三声与第四声），意思是展览的场地。"}, {"text": "站长", "is_correct": false, "explanation": "声母不同：站长（zhàn zhǎng）与战场只有第二音节声母不同（zh 与 ch），意思是车站的负责人。"}, {"text": "散场", "is_correct": false, "explanation": "声母不同：散场（sàn chǎng）与战场只有第一音节声母不同（s 与 zh），意思是演出或活动结束后人群离开。"}], "explanations": {"战场": "正确。战场指打仗的地方，有很多士兵。", "展场": "声调不同：展场（zhǎn chǎng）与战场只有第一音节声调不同（第三声与第四声），意思是展览的场地。", "站长": "声母不同：站长（zhàn zhǎng）与战场只有第二音节声母不同（zh 与 ch），意思是车站的负责人。", "散场": "声母不同：散场（sàn chǎng）与战场只有第一音节声母不同（s 与 zh），意思是演出或活动结束后人群离开。"}, "sentence_index": null, "correct_answer": "战场"}, "level_3": {"options": [{"text": "战场", "is_correct": true, "explanation": "正确。“战场上有很多士兵”指打仗的地方，与释义相符。"}, {"text": "课堂", "is_correct": false, "explanation": "语义：课堂是上课的地方，不会有很多士兵，与“打仗”的语境冲突。"}, {"text": "考场", "is_correct": false, "explanation": "语义：考场是考试的地方，与士兵聚集的语境不符。"}, {"text": "键盘", "is_correct": false, "explanation": "搭配：“键盘”是输入设备，不是能容纳很多士兵的场所，与“有很多士兵”不搭。"}], "explanations": {"战场": "正确。“战场上有很多士兵”指打仗的地方，与释义相符。", "课堂": "语义：课堂是上课的地方，不会有很多士兵，与“打仗”的语境冲突。", "考场": "语义：考场是考试的地方，与士兵聚集的语境不符。", "键盘": "搭配：“键盘”是输入设备，不是能容纳很多士兵的场所，与“有很多士兵”不搭。"}, "sentence_index": 0, "correct_answer": "战场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都在战场上写作业。", "explanation": "这里应该用〈教室〉。作业要在教室或书房里写，战场是打仗的地方，不能在那里写作业。"}, {"text": "这个战场很勇敢。", "explanation": "这里应该用〈士兵〉。战场是地点，不能用“勇敢”来形容，说人勇敢要用士兵这类指人的词。"}, {"text": "那个战场被关在营地里。", "explanation": "这里应该用〈战俘〉。战俘是人，可以被关押，战场是地点，不能被关押。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战场", "is_correct": true, "explanation": "正确。“妈妈不想让哥哥去战场”中，“战场”是“去”的处所，与语境相符。"}, {"text": "糖果", "is_correct": false, "explanation": "搭配：「去」要求表示地点的宾语，「糖果」是食物，不能作为「去」的处所。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘是下棋的器具，不能作为哥哥要去的地方，与打仗的语境不符。"}, {"text": "墨水瓶", "is_correct": false, "explanation": "语义：墨水瓶是器物，不能作为要去的地方，与语境毫无关系。"}], "explanations": {"战场": "正确。“妈妈不想让哥哥去战场”中，“战场”是“去”的处所，与语境相符。", "糖果": "搭配：「去」要求表示地点的宾语，「糖果」是食物，不能作为「去」的处所。", "棋盘": "语义：棋盘是下棋的器具，不能作为哥哥要去的地方，与打仗的语境不符。", "墨水瓶": "语义：墨水瓶是器物，不能作为要去的地方，与语境毫无关系。"}, "sentence_index": 6, "correct_answer": "战场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个战场里挤满了买菜的人。", "explanation": "这里应该用〈菜市场〉。菜市场是买菜的地方，战场是打仗的地方，不能说挤满了买菜的人。"}, {"text": "这个战场里摆满了书架。", "explanation": "这里应该用〈图书馆〉。图书馆里摆书架，战场是交战的区域，不能摆满书架。"}, {"text": "这里的战场每天开门营业，欢迎顾客光临。", "explanation": "这里应该用〈商店〉。商店才营业接待顾客，战场是打仗的地方，不能营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位医生在一只战场上救过很多伤员。", "corrected_sentence": "那位医生在一个战场上救过很多伤员。", "error_description": "量词错误：战场应用量词“个”，“只”多用于动物。错误形式“一只战场”，正确形式“一个战场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我叔叔年轻时去着战场，很少提那段经历。", "corrected_sentence": "我叔叔年轻时去过战场，很少提那段经历。", "error_description": "体标错误：表示经历要用“过”，“着”表示持续或状态，不能用于此处。错误形式“去着战场”，正确形式“去过战场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
