INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他第一次去在大陆。", "corrected_sentence": "他第一次去大陆。", "error_description": "错误：「在」插在动词「去」和处所宾语「大陆」之间，「去在大陆」不成句。正确：「去大陆」，「去」后直接接处所宾语，不加「在」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在大陆来，说一口普通话。", "corrected_sentence": "我从大陆来，说一口普通话。", "error_description": "错误：表示起点要用介词“从”，“在”表示所在地，“在大陆来”不成句。正确：“从大陆来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
