INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23724, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西的外面一层。", "primary_collocate": null, "pronunciation": "biǎo miàn", "ipa": "piɑʊ˨˩˦ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "桌子的表面很干净。", "target_word": "表面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水表面结了一层冰。", "target_word": "表面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮表面有很多小坑。", "target_word": "表面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果表面有一点脏。", "target_word": "表面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的表面飘着一片叶子。", "target_word": "表面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用布擦了擦桌子表面。", "target_word": "表面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头的表面很光滑。", "target_word": "表面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球表面大部分是海洋。", "target_word": "表面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃表面有一层水。", "target_word": "表面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙的表面刷成了白色。", "target_word": "表面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物体的外层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表面", "is_correct": true, "explanation": "正确：“桌子的表面”指桌子的外层，与“很干净”相符。"}, {"text": "厚度", "is_correct": false, "explanation": "语义：厚度是尺寸，不能用“干净”形容。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能是“干净”的。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度是快慢，不能用“干净”形容。"}], "explanations": {"表面": "正确：“桌子的表面”指桌子的外层，与“很干净”相符。", "厚度": "语义：厚度是尺寸，不能用“干净”形容。", "价格": "语义：价格不能是“干净”的。", "速度": "语义：速度是快慢，不能用“干净”形容。"}, "sentence_index": 0, "correct_answer": "表面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他喝了酒，表面很红。", "explanation": "语义：这里应该用〈脸色〉。“表面”指物体的外层，不能用来说人脸的颜色。"}, {"text": "这个人的表面很英俊。", "explanation": "这里应该用〈外表〉。“表面”指物体的外层；形容人的外貌要用〈外表〉。"}, {"text": "这道菜的表面很好吃。", "explanation": "这里应该用〈味道〉。“表面”指物体的外层，说吃起来怎么样要用“味道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表面", "is_correct": true, "explanation": "正确：“这块石头的表面”指石头的外层，与“很光滑”相符。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“光滑”形容物体表面，不形容重量。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“光滑”是触感，不形容味道。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“光滑”不形容温度。"}], "explanations": {"表面": "正确：“这块石头的表面”指石头的外层，与“很光滑”相符。", "重量": "搭配：“光滑”形容物体表面，不形容重量。", "味道": "语义：“光滑”是触感，不形容味道。", "温度": "搭配：“光滑”不形容温度。"}, "sentence_index": 6, "correct_answer": "表面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的表面讲的是一个爱情故事。", "explanation": "这里应该用〈内容〉。“表面”指物体的外层，书里讲的东西要说“内容”。"}, {"text": "这面墙的表面一共有三十年。", "explanation": "语义：“表面”指物体的外层，不表示经历的年份，这里应说〈年代〉。"}, {"text": "这块木头的表面有三个小时。", "explanation": "语义：“表面”不表示时长，三个小时的长度要说〈时间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块玻璃的表面的很干净。", "corrected_sentence": "这块玻璃的表面很干净。", "error_description": "“的”用错：“表面的很干净”不成句，“的”不能加在“表面”后面，应说“玻璃的表面很干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个杯子的一只表面很光滑。", "corrected_sentence": "这个杯子的表面很光滑。", "error_description": "量词错误：“表面”前不能用量词“只”，“只”用于动物或成对的东西。应说“这个杯子的表面很光滑”，或用“一层”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
