INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做成了很好的事。", "primary_collocate": null, "pronunciation": "chéng jiù", "ipa": "ʈʂʰɤŋ˧˥ tɕiou˥˩", "syllable_count": 2, "sentences": [{"text": "拿到这个奖是他最大的成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都为他的成就高兴。", "target_word": "成就", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子学会骑车，对他来说是个大成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小小的成就，让她很开心。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写完了第一本书，这是很大的成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跑完了全程，对自己的成就很满意。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司今年的成就，要谢谢大家的努力。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的成就让爸爸妈妈很骄傲。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做成这件事，是我们一起的成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从不跟别人说自己的成就。", "target_word": "成就", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "成就感", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：做成的值得骄傲的好事，生活中的成绩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f2f380-84e6-4cc1-b3ea-516ce01c2dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成就", "is_correct": true, "explanation": "正确：「最大的成就」指做成的最值得骄傲的事，与「拿到这个奖」相符。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：「疾病」是不好的事，说拿奖是他最大的疾病，与句意相反。"}, {"text": "伤口", "is_correct": false, "explanation": "语义：「伤口」指身体的创伤，与「拿到这个奖」无关，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「最大的」可修饰成就、困难等，不能修饰「体温」。"}], "explanations": {"成就": "正确：「最大的成就」指做成的最值得骄傲的事，与「拿到这个奖」相符。", "疾病": "语义：「疾病」是不好的事，说拿奖是他最大的疾病，与句意相反。", "伤口": "语义：「伤口」指身体的创伤，与「拿到这个奖」无关，句意不通。", "体温": "搭配：「最大的」可修饰成就、困难等，不能修饰「体温」。"}, "sentence_index": 0, "correct_answer": "成就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的成就很明显。", "explanation": "这里应该用〈功效〉。成就指人做成的事，药物的作用要用〈功效〉。"}, {"text": "这个月他的成就比上个月多了两千块。", "explanation": "这里应该用〈收入〉。成就指做成的事，不能用来计算金钱，表示多了多少钱要用〈收入〉。"}, {"text": "他承认了自己的成就，并向大家道了歉。", "explanation": "这里应该用〈过失〉。成就是做成的好事，不能承认或道歉；承认错误并道歉要用〈过失〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成就", "is_correct": true, "explanation": "正确：「公司今年的成就」指公司做成的事，与「要谢谢大家的努力」相符。"}, {"text": "梦话", "is_correct": false, "explanation": "语义：「梦话」是睡梦中说的话，不是值得感谢的工作成果，句意不通。"}, {"text": "鼾声", "is_correct": false, "explanation": "语义：「鼾声」是睡觉时的呼吸声，不是公司做成的事，句意不通。"}, {"text": "喷嚏", "is_correct": false, "explanation": "语义：「喷嚏」是身体的反应，不是工作成果，与「要谢谢大家的努力」不合。"}], "explanations": {"成就": "正确：「公司今年的成就」指公司做成的事，与「要谢谢大家的努力」相符。", "梦话": "语义：「梦话」是睡梦中说的话，不是值得感谢的工作成果，句意不通。", "鼾声": "语义：「鼾声」是睡觉时的呼吸声，不是公司做成的事，句意不通。", "喷嚏": "语义：「喷嚏」是身体的反应，不是工作成果，与「要谢谢大家的努力」不合。"}, "sentence_index": 6, "correct_answer": "成就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他取得了一本很大的成就。", "explanation": "这里应该用〈项〉。「本」用于书籍，「成就」要用量词「项」。"}, {"text": "她拿到了一把很重要的成就。", "explanation": "这里应该用〈项〉。「把」用于有柄的器具，「成就」要用量词「项」。"}, {"text": "这次比赛我得到了一首大成就。", "explanation": "这里应该用〈项〉。「首」用于诗歌、歌曲，「成就」要用量词「项」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父母为她成就高兴。", "corrected_sentence": "父母为她的成就高兴。", "error_description": "错误在于「她」和「成就」之间漏掉了定语标记「的」，应为「她的成就」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是他最大的一颗成就。", "corrected_sentence": "这是他最大的一项成就。", "error_description": "量词错误：「颗」多用于粒状或球状的小东西，「成就」应用量词「项」，正确写法是「一项成就」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23728, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23728, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "像素是图片上的小点点，很多小点点拼在一起就变成一张图。", "primary_collocate": null, "pronunciation": "xiàng sù", "ipa": "ɕjɑŋ˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "图片上有很多小点，这些小点就是像素。", "target_word": "像素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "像素太少的照片看起来不清楚。", "target_word": "像素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把照片放得很大，就能看到一个个像素。", "target_word": "像素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画是用很多彩色的像素拼成的。", "target_word": "像素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手机相机像素很高，拍的照片很清楚。", "target_word": "像素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个像素只有一种颜色。", "target_word": "像素", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张小图的像素不够，放大了就会模糊。", "target_word": "像素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟在电脑上用像素画了一只小狗。", "target_word": "像素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屏幕上的像素很小，我们用眼睛看不清。", "target_word": "像素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们数一数这张图有多少个像素。", "target_word": "像素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "像素点", "label": "复合"}, {"form": "像素值", "label": "复合"}], "register": "中性", "sense_fingerprint": "图片上的小点，许多小点拼成一张图", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2f2f380-84e6-4cc1-b3ea-516ce01c2dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "像素", "is_correct": true, "explanation": "正确。像素是图片上的小点，许多小点拼在一起形成图像。"}, {"text": "项目", "is_correct": false, "explanation": "声母不同：项目（xiàng mù）与像素只有第二音节声母不同（m 与 s），意思是工作或活动的事项。"}, {"text": "橡树", "is_correct": false, "explanation": "声母不同：橡树（xiàng shù）与像素只有第二音节声母不同（sh 与 s），意思是一种树木。"}, {"text": "限速", "is_correct": false, "explanation": "韵尾不同：限速（xiàn sù）与像素只有第一音节韵尾不同（-n 与 -ng），意思是限制车速。"}], "explanations": {"像素": "正确。像素是图片上的小点，许多小点拼在一起形成图像。", "项目": "声母不同：项目（xiàng mù）与像素只有第二音节声母不同（m 与 s），意思是工作或活动的事项。", "橡树": "声母不同：橡树（xiàng shù）与像素只有第二音节声母不同（sh 与 s），意思是一种树木。", "限速": "韵尾不同：限速（xiàn sù）与像素只有第一音节韵尾不同（-n 与 -ng），意思是限制车速。"}, "sentence_index": null, "correct_answer": "像素"}, "level_3": {"options": [{"text": "像素", "is_correct": true, "explanation": "正确。“这些小点就是像素”与“图片上有很多小点”的语境一致。"}, {"text": "标点", "is_correct": false, "explanation": "语义：标点是文字的符号，与“图片上的小点”无关。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“就是”后接的应是小点可以指代的事物，墨水是液体，不能说小点就是墨水。"}, {"text": "皮肤", "is_correct": false, "explanation": "语义：皮肤是人体组织，与图片上的小点没有关系。"}], "explanations": {"像素": "正确。“这些小点就是像素”与“图片上有很多小点”的语境一致。", "标点": "语义：标点是文字的符号，与“图片上的小点”无关。", "墨水": "搭配：“就是”后接的应是小点可以指代的事物，墨水是液体，不能说小点就是墨水。", "皮肤": "语义：皮肤是人体组织，与图片上的小点没有关系。"}, "sentence_index": 0, "correct_answer": "像素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这袋面粉里有很多细小的像素。", "explanation": "这里应该用〈颗粒〉。像素是数字图像的最小单位，不指面粉中的细小颗粒。"}, {"text": "黑板上留下了几个像素。", "explanation": "这里应该用〈墨点〉。像素只用于数字图像，不指黑板上的墨点。"}, {"text": "这部电影的像素很美。", "explanation": "这里应该用〈画面〉。像素是图像的构成单位，不能用来评价影片的画面美不美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "像素", "is_correct": true, "explanation": "正确。“这张小图的像素不够，放大了就会模糊”指图像的清晰度，与“像素”相符。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量是声音的大小，与图片的清晰度无关，“放大”和“模糊”也不能用于声音。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“放大”和“模糊”只能用于描述图像，不能用于味道。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人的岁数，与图片的清晰度没有关系。"}], "explanations": {"像素": "正确。“这张小图的像素不够，放大了就会模糊”指图像的清晰度，与“像素”相符。", "音量": "语义：音量是声音的大小，与图片的清晰度无关，“放大”和“模糊”也不能用于声音。", "味道": "搭配：“放大”和“模糊”只能用于描述图像，不能用于味道。", "年龄": "语义：年龄是人的岁数，与图片的清晰度没有关系。"}, "sentence_index": 6, "correct_answer": "像素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸上有很多小像素，很难去掉。", "explanation": "这里应该用〈斑点〉。斑点是皮肤上的色斑，像素指图像中的最小点，不指人脸上的斑点。"}, {"text": "衣服上的像素很难洗掉。", "explanation": "这里应该用〈污渍〉。污渍是衣服上洗不掉的脏迹，像素指图像中的最小点，不能用来形容衣服。"}, {"text": "窗玻璃上结了很多像素，看不清外面。", "explanation": "这里应该用〈水珠〉。水珠是玻璃上凝结的小水点，像素不能指窗上结的水点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图片放大以后，能看到很多只像素。", "corrected_sentence": "图片放大以后，能看到很多个像素。", "error_description": "量词错误：像素应用量词“个”，“只”多用于动物。错误形式“很多只像素”，正确形式“很多个像素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屏幕上这些像素们都很小。", "corrected_sentence": "屏幕上这些像素都很小。", "error_description": "“们”只用于指人或拟人化的名词，“像素”是事物，不能加“们”。错误形式“这些像素们”，正确形式“这些像素”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07ddb37a-1479-43aa-b31d-1a56168df47a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23730, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降职", "is_correct": true, "explanation": "降职指职位降低，与晋升的意思相反，是词典所列的反义词。"}, {"text": "散步", "is_correct": false, "explanation": "散步是慢慢走路，与晋升没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫是清理卫生的动作，与晋升没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "研究是探索学问的活动，与晋升没有反义关系。"}], "correct_answer": "降职", "explanations": {"降职": "降职指职位降低，与晋升的意思相反，是词典所列的反义词。", "散步": "散步是慢慢走路，与晋升没有反义关系。", "打扫": "打扫是清理卫生的动作，与晋升没有反义关系。", "研究": "研究是探索学问的活动，与晋升没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23730, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降职", "is_correct": true, "explanation": "降职指职位降低，与晋升的意思相反，是词典所列的反义词。"}, {"text": "烹饪", "is_correct": false, "explanation": "烹饪是做饭的动作，与晋升没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运是搬动物品的动作，与晋升没有反义关系。"}, {"text": "赞美", "is_correct": false, "explanation": "赞美是称赞别人，与晋升没有反义关系。"}], "correct_answer": "降职", "explanations": {"降职": "降职指职位降低，与晋升的意思相反，是词典所列的反义词。", "烹饪": "烹饪是做饭的动作，与晋升没有反义关系。", "搬运": "搬运是搬动物品的动作，与晋升没有反义关系。", "赞美": "赞美是称赞别人，与晋升没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23730, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "晋升就是一个人得到更好的工作或更高的位置。", "primary_collocate": null, "pronunciation": "jìn shēng", "ipa": "tɕin˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "老李晋升后，搬进了大办公室。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈今天很高兴，因为她晋升了。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他希望早点晋升，赚更多钱。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过努力，小张终于晋升为组长。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她工作认真，很快就晋升了。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们都祝贺他晋升。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在银行晋升得很快。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的员工很容易晋升。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有晋升，心里有点难过。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了晋升，每天加班到很晚。", "target_word": "晋升", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晋升了", "label": "体标"}, {"form": "晋升过", "label": "体标"}, {"form": "晋升为", "label": "补语"}], "register": "中性", "sense_fingerprint": "一个人得到更好的工作或更高的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a504ff71-c661-4a1d-b12d-34e4e5063915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "语义：感冒是生病，与“搬进大办公室”没有关联，句意不通。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：失眠是睡眠问题，与搬进大办公室的结果无关。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽后搬进大办公室”没有合理的先后关系，搭配不当。"}, {"text": "晋升", "is_correct": true, "explanation": "晋升指得到更好的工作或位置，“晋升后搬进大办公室”符合句意。"}], "explanations": {"感冒": "语义：感冒是生病，与“搬进大办公室”没有关联，句意不通。", "失眠": "语义：失眠是睡眠问题，与搬进大办公室的结果无关。", "咳嗽": "搭配：“咳嗽后搬进大办公室”没有合理的先后关系，搭配不当。", "晋升": "晋升指得到更好的工作或位置，“晋升后搬进大办公室”符合句意。"}, "sentence_index": 0, "correct_answer": "晋升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱晋升了。", "explanation": "这里应该用〈升级〉。晋升只用于人或组织的职位和等级，冰箱的功能要说“升级”。"}, {"text": "这瓶水的温度晋升了。", "explanation": "这里应该用〈升高〉。晋升用于人的职位或等级，温度要说“升高”。"}, {"text": "这块地的价格晋升了。", "explanation": "这里应该用〈上涨〉。晋升用于职位和等级，价格要说“上涨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迟到", "is_correct": false, "explanation": "语义：“迟到得很快”说不通，迟到与工作升迁无关。"}, {"text": "打针", "is_correct": false, "explanation": "语义：打针没有快慢的升迁含义，句意不通。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”不能用于“在银行……得很快”的语境，搭配不当。"}, {"text": "晋升", "is_correct": true, "explanation": "晋升指职位向上提升，“在银行晋升得很快”符合句意。"}], "explanations": {"迟到": "语义：“迟到得很快”说不通，迟到与工作升迁无关。", "打针": "语义：打针没有快慢的升迁含义，句意不通。", "发烧": "搭配：“发烧”不能用于“在银行……得很快”的语境，搭配不当。", "晋升": "晋升指职位向上提升，“在银行晋升得很快”符合句意。"}, "sentence_index": 6, "correct_answer": "晋升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的收入晋升了一千元。", "explanation": "这里应该用〈增加〉。晋升用于职位和等级，收入要说“增加”，也不能用“元”来计量晋升。"}, {"text": "她的年龄晋升了。", "explanation": "这里应该用〈增长〉。晋升用于职位和等级，年龄要说“增长”。"}, {"text": "她的车速晋升了。", "explanation": "这里应该用〈提高〉。晋升用于职位和等级，车速要说“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老王终于晋升着总监。", "corrected_sentence": "老王终于晋升为总监。", "error_description": "错误形式“晋升着”，正确形式“晋升为”。“晋升”后接职位要用补语“为”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我希望下个月能晋升过。", "corrected_sentence": "我希望下个月能晋升。", "error_description": "体标用错：“过”表示过去的经历，不能用于“希望下个月”这种将来的事，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
