INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人或事物在列表中的位置顺序。", "primary_collocate": null, "pronunciation": "pái míng", "ipa": "pʰaɪ˧˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "名单上他的排名在第二位。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看这家饭店的排名。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站上的排名每天都会变。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个歌手的排名下降了。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子很在意自己的排名。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的排名比去年高了三位。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机游戏里有玩家的排名。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你们队的排名。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排名最后的同学要加油。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，排名马上出来了。", "target_word": "排名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排名表", "label": "复合"}, {"form": "总排名", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或事物在榜单中的先后位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a504ff71-c661-4a1d-b12d-34e4e5063915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是可以排列名单的事物，“在第二位”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有名次，名单上不会排颜色。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是外形，不会在名单上排出名次。"}, {"text": "排名", "is_correct": true, "explanation": "排名指在名单中的位置顺序，“在第二位”与之相符，符合句意。"}], "explanations": {"年龄": "语义：年龄不是可以排列名单的事物，“在第二位”说不通。", "颜色": "语义：颜色没有名次，名单上不会排颜色。", "身材": "体貌：身材是外形，不会在名单上排出名次。", "排名": "排名指在名单中的位置顺序，“在第二位”与之相符，符合句意。"}, "sentence_index": 0, "correct_answer": "排名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个歌手的排名下降了五公斤。", "explanation": "这里应该用〈体重〉。排名是位置，不能用“公斤”计量。"}, {"text": "这个歌手的排名是三十岁。", "explanation": "这里应该用〈年龄〉。排名表示位置，不能说明年龄。"}, {"text": "这个歌手的排名在台上唱歌。", "explanation": "这里应该用〈人〉作主语。排名表示位置，不能做“唱歌”的主语，唱歌要求主语是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：温度不是玩家在游戏中可排列的属性，句子说不通。"}, {"text": "作息", "is_correct": false, "explanation": "搭配：“作息”指人的起居习惯，与游戏里的排列次序不搭。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温没有先后次序，不能用于手机游戏中的排列。"}, {"text": "排名", "is_correct": true, "explanation": "排名指在榜单中的位置，符合手机游戏的语境。"}], "explanations": {"温度": "语义：温度不是玩家在游戏中可排列的属性，句子说不通。", "作息": "搭配：“作息”指人的起居习惯，与游戏里的排列次序不搭。", "体温": "语义：体温没有先后次序，不能用于手机游戏中的排列。", "排名": "排名指在榜单中的位置，符合手机游戏的语境。"}, "sentence_index": 6, "correct_answer": "排名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛结束后，排名定在了周六。", "explanation": "这里应该用〈日期〉。排名是位置，不能“定在”某一天。"}, {"text": "这盆花的排名很香。", "explanation": "这里应该用有香气的事物作主语，如〈饭菜〉。排名表示位置，没有气味，不能说“很香”。"}, {"text": "他的排名会游泳。", "explanation": "这里应该用〈人〉作主语。“会游泳”要求主语能游泳，排名不是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书的排名在三位。", "corrected_sentence": "这本书的排名在第三位。", "error_description": "错误形式“在三位”，正确形式“在第三位”。说排名的位置时，数字前要加“第”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的排名在一位。", "corrected_sentence": "他的排名在第一位。", "error_description": "错误形式“在一位”，正确形式“在第一位”。表示名次的序数要带“第”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23738, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表面", "is_correct": true, "explanation": "“表面”指外在的样子，与“实质”指根本内容相对。"}, {"text": "价格", "is_correct": false, "explanation": "“价格”指商品的价值用钱衡量，与“实质”没有反义关系。"}, {"text": "速度", "is_correct": false, "explanation": "“速度”指快慢的程度，与“实质”没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "“天气”指一定时间内的冷暖阴晴，与“实质”没有反义关系。"}], "correct_answer": "表面", "explanations": {"表面": "“表面”指外在的样子，与“实质”指根本内容相对。", "价格": "“价格”指商品的价值用钱衡量，与“实质”没有反义关系。", "速度": "“速度”指快慢的程度，与“实质”没有反义关系。", "天气": "“天气”指一定时间内的冷暖阴晴，与“实质”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
