INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23738, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "实质就是事情最重要的部分。", "primary_collocate": null, "pronunciation": "shí zhì", "ipa": "ʂɨ˧˥ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这件事的实质是钱的问题。", "target_word": "实质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要看到问题的实质。", "target_word": "实质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一句话就说出了事情的实质。", "target_word": "实质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种说法看起来不同，实质是一样的。", "target_word": "实质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮我看清了这个问题的实质。", "target_word": "实质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次争论的实质是看法不同。", "target_word": "实质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别只看外面，要想想它的实质。", "target_word": "实质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个办法的实质并没有变。", "target_word": "实质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有明白这句话的实质。", "target_word": "实质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架的实质是什么？", "target_word": "实质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "实质性", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物最根本、最重要的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61123057-4989-4a95-82bf-725897152c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23738, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实质", "is_correct": true, "explanation": "正确答案“实质”shí zhì，意思是事物最根本、最重要的内容。"}, {"text": "食指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是食指。"}, {"text": "试制", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是试制。"}, {"text": "失智", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是认知能力下降。"}], "explanations": {"实质": "正确答案“实质”shí zhì，意思是事物最根本、最重要的内容。", "食指": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是食指。", "试制": "shì（第四声）与 shí（第二声）声调不同，意思是试制。", "失智": "shī（第一声）与 shí（第二声）声调不同，意思是认知能力下降。"}, "sentence_index": null, "correct_answer": "实质"}, "level_3": {"options": [{"text": "实质", "is_correct": true, "explanation": "“实质”指事物根本的内容，与“是钱的问题”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是外在的视觉属性，与“是钱的问题”意思不合。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积指占的空间大小，与句意无关。"}, {"text": "外表", "is_correct": false, "explanation": "搭配：“外表”指外在样子，不能用来说明“是……问题”。"}], "explanations": {"实质": "“实质”指事物根本的内容，与“是钱的问题”搭配，符合句意。", "颜色": "语义：颜色是外在的视觉属性，与“是钱的问题”意思不合。", "体积": "语义：体积指占的空间大小，与句意无关。", "外表": "搭配：“外表”指外在样子，不能用来说明“是……问题”。"}, "sentence_index": 0, "correct_answer": "实质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的实质很厚。", "explanation": "这里应该用〈书页〉。“实质”指根本的内容，不能描述厚薄。"}, {"text": "空气是一种实质。", "explanation": "这里应该用〈物质〉。“实质”指事物根本的内容，不是可见的物体，说空气要用“物质”。"}, {"text": "这间屋子的实质很亮。", "explanation": "这里应该用〈灯光〉。“实质”指根本的内容，不能描述光线明暗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实质", "is_correct": true, "explanation": "“实质”指根本的内容，与“别只看外面，要想想它的”搭配，符合句意。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量指声音的大小，与“别只看外面”的语境不合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是具体物品，与“想想它的……”所指的根本内容不合。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”指走路的步子，一般用于人，不能说“它的脚步”。"}], "explanations": {"实质": "“实质”指根本的内容，与“别只看外面，要想想它的”搭配，符合句意。", "音量": "语义：音量指声音的大小，与“别只看外面”的语境不合。", "书包": "语义：“书包”是具体物品，与“想想它的……”所指的根本内容不合。", "脚步": "搭配：“脚步”指走路的步子，一般用于人，不能说“它的脚步”。"}, "sentence_index": 6, "correct_answer": "实质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把实质放进了包里。", "explanation": "这里应该用〈东西〉。“实质”是抽象的根本内容，不能像具体物品那样放进包里。"}, {"text": "他们吵架的实质在操场上。", "explanation": "这里应该用〈地点〉。“实质”不表示空间位置，说吵架的场所要用“地点”。"}, {"text": "他的实质有一米八。", "explanation": "这里应该用〈身高〉。“实质”不能用来表示身高或身材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了这个问题的一本实质。", "corrected_sentence": "我找到了这个问题的实质。", "error_description": "“实质”是抽象名词，不能用量词“本”，应直接说“问题的实质”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一眼就看透了这件事的实质的。", "corrected_sentence": "他一眼就看透了这件事的实质。", "error_description": "末尾多出的“的”没有中心语，句子不完整；“这件事的实质”中的“的”已连接定语，不应再加。应说“看透了这件事的实质”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23740, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "正确：“信任”与“怀疑”互为反义：一个是相信对方不会骗自己，一个是不相信。"}, {"text": "帮助", "is_correct": false, "explanation": "帮助与信任没有反义关系，不能与“信任”构成对立。"}, {"text": "感谢", "is_correct": false, "explanation": "感谢与信任没有对立关系，不构成反义词。"}, {"text": "批评", "is_correct": false, "explanation": "批评与信任没有反义关系，句意上并不相对。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "正确：“信任”与“怀疑”互为反义：一个是相信对方不会骗自己，一个是不相信。", "帮助": "帮助与信任没有反义关系，不能与“信任”构成对立。", "感谢": "感谢与信任没有对立关系，不构成反义词。", "批评": "批评与信任没有反义关系，句意上并不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
