INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23740, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "相信别人不会骗自己。", "primary_collocate": null, "pronunciation": "xìn rèn", "ipa": "ɕin⁵¹ ɻən⁵¹", "syllable_count": 2, "sentences": [{"text": "我很信任我的朋友。", "target_word": "信任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不信任陌生人。", "target_word": "信任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子信任父母，什么事都告诉他们。", "target_word": "信任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人都信任这位医生。", "target_word": "信任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她骗过我一次，我再也不信任她了。", "target_word": "信任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板信任他，把钱交给他管。", "target_word": "信任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以信任我，我不会说出去。", "target_word": "信任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是个值得信任的人。", "target_word": "信任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们不能轻易信任网上的陌生人。", "target_word": "信任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师信任学生，考试时不在教室。", "target_word": "信任", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "信任过", "label": "体标"}, {"form": "不信任", "label": "复合"}], "register": "中性", "sense_fingerprint": "相信别人不会骗自己", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23740, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信任", "is_correct": true, "explanation": "正确：“我很信任我的朋友”表示相信朋友不会骗自己。"}, {"text": "通过", "is_correct": false, "explanation": "配价：“通过”要带方式、考试、方案等宾语，不能直接带人。"}, {"text": "取消", "is_correct": false, "explanation": "配价：“取消”的对象是活动、计划，不能取消一个人。"}, {"text": "报名", "is_correct": false, "explanation": "搭配：“报名”是离合词，后面不能直接带人作宾语。"}], "explanations": {"信任": "正确：“我很信任我的朋友”表示相信朋友不会骗自己。", "通过": "配价：“通过”要带方式、考试、方案等宾语，不能直接带人。", "取消": "配价：“取消”的对象是活动、计划，不能取消一个人。", "报名": "搭配：“报名”是离合词，后面不能直接带人作宾语。"}, "sentence_index": 0, "correct_answer": "信任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我信任明天会下雨。", "explanation": "这里应该用〈相信〉。信任针对可靠的人，不能接一件事情或一个判断。"}, {"text": "他信任佛教，每周都去寺庙。", "explanation": "这里应该用〈信仰〉。信任是对人可靠的相信，对宗教、主义要用“信仰”。"}, {"text": "他对自己的能力很有信任。", "explanation": "这里应该用〈信心〉。信任是对别人可靠的相信，对自己的能力有把握要用“信心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信任", "is_correct": true, "explanation": "正确：“你可以信任我，我不会说出去”表示你可以相信我。"}, {"text": "推迟", "is_correct": false, "explanation": "配价：“推迟”的对象是时间、计划，不能推迟一个人。"}, {"text": "撤销", "is_correct": false, "explanation": "语义：“撤销”的对象是决定、命令，不能撤销人，句意不通。"}, {"text": "收费", "is_correct": false, "explanation": "语法：“收费”是离合结构，后面不能直接带“我”作宾语，“你可以收费我”不成句。"}], "explanations": {"信任": "正确：“你可以信任我，我不会说出去”表示你可以相信我。", "推迟": "配价：“推迟”的对象是时间、计划，不能推迟一个人。", "撤销": "语义：“撤销”的对象是决定、命令，不能撤销人，句意不通。", "收费": "语法：“收费”是离合结构，后面不能直接带“我”作宾语，“你可以收费我”不成句。"}, "sentence_index": 6, "correct_answer": "信任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们信任这次旅行。", "explanation": "这里应该用〈期待〉。信任用于人和可靠的对象，对事情的盼望要用“期待”。"}, {"text": "我们信任失败。", "explanation": "这里应该用〈接受〉。信任的对象是可靠的人，面对失败这样的结果要说“接受失败”。"}, {"text": "我信任他有罪。", "explanation": "这里应该用〈认定〉。信任是相信人的可靠，判断某人有罪要用“认定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该信任地父母。", "corrected_sentence": "我们应该信任父母。", "error_description": "错误形式：“信任地父母”。正确形式：“信任父母”。“地”是状语标记，不能放在“信任”和“父母”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从没信任了他。", "corrected_sentence": "我从没信任过他。", "error_description": "错误形式：“从没信任了他”。正确形式：“从没信任过他”。“没”否定的经历要配“过”，“没……了”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西给别人看，让大家看到。", "primary_collocate": null, "pronunciation": "zhǎn xiàn", "ipa": "tʂan˨˩ ɕi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这次展览把艺术家的独特风格完整展现给观众。", "target_word": "展现", "complexity_tier": "T3", "furigana": "zhè cì zhǎn lǎn bǎ yì shù jiā de dú tè fēng gé wán zhěng zhǎn xiàn gěi guān zhòng", "sentence_source": "generated"}, {"text": "新车发布会上，厂商完整展现了这款车的设计理念。", "target_word": "展现", "complexity_tier": "T3", "furigana": "xīn chē fā bù huì shàng, chǎng shāng wán zhěng zhǎn xiàn le zhè kuǎn chē de shè jì lǐ niàn", "sentence_source": "generated"}, {"text": "舞台的幕布一拉开，展现在观众面前的是一座花园。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位设计师在秀场上展现了新品的独特风格。", "target_word": "展现", "complexity_tier": "T3", "furigana": "zhè wèi shè jì shī zài xiù chǎng shàng zhǎn xiàn le xīn pǐn de dú tè fēng gé", "sentence_source": "generated"}, {"text": "展览会上，策展人把城市的历史风貌展现给参观者。", "target_word": "展现", "complexity_tier": "T3", "furigana": "zhǎn lǎn huì shàng, cè zhǎn rén bǎ chéng shì de lì shǐ fēng mào zhǎn xiàn gěi cān guān zhě", "sentence_source": "generated"}, {"text": "他的新招数终于展现出来，让大家眼前一亮。", "target_word": "展现", "complexity_tier": "T3", "furigana": "tā de xīn zhāo shù zhōng yú zhǎn xiàn chū lái, ràng dà jiā yǎn qián yí liàng", "sentence_source": "generated"}, {"text": "店员在柜台前把手机的新功能展现在客人面前。", "target_word": "展现", "complexity_tier": "T3", "furigana": "diàn yuán zài guì tái qián bǎ shǒu jī de xīn gōng néng zhǎn xiàn zài kè rén miàn qián", "sentence_source": "generated"}, {"text": "她在朋友面前展现了自己的绘画风格，大家都很赞赏。", "target_word": "展现", "complexity_tier": "T3", "furigana": "tā zài péng yǒu miàn qián zhǎn xiàn le zì jǐ de huì huà fēng gé, dà jiā dōu hěn zàn shǎng", "sentence_source": "generated"}, {"text": "窗帘一拉开，展现在眼前的是大海。", "target_word": "展现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课堂上展现了自己的创意，老师很满意。", "target_word": "展现", "complexity_tier": "T3", "furigana": "hái zi men zài kè táng shàng zhǎn xiàn le zì jǐ de chuàng yì, lǎo shī hěn mǎn yì", "sentence_source": "generated"}], "morphological_forms": [{"form": "展现了", "label": "体标"}, {"form": "展现着", "label": "体标"}, {"form": "展现过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把具体的东西或抽象的风格、创意等摆出来、露出来或呈现出来，让大家看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b2369b-e895-4499-98cc-06ea7bf3828e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "展现", "is_correct": true, "explanation": "正确答案：展现（zhǎn xiàn），意思是把东西摆出来让大家看到。"}, {"text": "占线", "is_correct": false, "explanation": "zhàn（第四声）与 zhǎn 声调不同，意思是电话或线路被占用、忙线。"}, {"text": "战线", "is_correct": false, "explanation": "zhàn（第四声）与 zhǎn 声调不同，意思是作战的前沿阵地。"}, {"text": "产线", "is_correct": false, "explanation": "chǎn（第三声）与 zhǎn 声母不同（ch 与 zh），意思是生产线。"}], "explanations": {"展现": "正确答案：展现（zhǎn xiàn），意思是把东西摆出来让大家看到。", "占线": "zhàn（第四声）与 zhǎn 声调不同，意思是电话或线路被占用、忙线。", "战线": "zhàn（第四声）与 zhǎn 声调不同，意思是作战的前沿阵地。", "产线": "chǎn（第三声）与 zhǎn 声母不同（ch 与 zh），意思是生产线。"}, "sentence_index": null, "correct_answer": "展现"}, "level_3": {"options": [{"text": "展现", "is_correct": true, "explanation": "正确：展现表示把东西摆出来让观众看，与“风格”和“给观众”搭配。"}, {"text": "借给", "is_correct": false, "explanation": "语义：风格不是可以借出的物品，“借给观众”与句意不符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理的对象是器物，不能修理“风格”，也不与“给观众”搭配。"}, {"text": "购买", "is_correct": false, "explanation": "配价：购买的宾语是商品，不带与事“给观众”，“购买……给观众”不成立。"}], "explanations": {"展现": "正确：展现表示把东西摆出来让观众看，与“风格”和“给观众”搭配。", "借给": "语义：风格不是可以借出的物品，“借给观众”与句意不符。", "修理": "搭配：修理的对象是器物，不能修理“风格”，也不与“给观众”搭配。", "购买": "配价：购买的宾语是商品，不带与事“给观众”，“购买……给观众”不成立。"}, "sentence_index": 0, "correct_answer": "展现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位设计师在秀场上展现了一次演讲。", "explanation": "这里应用“发表”。“展现”指把具体物品或作品摆出来让人看，演讲是一种活动，要说“发表”，不能用“展现”。"}, {"text": "这位设计师在秀场上展现了一顿饭。", "explanation": "这里应用“准备”。“展现”指把具体物品或作品摆出来让人看，做饭要说“准备”或“做”，不能用“展现”。"}, {"text": "这个月的销量展现了不少。", "explanation": "这里应用“增加”。“展现”用于把具体物品或作品摆出来让人看，销量的增减要用“增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展现", "is_correct": true, "explanation": "正确：展现表示把具体东西摆出来让人看，与“在客人面前”搭配。"}, {"text": "拆卸", "is_correct": false, "explanation": "搭配：“拆卸”的对象是有形器物，新功能不能被拆卸，句意不通。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”的对象是食物，手机的新功能不能被吃掉。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”的对象是有形的器物，功能不能被打碎。"}], "explanations": {"展现": "正确：展现表示把具体东西摆出来让人看，与“在客人面前”搭配。", "拆卸": "搭配：“拆卸”的对象是有形器物，新功能不能被拆卸，句意不通。", "吃掉": "语义：“吃掉”的对象是食物，手机的新功能不能被吃掉。", "打碎": "搭配：“打碎”的对象是有形的器物，功能不能被打碎。"}, "sentence_index": 6, "correct_answer": "展现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次改革展现了成本。", "explanation": "这里应用“降低”。“展现”用于把东西摆出来让人看，成本的变化要用“降低”。"}, {"text": "这次会议展现了一个小时。", "explanation": "这里应用“延长”。“展现”不指时间的增加，会议时长的变化要用“延长”。"}, {"text": "孩子们的成绩展现了很多。", "explanation": "这里应用“增长”。“展现”不用于成绩等数量的增加，要用“增长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "馆方这批古代陶器完整展现出来。", "corrected_sentence": "馆方把这批古代陶器完整展现出来。", "error_description": "错误形式：“馆方这批古代陶器完整展现出来”。正确形式：“馆方把这批古代陶器完整展现出来”。宾语“这批古代陶器”前须用“把”提到动词前，直接并列则不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把这张地图完整展现全班同学。", "corrected_sentence": "老师把这张地图完整展现给全班同学。", "error_description": "错误形式：“展现全班同学”。正确形式：“展现给全班同学”。“展现”引出接受对象要用“给”，漏掉“给”则不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
