INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能提前知道以后会发生什么。", "primary_collocate": null, "pronunciation": "yù jiàn xìng", "ipa": "y˥˩ tɕjɛn˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他很有预见性，知道明天会下雨。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有预见性的人能提前做好准备。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的预见性很强，早就带了伞。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的预见性真好，一切都让你说中了。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意没有预见性，很容易亏钱。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师对学生的未来很有预见性。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "预见性不是天生的，要多看多想。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的预见性让大家都很吃惊。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有预见性，不知道会发生这样的事。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提高预见性，要先了解事情的变化。", "target_word": "预见性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预见", "label": "词根"}], "register": "中性", "sense_fingerprint": "预见性|名词|能提前知道以后会发生什么的本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b2369b-e895-4499-98cc-06ea7bf3828e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预见性", "is_correct": true, "explanation": "正确。“很有预见性”指能提前知道事情的本领，与“知道明天会下雨”相合。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很有”后面不能接“身高”，句子不通。"}, {"text": "脸色", "is_correct": false, "explanation": "语义：“脸色”指面部的神情或颜色，与“知道明天会下雨”无关。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“很有”后面不接“价格”，句子不通。"}], "explanations": {"预见性": "正确。“很有预见性”指能提前知道事情的本领，与“知道明天会下雨”相合。", "身高": "搭配：“很有”后面不能接“身高”，句子不通。", "脸色": "语义：“脸色”指面部的神情或颜色，与“知道明天会下雨”无关。", "价格": "搭配：“很有”后面不接“价格”，句子不通。"}, "sentence_index": 0, "correct_answer": "预见性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈养成了早睡的预见性。", "explanation": "这里应该用〈习惯〉。“养成”后接“习惯”，早睡是生活习惯，不是对未来的预判，不能说“早睡的预见性”。"}, {"text": "我的预见性是音乐。", "explanation": "这里应该用〈爱好〉。“爱好”指喜欢做的事，“预见性”是预判未来的本领，不能指音乐这件事。"}, {"text": "他有一条很好的预见性。", "explanation": "这里应该用〈种〉。〈条〉用于细长的东西，“预见性”是抽象名词，不能用〈条〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预见性", "is_correct": true, "explanation": "正确。“预见性”是能提前知道以后会发生什么的本领，可以通过多看多想培养。"}, {"text": "脸型", "is_correct": false, "explanation": "体貌：“脸型”指面部的外形，不是可以通过多看多想获得的。"}, {"text": "味觉", "is_correct": false, "explanation": "语义：“味觉”是辨别滋味的感觉，不能靠“多看多想”获得。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，与“多看多想”无关。"}], "explanations": {"预见性": "正确。“预见性”是能提前知道以后会发生什么的本领，可以通过多看多想培养。", "脸型": "体貌：“脸型”指面部的外形，不是可以通过多看多想获得的。", "味觉": "语义：“味觉”是辨别滋味的感觉，不能靠“多看多想”获得。", "体重": "语义：“体重”是身体的重量，与“多看多想”无关。"}, "sentence_index": 6, "correct_answer": "预见性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的预见性很漂亮。", "explanation": "这里应该用〈长相〉。“长相”指外貌，“预见性”是对未来的预判能力，不能用“很漂亮”形容。"}, {"text": "我家的预见性是北京。", "explanation": "这里应该用〈地址〉。“地址”指住所的位置，“预见性”不能表示地点。"}, {"text": "这辆车的预见性是红色的。", "explanation": "这里应该用〈颜色〉。“颜色”指物体的色彩，“预见性”不能指车的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的预见性强很，每次都能提前准备。", "corrected_sentence": "他的预见性很强，每次都能提前准备。", "error_description": "“很”要放在形容词前。应说“预见性很强”，不能说“预见性强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师有一把很强的预见性。", "corrected_sentence": "这位老师有一种很强的预见性。", "error_description": "量词错误：“把”多用于有柄的物件，不用于抽象的“预见性”，应用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
