INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "技巧是做好事情的好方法。", "primary_collocate": null, "pronunciation": "jì qiǎo", "ipa": "tɕi˥˩ tɕʰiɑu̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本书教你学习英语的技巧。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学一些省钱的小技巧。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟客人说话需要沟通技巧。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，掌握答题技巧很重要。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他告诉我一个记单词的好技巧。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭有很多小技巧，比如先把水烧开。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会这些技巧，你工作会更轻松。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试有一些技巧，你可以问问老师。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个视频讲了拍照的几个技巧。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有自己的学习技巧。", "target_word": "技巧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "技巧性", "label": "复合词"}], "register": "中性", "sense_fingerprint": "技巧|名词|做好日常事情的小窍门和好方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b2369b-e895-4499-98cc-06ea7bf3828e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技巧", "is_correct": true, "explanation": "正确。“学习英语的技巧”指学好英语的好方法，书可以教。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指身体的外形，与“学习英语”无关，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不是书可以教的学习内容。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指事物的色彩，不是可以学习的内容。"}], "explanations": {"技巧": "正确。“学习英语的技巧”指学好英语的好方法，书可以教。", "身材": "体貌：“身材”指身体的外形，与“学习英语”无关，句意不通。", "价格": "语义：“价格”指钱数，不是书可以教的学习内容。", "颜色": "语义：“颜色”指事物的色彩，不是可以学习的内容。"}, "sentence_index": 0, "correct_answer": "技巧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的技巧是一米六。", "explanation": "这里应该用〈身高〉。“身高”指身体的高度，“技巧”不能用来表示身高。"}, {"text": "她是我最好的技巧。", "explanation": "这里应该用〈朋友〉。“朋友”指关系亲近的人，“技巧”指做事的方法，不能用来指人。"}, {"text": "他告诉我一颗好技巧。", "explanation": "这里应该用〈个〉或〈种〉。〈颗〉用于小而圆的东西，“技巧”不能用〈颗〉来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技巧", "is_correct": true, "explanation": "正确。“学会这些技巧”指学会做好工作的好方法，与“工作会更轻松”相合。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“学会”的宾语应是知识或方法，“房子”不能学会。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是戴在脸上的物件，不是可以学会的东西，句意不通。"}, {"text": "广告", "is_correct": false, "explanation": "语义：“广告”是宣传信息，不是可以学会的方法，与“工作更轻松”无关。"}], "explanations": {"技巧": "正确。“学会这些技巧”指学会做好工作的好方法，与“工作会更轻松”相合。", "房子": "搭配：“学会”的宾语应是知识或方法，“房子”不能学会。", "眼镜": "语义：“眼镜”是戴在脸上的物件，不是可以学会的东西，句意不通。", "广告": "语义：“广告”是宣传信息，不是可以学会的方法，与“工作更轻松”无关。"}, "sentence_index": 6, "correct_answer": "技巧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的技巧是红色的。", "explanation": "这里应该用〈颜色〉。“颜色”指物体的色彩，“技巧”是做事的方法，不能指车的颜色。"}, {"text": "他的技巧是六十公斤。", "explanation": "这里应该用〈体重〉。“体重”指人的重量，“技巧”不能表示重量。"}, {"text": "我的技巧是小明。", "explanation": "这里应该用〈名字〉。“名字”是人的称呼，“技巧”不能用来指人名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈教我一本省时间的好技巧。", "corrected_sentence": "妈妈教我一个省时间的好技巧。", "error_description": "量词错误：“技巧”应用“个”或“种”，“本”用于书籍，不能修饰“技巧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这个技巧练很熟了。", "corrected_sentence": "我把这个技巧练熟了。", "error_description": "错误：“很”不能用在结果补语“熟”前。应去掉“很”，说“练熟了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
