INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23752, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人或东西做了多少帮助，可以数出来。", "primary_collocate": null, "pronunciation": "gòng xiàn dù", "ipa": "kʊŋ⁵¹ ɕjɛn⁵¹ tu⁵¹", "syllable_count": 3, "sentences": [{"text": "老板用表格记下每个人的贡献度。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的贡献度是百分之三十。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月，小王的贡献度排第一。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先算一算每个人的贡献度。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作做得多，贡献度就高。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对团队的贡献度很大。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁的贡献度最大，谁先拿奖品。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贡献度可以用分数来看。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们对每个人的贡献度都很清楚。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图显示了三个人的贡献度。", "target_word": "贡献度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "所做帮助的多少，可以用数字计算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57e7b389-1948-4f3e-a521-8d2fc34cfc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贡献度", "is_correct": true, "explanation": "正确。“记下每个人的贡献度”指记录每人所做帮助的多少，可以数出来，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用来计算帮助的多少，表格里不会记录每人的“颜色”，句子不通。"}, {"text": "时速", "is_correct": false, "explanation": "语义：时速是速度，用于交通工具，不能用来衡量个人所做的帮助。"}, {"text": "晚霞", "is_correct": false, "explanation": "语义：晚霞是天空中的景色，不属于某个人，也不能用表格记下每个人的晚霞。"}], "explanations": {"贡献度": "正确。“记下每个人的贡献度”指记录每人所做帮助的多少，可以数出来，与句意相符。", "颜色": "语义：颜色不能用来计算帮助的多少，表格里不会记录每人的“颜色”，句子不通。", "时速": "语义：时速是速度，用于交通工具，不能用来衡量个人所做的帮助。", "晚霞": "语义：晚霞是天空中的景色，不属于某个人，也不能用表格记下每个人的晚霞。"}, "sentence_index": 0, "correct_answer": "贡献度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给大家提供了很多贡献度。", "explanation": "这里应该用〈帮助〉。“提供”搭配帮助、服务，贡献度表示帮助多少的程度，不能说“提供贡献度”。"}, {"text": "他立下了大贡献度。", "explanation": "这里应该用〈功劳〉。“立下”搭配功劳，贡献度是程度，不能说“立下大贡献度”。"}, {"text": "他在大会上做了一个贡献度。", "explanation": "这里应该用〈报告〉。“做”搭配报告、发言，“贡献度”表示程度，不能作“做”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贡献度", "is_correct": true, "explanation": "正确。“谁的贡献度最大，谁先拿奖品”指按所做帮助的多少来奖励，与句意相符。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步不是可以计算的帮助量，也不能用“最大”来比较，与奖品的语境不符。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是类别，没有大小之分，不能说“最大”，句子不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材通常说“好”或“高”，说“最大”不自然，且与拿奖品的语境不搭。"}], "explanations": {"贡献度": "正确。“谁的贡献度最大，谁先拿奖品”指按所做帮助的多少来奖励，与句意相符。", "脚步": "语义：脚步不是可以计算的帮助量，也不能用“最大”来比较，与奖品的语境不符。", "血型": "语义：血型是类别，没有大小之分，不能说“最大”，句子不通。", "身材": "体貌：身材通常说“好”或“高”，说“最大”不自然，且与拿奖品的语境不搭。"}, "sentence_index": 6, "correct_answer": "贡献度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一口气吃掉了一大碗贡献度。", "explanation": "这里应该用〈饭〉。“吃”搭配饭菜，“贡献度”是抽象的程度，不能被吃。"}, {"text": "他承受了很大贡献度。", "explanation": "这里应该用〈压力〉。“承受”搭配压力、痛苦，不能说“承受贡献度”。"}, {"text": "他在会议上发表了贡献度。", "explanation": "这里应该用〈意见〉。“发表”搭配意见、文章，贡献度表示程度，不能被发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次项目中，他的贡献度很最高。", "corrected_sentence": "这次项目中，他的贡献度最高。", "error_description": "“很”和“最”都是程度副词，不能同时修饰“高”。应只用“最”，说“贡献度最高”，不能说“贡献度很最高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的贡献度比我的很高。", "corrected_sentence": "他的贡献度比我的高。", "error_description": "用“比”比较时，形容词前不能加“很”，应说“他的贡献度比我的高”；如要表示差得多，可说“高得多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得某人或某物是好的、对的。", "primary_collocate": null, "pronunciation": "rèn kě", "ipa": "ɻən⁵¹ kʰɤ²¹⁴", "syllable_count": 2, "sentences": [{"text": "妈妈认可我选的专业。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认可他说的话。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法，大家都认可。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师认可了我的答案。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客认可这个牌子的质量。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少认可别人的做法。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还不太认可这个计划。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸认可过我的决定。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你认可这个价格吗？", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她认可朋友的意见，决定改一改。", "target_word": "认可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认可了", "label": "完成体"}, {"form": "认可过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "觉得某人或某物好、对而表示接受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57e7b389-1948-4f3e-a521-8d2fc34cfc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认可", "is_correct": true, "explanation": "“认可”表示妈妈接受并肯定我选的专业，与句意相符。"}, {"text": "解剖", "is_correct": false, "explanation": "语义：“解剖”指切开生物体进行研究，与对专业的态度毫无关系。"}, {"text": "砍伐", "is_correct": false, "explanation": "配价：“砍伐”要求以树木等作宾语，不能以专业作宾语。"}, {"text": "熨烫", "is_correct": false, "explanation": "语义：“熨烫”指用熨斗整理衣物，用来形容妈妈对专业的态度读不通。"}], "explanations": {"认可": "“认可”表示妈妈接受并肯定我选的专业，与句意相符。", "解剖": "语义：“解剖”指切开生物体进行研究，与对专业的态度毫无关系。", "砍伐": "配价：“砍伐”要求以树木等作宾语，不能以专业作宾语。", "熨烫": "语义：“熨烫”指用熨斗整理衣物，用来形容妈妈对专业的态度读不通。"}, "sentence_index": 0, "correct_answer": "认可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我认可这个想法很糟糕，不值得再讨论。", "explanation": "这里应该用〈认为〉。认可表示觉得事情好、对而接受，不能与“很糟糕”这样的否定评价搭配。"}, {"text": "他在失物招领处认可了那只丢失的钱包是自己的，马上领了回去。", "explanation": "这里应该用〈认领〉。认可指觉得对而接受，认领失物要说认领。"}, {"text": "警察认可他是凶手，已经抓了他。", "explanation": "这里应该用〈认定〉。认可表示觉得对而接受，不用于认定某人是凶手这类负面结论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认可", "is_correct": true, "explanation": "“认可”指觉得这个计划好而接受，与“还不太”表示的保留态度相符。"}, {"text": "烘焙", "is_correct": false, "explanation": "配价：“烘焙”要求以食品作宾语，不能以计划作宾语。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，与计划无关。"}, {"text": "烧制", "is_correct": false, "explanation": "语义：“烧制”指用火加工陶瓷、砖瓦等器物，不能用于计划。"}], "explanations": {"认可": "“认可”指觉得这个计划好而接受，与“还不太”表示的保留态度相符。", "烘焙": "配价：“烘焙”要求以食品作宾语，不能以计划作宾语。", "种植": "语义：“种植”指栽种植物，与计划无关。", "烧制": "语义：“烧制”指用火加工陶瓷、砖瓦等器物，不能用于计划。"}, "sentence_index": 6, "correct_answer": "认可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一进门就认可了老朋友的声音。", "explanation": "这里应该用〈听出〉。认可指觉得对而接受，辨认声音要说听出。"}, {"text": "这张旧照片让我认可了小时候住过的胡同。", "explanation": "这里应该用〈认出〉。认可指觉得对而接受，辨认地方要说认出。"}, {"text": "她在人群里一眼就认可了多年不见的同学。", "explanation": "这里应该用〈认出〉。认可指觉得对而接受，辨认人要说认出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我被认可他的建议。", "corrected_sentence": "我很认可他的建议。", "error_description": "“被”不能放在“认可”前表示“很认可”，应说“我很认可他的建议”；“被认可”需要被认可的事物作主语，如“我的建议被认可了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没认可了他的做法。", "corrected_sentence": "我还没认可过他的做法。", "error_description": "“没”否定有过的经历时要用“没……过”，应说“还没认可过他的做法”；“没”与“了”不能搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
