INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23756, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说一个人或一件事好不好。", "primary_collocate": null, "pronunciation": "píng jià", "ipa": "pʰiŋ˧˥ tɕjɑ˥˩", "syllable_count": 2, "sentences": [{"text": "客人们评价这家饭馆时都说不错。", "target_word": "评价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常常评价我们写的作文。", "target_word": "评价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么评价这部电影？", "target_word": "评价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你评价一下这本书。", "target_word": "评价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只看钱来评价一个人。", "target_word": "评价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢评价别人，可是不喜欢听批评。", "target_word": "评价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人们评价这道菜时都说太咸了。", "target_word": "评价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她评价这次比赛时说很公平。", "target_word": "评价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家怎么评价新同事？", "target_word": "评价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要太快评价一件自己不了解的事。", "target_word": "评价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "评价了", "label": "完成体"}, {"form": "评价过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动词，对人或事物的好坏作出判断和说明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '449b634c-ae74-4ccb-8934-b82cc0828b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23756, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "评价", "is_correct": true, "explanation": "正确：“评价”指说明一个人或一件事好不好，即本题的目标词。"}, {"text": "凭借", "is_correct": false, "explanation": "jiè（第四声）与 jià（第四声）韵母不同（e 与 a），“凭借”意思是依靠、借助。"}, {"text": "评级", "is_correct": false, "explanation": "jí（第二声）与 jià（第四声）韵母、声调不同，“评级”意思是评定等级。"}, {"text": "棚架", "is_correct": false, "explanation": "péng 与 píng 韵母不同（e 与 i），意思是搭起来供攀爬或遮挡的架子。"}], "explanations": {"评价": "正确：“评价”指说明一个人或一件事好不好，即本题的目标词。", "凭借": "jiè（第四声）与 jià（第四声）韵母不同（e 与 a），“凭借”意思是依靠、借助。", "评级": "jí（第二声）与 jià（第四声）韵母、声调不同，“评级”意思是评定等级。", "棚架": "péng 与 píng 韵母不同（e 与 i），意思是搭起来供攀爬或遮挡的架子。"}, "sentence_index": null, "correct_answer": "评价"}, "level_3": {"options": [{"text": "装修", "is_correct": false, "explanation": "语义：装修是店主对店铺所做的工程，客人不做这件事，与“都说不错”的评述语境不合。"}, {"text": "评价", "is_correct": true, "explanation": "正确：客人对饭馆的好坏作出判断，与后文“都说不错”相符。"}, {"text": "点", "is_correct": false, "explanation": "搭配：“点”的宾语应是菜或餐，不说点饭馆。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆除建筑，与客人“说不错”的语境冲突。"}], "explanations": {"装修": "语义：装修是店主对店铺所做的工程，客人不做这件事，与“都说不错”的评述语境不合。", "评价": "正确：客人对饭馆的好坏作出判断，与后文“都说不错”相符。", "点": "搭配：“点”的宾语应是菜或餐，不说点饭馆。", "拆": "语义：“拆”是拆除建筑，与客人“说不错”的语境冲突。"}, "sentence_index": 0, "correct_answer": "评价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我评价明天会下雨。", "explanation": "这里应该用〈估计〉。评价是对人或事物的好坏作判断，不用来推测将要发生的事。"}, {"text": "这台机器评价了这批零件的数量。", "explanation": "这里应该用〈统计〉。数量要用统计或计算，评价只说好坏，不能用来评价数量。"}, {"text": "工人评价了这块木板的长度。", "explanation": "这里应该用〈测量〉。量长短、大小要用测量，评价是判断好坏，不能用来量长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进入", "is_correct": false, "explanation": "配价：“进入”带的是处所或领域，不能以“这道菜”作宾语。"}, {"text": "登记", "is_correct": false, "explanation": "配价：“登记”的宾语是姓名、事项等，不能说登记一道菜。"}, {"text": "评价", "is_correct": true, "explanation": "正确：客人对菜的咸淡作出评述，与“说太咸了”相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、地面等场所，不能用于菜肴，句子说不通。"}], "explanations": {"进入": "配价：“进入”带的是处所或领域，不能以“这道菜”作宾语。", "登记": "配价：“登记”的宾语是姓名、事项等，不能说登记一道菜。", "评价": "正确：客人对菜的咸淡作出评述，与“说太咸了”相符。", "打扫": "搭配：“打扫”的对象是房间、地面等场所，不能用于菜肴，句子说不通。"}, "sentence_index": 6, "correct_answer": "评价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们评价明天出发。", "explanation": "这里应该用〈决定〉。定下要做的事用决定，评价只用来说人或事物的好坏。"}, {"text": "学校评价我们明天放假。", "explanation": "这里应该用〈通知〉。把安排告诉大家用通知，评价不能用来传达消息。"}, {"text": "妈妈评价我带伞。", "explanation": "这里应该用〈提醒〉。叮嘱别人留意某事用提醒，评价是判断好坏，不表示叮嘱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家被评价了这个方案。", "corrected_sentence": "大家评价了这个方案。", "error_description": "错误形式：“大家被评价了这个方案”；正确形式：“大家评价了这个方案”。“被”字句中动词后不能再带宾语“这个方案”，多加的“被”使句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师评价着一下我们写的作文。", "corrected_sentence": "老师评价了一下我们写的作文。", "error_description": "错误形式：“评价着一下”。正确形式：“评价了一下”。动词带“一下”表示短暂、已完成的动作，不能用表示持续的“着”，应改为“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
