INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23758, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同侪的意思是一起学习或工作的人，就像同学或同事。", "primary_collocate": null, "pronunciation": "tóng chái", "ipa": "tʰʊŋ³⁵ ʈʂʰai³⁵", "syllable_count": 2, "sentences": [{"text": "我的同侪都在同一所学校学习。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和同侪每天一起做实验。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同侪互相检查作业。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公司，同侪常常一起吃午饭。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向同侪请教了这个问题。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同侪一起完成了这个项目。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，他先和同侪商量了一下。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一位很友好的同侪。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同侪之间应该互相帮助。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后，我和以前的同侪还有联系。", "target_word": "同侪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一起学习或工作的同学、同事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57e7b389-1948-4f3e-a521-8d2fc34cfc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同侪", "is_correct": true, "explanation": "正确。“同侪”指一起学习或工作的人，与“在同一所学校学习”相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客指搭乘交通工具的人，不是一起学习的人，句子不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师指做饭的人，与“在同一所学校学习”无关，句子不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，不能“在学校学习”，句子不通。"}], "explanations": {"同侪": "正确。“同侪”指一起学习或工作的人，与“在同一所学校学习”相符。", "乘客": "语义：乘客指搭乘交通工具的人，不是一起学习的人，句子不通。", "厨师": "语义：厨师指做饭的人，与“在同一所学校学习”无关，句子不通。", "雨伞": "语义：雨伞是物品，不能“在学校学习”，句子不通。"}, "sentence_index": 0, "correct_answer": "同侪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同侪生了我，把我养大。", "explanation": "这里应该用〈母亲〉。同侪指一起学习或工作的人，不是生养自己的人。"}, {"text": "同侪在河里游来游去，吐着泡泡。", "explanation": "这里应该用〈鱼〉。同侪指一起学习或工作的人，不是水里的动物。"}, {"text": "我把同侪放进书包，带去学校。", "explanation": "这里应该用〈课本〉。同侪是人，不能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同侪", "is_correct": true, "explanation": "正确。“开会前，他先和同侪商量了一下”指会前与一起工作的人商量，与句意相符。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不是人，无法与他“商量”，句子不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不能与他商量，句子不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是物件，不能与他商量，句子不通。"}], "explanations": {"同侪": "正确。“开会前，他先和同侪商量了一下”指会前与一起工作的人商量，与句意相符。", "影子": "语义：影子不是人，无法与他“商量”，句子不通。", "桌子": "语义：桌子是物品，不能与他商量，句子不通。", "闹钟": "语义：闹钟是物件，不能与他商量，句子不通。"}, "sentence_index": 6, "correct_answer": "同侪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同侪给我们发工资。", "explanation": "这里应该用〈老板〉。同侪指地位相近的人，没有给别人发工资的身份，应说“老板给我们发工资”。"}, {"text": "他正在喝同侪。", "explanation": "这里应该用〈咖啡〉。“喝”搭配饮品，同侪是人，不能被喝。"}, {"text": "他很孝顺同侪。", "explanation": "这里应该用〈父母〉。“孝顺”的对象是父母或长辈，不能用于同侪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只同侪很努力。", "corrected_sentence": "我有一位同侪很努力。", "error_description": "同侪指人，量词应用“位”，不能用“只”（“只”多用于动物或成对的物体）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议前，她先同侪讨论了一下。", "corrected_sentence": "会议前，她先和同侪讨论了一下。", "error_description": "“讨论”的对象要用介词“和”引出，应说“先和同侪讨论了一下”。漏掉“和”，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23760, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理想", "is_correct": true, "explanation": "正确。理想与现实是一对反义词，理想指对未来的美好设想，与真实存在的情况相对。"}, {"text": "天空", "is_correct": false, "explanation": "无反义关系：“天空”是自然景物，与“现实”没有相对的关系。"}, {"text": "图书", "is_correct": false, "explanation": "无反义关系：“图书”指书籍，与“现实”在词义上没有相对的关系。"}, {"text": "汽车", "is_correct": false, "explanation": "无反义关系：“汽车”是交通工具，与“现实”没有相对的关系。"}], "correct_answer": "理想", "explanations": {"理想": "正确。理想与现实是一对反义词，理想指对未来的美好设想，与真实存在的情况相对。", "天空": "无反义关系：“天空”是自然景物，与“现实”没有相对的关系。", "图书": "无反义关系：“图书”指书籍，与“现实”在词义上没有相对的关系。", "汽车": "无反义关系：“汽车”是交通工具，与“现实”没有相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23760, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理想", "is_correct": true, "explanation": "正确。理想与现实是一对反义词，理想指对未来的美好设想，与真实存在的情况相对。"}, {"text": "河流", "is_correct": false, "explanation": "无反义关系：“河流”是自然景物，与“现实”没有相对的关系。"}, {"text": "书本", "is_correct": false, "explanation": "无反义关系：“书本”指书籍，与“现实”在词义上没有相对的关系。"}, {"text": "城市", "is_correct": false, "explanation": "无反义关系：“城市”指人口集中的地区，与“现实”没有相对的关系。"}], "correct_answer": "理想", "explanations": {"理想": "正确。理想与现实是一对反义词，理想指对未来的美好设想，与真实存在的情况相对。", "河流": "无反义关系：“河流”是自然景物，与“现实”没有相对的关系。", "书本": "无反义关系：“书本”指书籍，与“现实”在词义上没有相对的关系。", "城市": "无反义关系：“城市”指人口集中的地区，与“现实”没有相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23760, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现在真实存在的事情，不是想象出来的。", "primary_collocate": null, "pronunciation": "xiàn shí", "ipa": "ɕjɛn˥˩ ʂʐ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他的梦想和现实不一样。", "target_word": "现实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要接受现实。", "target_word": "现实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的故事不是现实。", "target_word": "现实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想面对现实。", "target_word": "现实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现实中，找工作没有那么容易。", "target_word": "现实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从梦里醒来，回到了现实。", "target_word": "现实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的想法在现实里很难做到。", "target_word": "现实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人要看清现实，也要有梦想。", "target_word": "现实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说反映了当时的现实。", "target_word": "现实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现实和想象差得很远。", "target_word": "现实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现实生活", "label": "复合"}, {"form": "现实主义", "label": "复合"}], "register": "中性", "sense_fingerprint": "现实|真实存在的情况，相对于想象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88de35c8-0eb8-4233-8872-c58f86c79787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23760, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现实", "is_correct": true, "explanation": "正确。现实指现在真实存在的事情，读作 xiàn shí。"}, {"text": "显示", "is_correct": false, "explanation": "声调不同：显示读 xiǎn shì（第三、第四声），现实读 xiàn shí（第四、第二声），意思是展示、表现。"}, {"text": "相识", "is_correct": false, "explanation": "韵母不同：相识读 xiāng shí，第一个字韵母是 -ang，现实是 -an，意思是互相认识。"}, {"text": "先是", "is_correct": false, "explanation": "声调不同：先是读 xiān shì（第一、第四声），与现实的声调都不同，意思是起初、先前。"}], "explanations": {"现实": "正确。现实指现在真实存在的事情，读作 xiàn shí。", "显示": "声调不同：显示读 xiǎn shì（第三、第四声），现实读 xiàn shí（第四、第二声），意思是展示、表现。", "相识": "韵母不同：相识读 xiāng shí，第一个字韵母是 -ang，现实是 -an，意思是互相认识。", "先是": "声调不同：先是读 xiān shì（第一、第四声），与现实的声调都不同，意思是起初、先前。"}, "sentence_index": null, "correct_answer": "现实"}, "level_3": {"options": [{"text": "现实", "is_correct": true, "explanation": "正确。现实指真实存在的情况，与“梦想”相对，句意是梦想与真实情况不同。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指气象状况，不是可以与梦想比较的事物，句意不通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”是可以喝的东西，与“梦想”不属同类，不能相比。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，属于外形特征，与“梦想”不能放在一起比较。"}], "explanations": {"现实": "正确。现实指真实存在的情况，与“梦想”相对，句意是梦想与真实情况不同。", "天气": "语义：“天气”指气象状况，不是可以与梦想比较的事物，句意不通。", "饮料": "语义：“饮料”是可以喝的东西，与“梦想”不属同类，不能相比。", "身高": "体貌：“身高”指身体的高矮，属于外形特征，与“梦想”不能放在一起比较。"}, "sentence_index": 0, "correct_answer": "现实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子心里装满了现实。", "explanation": "这里应该用〈梦想〉。现实指真实存在的情况，心里的期待要说梦想。"}, {"text": "他从小就有当医生的现实。", "explanation": "这里应该用〈理想〉。现实与想象相对，心中的追求要说理想，不能说现实。"}, {"text": "他编造了一个骗人的现实。", "explanation": "这里应该用〈谎言〉。现实指真实存在的情况，编造的假话要说谎言，不能说现实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现实", "is_correct": true, "explanation": "正确。现实指真实存在的情况，“在现实里”表示在真实的环境中，符合句意。"}, {"text": "森林", "is_correct": false, "explanation": "语义：“森林”是具体的地方，“想法在森林里做到”的说法没有意义。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是具体的房间，把抽象的想法放在厨房里，不合逻辑。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不是能容纳事情的场所，不能与“里”搭配表示范围。"}], "explanations": {"现实": "正确。现实指真实存在的情况，“在现实里”表示在真实的环境中，符合句意。", "森林": "语义：“森林”是具体的地方，“想法在森林里做到”的说法没有意义。", "厨房": "语义：“厨房”是具体的房间，把抽象的想法放在厨房里，不合逻辑。", "颜色": "搭配：“颜色”不是能容纳事情的场所，不能与“里”搭配表示范围。"}, "sentence_index": 6, "correct_answer": "现实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨晚做了一个奇怪的现实。", "explanation": "这里应该用〈梦〉。现实指真实存在的情况，夜里睡着时出现的情景要说梦，不能说做现实。"}, {"text": "她的现实很丰富，总是编出有趣的故事。", "explanation": "这里应该用〈幻想〉。编出有趣故事、内容丰富的想象要说幻想，现实是客观存在，不能形容想象力。"}, {"text": "这首诗用了很多现实。", "explanation": "这里应该用〈比喻〉。现实指真实存在的情况，修辞手法要说比喻，不能说现实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只残酷的现实让他很难接受。", "corrected_sentence": "这个残酷的现实让他很难接受。", "error_description": "量词错误：“现实”是抽象名词，量词应用“个”，“只”用于动物等，不能用于“现实”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于接受了残酷地现实。", "corrected_sentence": "他终于接受了残酷的现实。", "error_description": "“地”应改为“的”：“残酷”修饰名词“现实”，应用“的”，“地”用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938d712c-73d7-43d9-b31c-bfb4db5aa6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
