INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23762, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指大家都同意并遵守的标准或规则。", "primary_collocate": null, "pronunciation": "guī fàn", "ipa": "kweɪ fan", "syllable_count": 2, "sentences": [{"text": "班里有一条规范：上课不能玩手机。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家要遵守安全规范。", "target_word": "规范", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家餐厅的卫生规范很严格。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一起定下了小区的生活规范。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们要学习基本的礼貌规范。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏里有一条规范：不能骂人。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个社团的规范很简单，大家都记得住。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了课堂上的规范。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打破这个规范的人，要向大家道歉。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的规范要求大家见面先打招呼。", "target_word": "规范", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "規範", "label": "繁体"}], "register": "正式", "sense_fingerprint": "名词：大家都同意并遵守的规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57e7b389-1948-4f3e-a521-8d2fc34cfc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规范", "is_correct": true, "explanation": "正确。“规范”指全班共同遵守的规则，与后面的禁令相符。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是做菜的方法，不是课堂规则。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，与课堂禁令无关。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”是性格，不能说“有一个脾气”后接一条规则。"}], "explanations": {"规范": "正确。“规范”指全班共同遵守的规则，与后面的禁令相符。", "食谱": "语义：食谱是做菜的方法，不是课堂规则。", "身材": "体貌：“身材”指人的体形，与课堂禁令无关。", "脾气": "搭配：“脾气”是性格，不能说“有一个脾气”后接一条规则。"}, "sentence_index": 0, "correct_answer": "规范"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗很可爱，是我多年的规范。", "explanation": "这里应该用〈朋友〉。规范指大家都同意并遵守的标准，一只狗不能叫规范。"}, {"text": "我去年在国外工作，这是我难忘的规范。", "explanation": "这里应该用〈经历〉。规范指大家共同遵守的标准，个人的人生经历不能叫规范。"}, {"text": "我从小的规范是成为科学家。", "explanation": "这里应该用〈梦想〉。规范指大家共同遵守的标准，个人的志向不能叫规范。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规范", "is_correct": true, "explanation": "正确。“社团的规范”指成员共同遵守的规则，与“简单、记得住”相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指身体的温度，不能说“简单、记得住”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”属于体貌，与社团的规则无关。"}, {"text": "屋顶", "is_correct": false, "explanation": "语义：屋顶是房子的一部分，不能说“社团的屋顶很简单，大家都记得住”。"}], "explanations": {"规范": "正确。“社团的规范”指成员共同遵守的规则，与“简单、记得住”相符。", "体温": "语义：体温指身体的温度，不能说“简单、记得住”。", "身高": "体貌：“身高”属于体貌，与社团的规则无关。", "屋顶": "语义：屋顶是房子的一部分，不能说“社团的屋顶很简单，大家都记得住”。"}, "sentence_index": 6, "correct_answer": "规范"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次的规范是全班第一。", "explanation": "这里应该用〈成绩〉。规范指大家都遵守的标准或规则，个人的考试名次要说成绩。"}, {"text": "我送你的规范是一本书。", "explanation": "这里应该用〈礼物〉。规范指大家都遵守的标准或规则，送人的东西要说礼物。"}, {"text": "我家到学校的规范是三公里。", "explanation": "这里应该用〈距离〉。规范指大家都遵守的标准或规则，两地之间的远近要说距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里定了一根新规范。", "corrected_sentence": "村里定了一套新规范。", "error_description": "量词“根”多用于细长的东西，规范应用量词“套”，应说“一套新规范”，不能说“一根新规范”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社团曾经制定着一套规范。", "corrected_sentence": "社团曾经制定过一套规范。", "error_description": "“着”表示动作正在进行或持续，与“曾经”指已完成的经历矛盾，应说“制定过一套规范”，“过”紧跟动词表示经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
