INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23764, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "干净，没有别的东西。", "primary_collocate": null, "pronunciation": "chún cuì", "ipa": "ʈʂʰwən tsʰweɪ", "syllable_count": 2, "sentences": [{"text": "这块布是纯粹的棉，没有别的材料。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块银子很纯粹，里面没有别的金属。", "target_word": "纯粹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种果汁很纯粹，只有水果，没有糖。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝的是纯粹的白酒，没有兑水。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服是纯粹的羊毛做的，没有掺别的纤维。", "target_word": "纯粹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶蜂蜜很纯粹，没有加一点水。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是纯粹的牛奶，没有加别的东西。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家的茶是纯粹的绿茶，没有加花。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种油是纯粹的橄榄油，没有别的油。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块玉很纯粹，里面看不到杂质。", "target_word": "纯粹", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "純粹", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容词：东西干净，不掺别的材料（多指具体物质）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57e7b389-1948-4f3e-a521-8d2fc34cfc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纯粹", "is_correct": true, "explanation": "“纯粹”指这块布是纯棉、不掺别的材料，修饰“棉”符合句意。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音或食物的脆感，不能用来修饰材料。"}, {"text": "酸", "is_correct": false, "explanation": "语义：“酸”指味道，不能用来修饰棉这种材料。"}, {"text": "瘦长", "is_correct": false, "explanation": "体貌：“瘦长”形容人的体形，不能用来修饰布料的材料。"}], "explanations": {"纯粹": "“纯粹”指这块布是纯棉、不掺别的材料，修饰“棉”符合句意。", "清脆": "语义：“清脆”形容声音或食物的脆感，不能用来修饰材料。", "酸": "语义：“酸”指味道，不能用来修饰棉这种材料。", "瘦长": "体貌：“瘦长”形容人的体形，不能用来修饰布料的材料。"}, "sentence_index": 0, "correct_answer": "纯粹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告很纯粹，里面夹着好几张照片。", "explanation": "这里应该用〈丰富〉。纯粹指没有别的东西，报告里夹着照片时不能说纯粹，应说丰富。"}, {"text": "他做饭很纯粹，朋友们都夸他手艺好。", "explanation": "这里应该用〈熟练〉。纯粹指东西不掺别的材料，不能用来形容做饭的技巧。"}, {"text": "这盆花很纯粹，里面混着好几种杂草。", "explanation": "这里应该用〈杂乱〉。纯粹指没有别的东西，花盆里混着杂草时不能说纯粹，应说杂乱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纯粹", "is_correct": true, "explanation": "“纯粹”指牛奶没有加别的东西，修饰“牛奶”符合句意。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”形容人的身体，不能用来修饰牛奶。"}, {"text": "威严", "is_correct": false, "explanation": "语义：“威严”形容人或场面的庄重气派，与牛奶的成分无关。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：“迟钝”形容反应慢，不能用来形容牛奶。"}], "explanations": {"纯粹": "“纯粹”指牛奶没有加别的东西，修饰“牛奶”符合句意。", "瘦弱": "体貌：“瘦弱”形容人的身体，不能用来修饰牛奶。", "威严": "语义：“威严”形容人或场面的庄重气派，与牛奶的成分无关。", "迟钝": "语义：“迟钝”形容反应慢，不能用来形容牛奶。"}, "sentence_index": 6, "correct_answer": "纯粹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块玉雕得很纯粹，上面还刻着几朵云。", "explanation": "这里应该用〈精细〉。纯粹指没有别的东西，玉上还刻着别的图案时不能说纯粹，应说精细。"}, {"text": "这间房子很纯粹，能住下五个人。", "explanation": "这里应该用〈宽敞〉。纯粹指东西不掺别的材料，房子大小要说宽敞。"}, {"text": "这块布很纯粹，摸起来软软的。", "explanation": "这里应该用〈柔软〉。纯粹指不掺别的材料，摸起来软要说柔软。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这壶酒是纯粹地高粱酒。", "corrected_sentence": "这壶酒是纯粹的高粱酒。", "error_description": "“纯粹”修饰名词时后面应用“的”，应说“纯粹的高粱酒”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那碗汤被纯粹，只有鸡肉。", "corrected_sentence": "那碗汤很纯粹，只有鸡肉。", "error_description": "“被”不能用在形容词“纯粹”前，应说“很纯粹”，用副词“很”修饰形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
