INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23766, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "非常容易。", "primary_collocate": null, "pronunciation": "jí yì", "ipa": "tɕi˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "这种花极易养活，新手也能种好。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天食物极易变质，要放进冰箱。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很单纯，极易相信别人的话。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机屏幕极易留下指纹。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长时间不运动，身体极易感到疲劳。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木头遇水极易变形，要注意防潮。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个字太像，极易看错。", "target_word": "极易", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山路下雨后极易塌方，请绕行。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她太善良，极易上当。", "target_word": "极易", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "金属放在潮湿的地方极易生锈。", "target_word": "极易", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "极易：非常容易，用在动词前说明事物很容易出现某种变化或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b0ed77-9f70-4146-933b-ae5e8601f104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23766, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极易", "is_correct": true, "explanation": "正确：极易 jí yì，表示非常容易。"}, {"text": "记忆", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是记忆。"}, {"text": "技艺", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是技能和本领。"}, {"text": "奇异", "is_correct": false, "explanation": "qí 与 jí 声母不同（q / j），意思是奇特、不寻常。"}], "explanations": {"极易": "正确：极易 jí yì，表示非常容易。", "记忆": "jì（第四声）与 jí（第二声）声调不同，意思是记忆。", "技艺": "jì（第四声）与 jí（第二声）声调不同，意思是技能和本领。", "奇异": "qí 与 jí 声母不同（q / j），意思是奇特、不寻常。"}, "sentence_index": null, "correct_answer": "极易"}, "level_3": {"options": [{"text": "极易", "is_correct": true, "explanation": "正确：“极易”表示非常容易，说明这种花容易养活，与“新手也能种好”相符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”强调事情已经发生，与句中泛指花的特性不符。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”需要有意识的人作施事，“花”不能亲自养活。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，而“养活”这种自然结果不能故意达成。"}], "explanations": {"极易": "正确：“极易”表示非常容易，说明这种花容易养活，与“新手也能种好”相符。", "已经": "语义：“已经”强调事情已经发生，与句中泛指花的特性不符。", "亲自": "搭配：“亲自”需要有意识的人作施事，“花”不能亲自养活。", "故意": "语义：“故意”表示有意为之，而“养活”这种自然结果不能故意达成。"}, "sentence_index": 0, "correct_answer": "极易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛他费了很大力气，极易拿到好名次。", "explanation": "这里应该用〈不容易〉。极易表示很容易，与“费了很大力气”矛盾；费力才能做到的事要用“不容易”。"}, {"text": "这道题太难了，大家极易做对。", "explanation": "这里应该用〈很难〉。极易表示很容易，与“这道题太难了”矛盾。"}, {"text": "他一路上气喘吁吁，极易就到了山顶。", "explanation": "这里应该用〈不容易〉。极易表示很容易，与“气喘吁吁”的费力状态矛盾；费力才能做到的事要用“不容易”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68664c65-6e45-482a-b7d2-fd1940bc0cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "极易", "is_correct": true, "explanation": "正确：“极易”表示非常容易，说明两个字太像所以容易看错。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”表示本人动手，“看错”是无意的失误，二者不搭配。"}, {"text": "极力", "is_correct": false, "explanation": "语义：“极力”表示竭力去做，与“看错”这种无意的失误相反。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示从来没有，与“太像”带来的必然结果冲突。"}], "explanations": {"极易": "正确：“极易”表示非常容易，说明两个字太像所以容易看错。", "亲自": "搭配：“亲自”表示本人动手，“看错”是无意的失误，二者不搭配。", "极力": "语义：“极力”表示竭力去做，与“看错”这种无意的失误相反。", "从未": "语义：“从未”表示从来没有，与“太像”带来的必然结果冲突。"}, "sentence_index": 6, "correct_answer": "极易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试非常难，极易通过。", "explanation": "这里应该用〈不容易〉。极易表示很容易，与“考试非常难”矛盾。"}, {"text": "这辆车修了整整一周，极易就修好了。", "explanation": "这里应该用〈费了很多时间〉。极易表示做起来不费力，不表示时间长短；前句说修了一周，要用“费了很多时间”。"}, {"text": "他性格内向，不善交际，极易交到很多朋友。", "explanation": "这里应该用〈很难〉。极易表示很容易，与“性格内向，不善交际”矛盾；交朋友困难时要用“很难”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68664c65-6e45-482a-b7d2-fd1940bc0cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种草极易成活率，随便种都能长。", "corrected_sentence": "这种草极易成活，随便种都能长。", "error_description": "错误：“极易”修饰动词，其后应接动词“成活”，此处误用名词“成活率”，不能受“极易”修饰。正确应为“极易成活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68664c65-6e45-482a-b7d2-fd1940bc0cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个杯子很薄，很极易打碎。", "corrected_sentence": "这个杯子很薄，极易打碎。", "error_description": "错误：“极易”本身已表示程度，前面不能再加“很”。正确应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68664c65-6e45-482a-b7d2-fd1940bc0cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
