INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23774, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一个东西不能太强，另一个也不能太弱，它们互相管住对方。", "primary_collocate": null, "pronunciation": "zhì héng", "ipa": "ʈʂɻ̩ xɤŋ", "syllable_count": 2, "sentences": [{"text": "两个班长互相制衡，谁都不能说了算。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自然界里，天敌能制衡动物的数量。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "财务部和销售部彼此制衡，公司才安全。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "左右两队的力量互相制衡，比赛很精彩。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸管钱，妈妈管事，两人互相制衡。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要用规则制衡太强的一方。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三个人各管一部分钱，可以互相制衡。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的制度能制衡每一个人的权力。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弱队需要有人帮忙制衡强队。", "target_word": "制衡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们互相制衡着，谁也不敢先动手。", "target_word": "制衡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制衡了", "label": "体标"}, {"form": "制衡着", "label": "体标"}, {"form": "制衡过", "label": "体标"}], "register": "正式", "sense_fingerprint": "动词：双方互相管住对方，谁也不能过强或过弱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57e7b389-1948-4f3e-a521-8d2fc34cfc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制衡", "is_correct": true, "explanation": "正确。“互相制衡”指双方互相管住，谁都不能说了算，与句意一致。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：拥抱表达亲密，与“谁都不能说了算”的相互管束无关。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：烹饪的对象是食物，不能说“互相烹饪”。"}, {"text": "点名", "is_correct": false, "explanation": "语义：点名指叫人答到，与权力的相互管束不符。"}], "explanations": {"制衡": "正确。“互相制衡”指双方互相管住，谁都不能说了算，与句意一致。", "拥抱": "语义：拥抱表达亲密，与“谁都不能说了算”的相互管束无关。", "烹饪": "搭配：烹饪的对象是食物，不能说“互相烹饪”。", "点名": "语义：点名指叫人答到，与权力的相互管束不符。"}, "sentence_index": 0, "correct_answer": "制衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察制衡市民的安全，让大家放心。", "explanation": "这里应该用〈保护〉。制衡指双方互相管住，对他人的庇护要用保护。"}, {"text": "老师制衡学生复习功课。", "explanation": "这里应该用〈帮助〉。制衡强调双方互相制约，老师对学生的协助要用帮助。"}, {"text": "奶奶制衡生病的孙子。", "explanation": "这里应该用〈照顾〉。制衡需要双方互相制约，对生病的人的照料要用照顾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制衡", "is_correct": true, "explanation": "正确。“互相制衡”指各管一部分的人彼此管住，与句意相符。"}, {"text": "歌唱", "is_correct": false, "explanation": "搭配：“歌唱”是表演动作，不能与“互相”组成管束关系。"}, {"text": "盖房", "is_correct": false, "explanation": "语义：盖房指建造房屋，与分钱管事的语境不合。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆指无所事事地发愣，与彼此管住对方不符。"}], "explanations": {"制衡": "正确。“互相制衡”指各管一部分的人彼此管住，与句意相符。", "歌唱": "搭配：“歌唱”是表演动作，不能与“互相”组成管束关系。", "盖房": "语义：盖房指建造房屋，与分钱管事的语境不合。", "发呆": "语义：发呆指无所事事地发愣，与彼此管住对方不符。"}, "sentence_index": 6, "correct_answer": "制衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人制衡着一箱货物。", "explanation": "这里应该用〈搬〉。制衡指双方互相管住，搬运货物是单方面的动作，要用搬。"}, {"text": "厨师制衡着锅里的汤。", "explanation": "这里应该用〈煮〉。制衡指双方互相管住，烧汤是单方面的烹饪，要用煮。"}, {"text": "园丁制衡着院子里的花草。", "explanation": "这里应该用〈修剪〉。制衡指双方互相管住，整理花草是单方面的动作，要用修剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两队互相制衡得，比赛才公平。", "corrected_sentence": "两队互相制衡，比赛才公平。", "error_description": "补语标记“得”后面必须接补语，这里“制衡得”后面没有补语，应删去“得”，说“两队互相制衡，比赛才公平”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两派曾经制衡着对方。", "corrected_sentence": "两派曾经制衡过对方。", "error_description": "“着”表示动作持续，与“曾经”指已完成的经历矛盾，应说“制衡过对方”，“过”紧跟动词表示经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '205b575c-026f-4fe8-ad5c-06e3837b21c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐性", "is_correct": true, "explanation": "隐性：与显性相对，指特征不容易被察觉。"}, {"text": "响亮", "is_correct": false, "explanation": "与“显性”无反义关系。响亮指声音大而清楚，与显性不构成相对的概念。"}, {"text": "柔软", "is_correct": false, "explanation": "与“显性”无反义关系。柔软指质地松软，与显性不构成相对的概念。"}, {"text": "冷淡", "is_correct": false, "explanation": "与“显性”无反义关系。冷淡指态度不热情，与显性不构成相对的概念。"}], "correct_answer": "隐性", "explanations": {"隐性": "隐性：与显性相对，指特征不容易被察觉。", "响亮": "与“显性”无反义关系。响亮指声音大而清楚，与显性不构成相对的概念。", "柔软": "与“显性”无反义关系。柔软指质地松软，与显性不构成相对的概念。", "冷淡": "与“显性”无反义关系。冷淡指态度不热情，与显性不构成相对的概念。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐性", "is_correct": true, "explanation": "隐性：与显性相对，指特征不容易被察觉。"}, {"text": "潮湿", "is_correct": false, "explanation": "与“显性”无反义关系。潮湿指含水分多，与显性不构成相对的概念。"}, {"text": "高大", "is_correct": false, "explanation": "与“显性”无反义关系。高大指体形或高度，与显性不构成相对的概念。"}, {"text": "辽阔", "is_correct": false, "explanation": "与“显性”无反义关系。辽阔指范围广大，与显性不构成相对的概念。"}], "correct_answer": "隐性", "explanations": {"隐性": "隐性：与显性相对，指特征不容易被察觉。", "潮湿": "与“显性”无反义关系。潮湿指含水分多，与显性不构成相对的概念。", "高大": "与“显性”无反义关系。高大指体形或高度，与显性不构成相对的概念。", "辽阔": "与“显性”无反义关系。辽阔指范围广大，与显性不构成相对的概念。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "显性就是很容易看见或知道的样子。", "primary_collocate": null, "pronunciation": "xiǎn xìng", "ipa": "ɕi̯ɛn˨˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的进步是显性的，老师一眼就看到了。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "显性的错误容易改，隐性的错误难找。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的价格优势是显性的，一进门就能看到。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的不高兴是显性的，大家都看得出来。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司显性的问题已经解决了。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "显性的好处你马上就能看到。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病有显性症状，很容易发现。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先说显性的原因，再说隐性的原因。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的变化不是显性的，别人没注意。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "显性成本比隐性成本好算。", "target_word": "显性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "显性基因", "label": "复合"}, {"form": "显性成本", "label": "复合"}], "register": "书面", "sense_fingerprint": "摆在明处、很容易看见或知道的样子，与隐性相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b2369b-e895-4499-98cc-06ea7bf3828e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性（xiǎn xìng）：摆在明处、很容易看见或知道的样子，与“隐性”相对。"}, {"text": "线性", "is_correct": false, "explanation": "线性（xiàn xìng）与显性的第一音节声调不同：xiàn 为第四声，xiǎn 为第三声。意思是呈直线关系。"}, {"text": "现行", "is_correct": false, "explanation": "现行（xiàn xíng）与显性的声调不同：第一音节 xiàn 为第四声，第二音节 xíng 为第二声。意思是当前正在实行的。"}, {"text": "显形", "is_correct": false, "explanation": "显形（xiǎn xíng）与显性的第二音节声调不同：xíng 为第二声，xìng 为第四声。意思是显露出原本的形状。"}, {"text": "限行", "is_correct": false, "explanation": "限行（xiàn xíng）与显性的两个音节声调都不同。意思是限制车辆或人员通行。"}], "explanations": {"显性": "显性（xiǎn xìng）：摆在明处、很容易看见或知道的样子，与“隐性”相对。", "线性": "线性（xiàn xìng）与显性的第一音节声调不同：xiàn 为第四声，xiǎn 为第三声。意思是呈直线关系。", "现行": "现行（xiàn xíng）与显性的声调不同：第一音节 xiàn 为第四声，第二音节 xíng 为第二声。意思是当前正在实行的。", "显形": "显形（xiǎn xíng）与显性的第二音节声调不同：xíng 为第二声，xìng 为第四声。意思是显露出原本的形状。", "限行": "限行（xiàn xíng）与显性的两个音节声调都不同。意思是限制车辆或人员通行。"}, "sentence_index": null, "correct_answer": "显性"}, "level_3": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性：指进步容易被察觉，与“老师一眼就看到了”相合。"}, {"text": "隐性", "is_correct": false, "explanation": "语义：隐性指不容易察觉，与后句“老师一眼就看到了”矛盾。"}, {"text": "模糊", "is_correct": false, "explanation": "语义：模糊指看不清楚，与“一眼就看到了”矛盾。"}, {"text": "深奥", "is_correct": false, "explanation": "搭配：深奥多用来形容道理或学问，不用来修饰“进步”。"}], "explanations": {"显性": "显性：指进步容易被察觉，与“老师一眼就看到了”相合。", "隐性": "语义：隐性指不容易察觉，与后句“老师一眼就看到了”矛盾。", "模糊": "语义：模糊指看不清楚，与“一眼就看到了”矛盾。", "深奥": "搭配：深奥多用来形容道理或学问，不用来修饰“进步”。"}, "sentence_index": 0, "correct_answer": "显性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的不高兴是显性的，谁都看不出来。", "explanation": "这里应该用〈隐蔽〉。显性指很容易看见，“谁都看不出来”与之矛盾。"}, {"text": "这个问题是显性的，大家一直都没发现。", "explanation": "这里应该用〈隐性〉。显性指很容易看见，“一直都没发现”与之矛盾。"}, {"text": "那棵老树很显性，走近了才能认出来。", "explanation": "这里应该用〈不起眼〉。显性指很容易看见，“走近了才能认出来”与之矛盾，应说“不起眼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性（xiǎn xìng）：摆在明处、很容易看见或知道的样子，与“隐性”相对。"}, {"text": "先行", "is_correct": false, "explanation": "先行（xiān xíng）与显性的第一音节声调不同：xiān 为第一声，xiǎn 为第三声。意思是事先走在前面。"}, {"text": "线形", "is_correct": false, "explanation": "线形（xiàn xíng）与显性的两个音节声调都不同。意思是线条的形状。"}, {"text": "线型", "is_correct": false, "explanation": "线型（xiàn xíng）与显性的两个音节声调都不同。意思是线条的类型或样式。"}, {"text": "现形", "is_correct": false, "explanation": "现形（xiàn xíng）与显性的两个音节声调都不同。意思是露出本来面目。"}], "explanations": {"显性": "显性（xiǎn xìng）：摆在明处、很容易看见或知道的样子，与“隐性”相对。", "先行": "先行（xiān xíng）与显性的第一音节声调不同：xiān 为第一声，xiǎn 为第三声。意思是事先走在前面。", "线形": "线形（xiàn xíng）与显性的两个音节声调都不同。意思是线条的形状。", "线型": "线型（xiàn xíng）与显性的两个音节声调都不同。意思是线条的类型或样式。", "现形": "现形（xiàn xíng）与显性的两个音节声调都不同。意思是露出本来面目。"}, "sentence_index": null, "correct_answer": "显性"}, "level_3": {"options": [{"text": "显性", "is_correct": true, "explanation": "显性：指症状容易察觉，与“很容易发现”相合。"}, {"text": "无形", "is_correct": false, "explanation": "语义：无形指看不见，与“很容易发现”矛盾。"}, {"text": "微妙", "is_correct": false, "explanation": "语义：微妙指细微难辨，与“很容易发现”矛盾。"}, {"text": "隐蔽", "is_correct": false, "explanation": "搭配：隐蔽多修饰行动或位置，一般不说“隐蔽症状”。"}], "explanations": {"显性": "显性：指症状容易察觉，与“很容易发现”相合。", "无形": "语义：无形指看不见，与“很容易发现”矛盾。", "微妙": "语义：微妙指细微难辨，与“很容易发现”矛盾。", "隐蔽": "搭配：隐蔽多修饰行动或位置，一般不说“隐蔽症状”。"}, "sentence_index": 6, "correct_answer": "显性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个错误是显性的，检查了很多次才发现。", "explanation": "这里应该用〈隐性〉。显性指很容易看见，“检查了很多次才发现”与之矛盾。"}, {"text": "她心里的想法是显性的，从来不让别人知道。", "explanation": "这里应该用〈隐秘〉。显性指很容易知道，“从来不让别人知道”与之矛盾。"}, {"text": "这种成本是显性的，很难算清楚。", "explanation": "这里应该用〈隐性〉。显性成本摆在明处，容易算，“很难算清楚”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个病的症状显性的，医生很快就判断出来了。", "corrected_sentence": "这个病的症状是显性的，医生很快就判断出来了。", "error_description": "“显性的”作表语前要用“是”。应说“是显性的”，不说“显性的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项改变是显性地，大家一眼就能看到。", "corrected_sentence": "这项改变是显性的，大家一眼就能看到。", "error_description": "“显性”作表语时要用“的”，不用“地”（“地”用于修饰动词）。应说“是显性的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86eb21fd-0132-4568-ae7c-75f9765876f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗劣", "is_correct": true, "explanation": "反义：“粗劣”指质量差，与“精良”相反。"}, {"text": "宽敞", "is_correct": false, "explanation": "无关：“宽敞”形容空间大，与“精良”不构成反义。"}, {"text": "灵活", "is_correct": false, "explanation": "无关：“灵活”指动作或思路敏捷，与“精良”不构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线充足或颜色亮，与“精良”不构成反义。"}], "correct_answer": "粗劣", "explanations": {"粗劣": "反义：“粗劣”指质量差，与“精良”相反。", "宽敞": "无关：“宽敞”形容空间大，与“精良”不构成反义。", "灵活": "无关：“灵活”指动作或思路敏捷，与“精良”不构成反义。", "明亮": "无关：“明亮”形容光线充足或颜色亮，与“精良”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68664c65-6e45-482a-b7d2-fd1940bc0cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗劣", "is_correct": true, "explanation": "反义：“粗劣”指质量差，与“精良”相反。"}, {"text": "繁忙", "is_correct": false, "explanation": "无关：“繁忙”形容事务多，与“精良”不构成反义。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：“迅速”形容速度快，与“精良”不构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容没有声音，与“精良”不构成反义。"}], "correct_answer": "粗劣", "explanations": {"粗劣": "反义：“粗劣”指质量差，与“精良”相反。", "繁忙": "无关：“繁忙”形容事务多，与“精良”不构成反义。", "迅速": "无关：“迅速”形容速度快，与“精良”不构成反义。", "安静": "无关：“安静”形容没有声音，与“精良”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68664c65-6e45-482a-b7d2-fd1940bc0cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "物品做得很好，质量高。", "primary_collocate": null, "pronunciation": "jīng liáng", "ipa": "tɕiŋ˥ liɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这双皮鞋做得精良，穿很多年也不坏。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的茶具都很精良。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸送我一支做工精良的钢笔。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自行车质量精良，骑起来很稳。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一套精良的画笔。", "target_word": "精良", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些玩具造得很精良。", "target_word": "精良", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们用精良的机器做衣服。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书印得很精良，纸也好。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手表小而精良。", "target_word": "精良", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子看上去简单，做得却很精良。", "target_word": "精良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物品做得好、质量高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b0ed77-9f70-4146-933b-ae5e8601f104') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粗劣", "is_correct": false, "explanation": "语义：“粗劣”指质量差，与后句“穿很多年也不坏”的评价相矛盾。"}, {"text": "精良", "is_correct": true, "explanation": "正确：“精良”指做得好、质量高，与“穿很多年也不坏”的评价相符。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”指容易损坏，与“穿很多年也不坏”相矛盾。"}, {"text": "不结实", "is_correct": false, "explanation": "语义：“不结实”指容易坏，与“穿很多年也不坏”相矛盾。"}], "explanations": {"粗劣": "语义：“粗劣”指质量差，与后句“穿很多年也不坏”的评价相矛盾。", "精良": "正确：“精良”指做得好、质量高，与“穿很多年也不坏”的评价相符。", "脆弱": "语义：“脆弱”指容易损坏，与“穿很多年也不坏”相矛盾。", "不结实": "语义：“不结实”指容易坏，与“穿很多年也不坏”相矛盾。"}, "sentence_index": 0, "correct_answer": "精良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很精良。", "explanation": "这里应该用〈聪明〉。精良形容物品做得好，形容人的智力要用聪明。"}, {"text": "这条河的水很精良。", "explanation": "这里应该用〈清澈〉。精良形容物品的制作质量，水的透明程度要用清澈。"}, {"text": "今天的天气很精良。", "explanation": "这里应该用〈晴朗〉。精良只形容物品的做工和质量，天气要用晴朗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68664c65-6e45-482a-b7d2-fd1940bc0cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容质地或颜色，不用来说机器的质量，与“工人们用……做衣服”的语境不符。"}, {"text": "精良", "is_correct": true, "explanation": "正确：“精良”指机器质量好、做得细致，与“用……做衣服”的语境相符。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地，不用来形容机器。"}, {"text": "苦涩", "is_correct": false, "explanation": "语义：“苦涩”形容味道，与“机器”不相关。"}], "explanations": {"透明": "语义：“透明”形容质地或颜色，不用来说机器的质量，与“工人们用……做衣服”的语境不符。", "精良": "正确：“精良”指机器质量好、做得细致，与“用……做衣服”的语境相符。", "柔软": "搭配：“柔软”形容质地，不用来形容机器。", "苦涩": "语义：“苦涩”形容味道，与“机器”不相关。"}, "sentence_index": 6, "correct_answer": "精良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个店员很精良。", "explanation": "这里应该用〈热情〉。精良形容物品做得好，形容人的态度要用热情。"}, {"text": "这场雨下得很精良。", "explanation": "这里应该用〈大〉。精良只形容物品的做工和质量，雨势要用大或小。"}, {"text": "她的笑容很精良。", "explanation": "这里应该用〈甜美〉。精良只形容物品的做工和质量，笑容要用甜美或灿烂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68664c65-6e45-482a-b7d2-fd1940bc0cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套家具做很精良，用了很多年。", "corrected_sentence": "这套家具做得很精良，用了很多年。", "error_description": "错误：“做很精良”，正确：“做得很精良”。“做”后接表示程度的补语时，要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68664c65-6e45-482a-b7d2-fd1940bc0cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把剪刀的质量最很精良。", "corrected_sentence": "这把剪刀的质量最精良。", "error_description": "错误：“最很精良”，正确：“最精良”。“最”和“很”都表示程度，不能同时修饰同一个形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68664c65-6e45-482a-b7d2-fd1940bc0cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
