INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两件事可以同时做，不会互相影响。", "primary_collocate": null, "pronunciation": "bìng xíng bù bèi", "ipa": "piŋ˥˩ ɕiŋ˧˥ pu˥˩ pei˥˩", "syllable_count": 4, "sentences": [{"text": "学钢琴和学画画并行不悖，时间安排得开。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会和写报告并行不悖，我可以同时做。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以工作，也可以读书，两件事并行不悖。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个活动并行不悖，不会互相影响。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱歌和跳舞并行不悖，她两样都爱。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打球和复习并行不悖，只要安排好时间。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作和家庭并行不悖，生活很稳定。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭和听广播并行不悖，妈妈天天这样。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写作业和听音乐并行不悖，他说不吵。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭和看新闻并行不悖，他每天都这样。", "target_word": "并行不悖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两件事能同时做且互不影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a75f58e-1f3e-45a4-b3b5-1fb54031ee52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "争抢", "is_correct": false, "explanation": "配价：“争抢”需要争夺的对象作宾语，这里缺宾语，句子不成立。"}, {"text": "并行不悖", "is_correct": true, "explanation": "正确：“并行不悖”指两件事能同时做、互不影响，与“时间安排得开”相合。"}, {"text": "相互挤占", "is_correct": false, "explanation": "语义：“相互挤占”指争抢同一份时间，与后文“时间安排得开”相矛盾。"}, {"text": "乱套", "is_correct": false, "explanation": "语义：“乱套”指秩序混乱，与后文“时间安排得开”相矛盾，也不能表示两件事互不影响。"}], "explanations": {"争抢": "配价：“争抢”需要争夺的对象作宾语，这里缺宾语，句子不成立。", "并行不悖": "正确：“并行不悖”指两件事能同时做、互不影响，与“时间安排得开”相合。", "相互挤占": "语义：“相互挤占”指争抢同一份时间，与后文“时间安排得开”相矛盾。", "乱套": "语义：“乱套”指秩序混乱，与后文“时间安排得开”相矛盾，也不能表示两件事互不影响。"}, "sentence_index": 0, "correct_answer": "并行不悖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个活动并行不悖，很难同时进行。", "explanation": "这里应该用〈互相干扰〉。“并行不悖”表示两件事互不影响、能同时进行，与“很难同时进行”的意思相反。"}, {"text": "这两件事要并行不悖地做，一步一步来。", "explanation": "这里应该用〈循序渐进〉。“并行不悖”强调同时进行，与“一步一步来”的先后次序不符。"}, {"text": "两个活动并行不悖，只能选一个。", "explanation": "这里应该用〈不可兼得〉。“并行不悖”表示两件事能同时进行，与“只能选一个”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相互冲击", "is_correct": false, "explanation": "语义：“相互冲击”指彼此撞击、相互影响，与后文“生活很稳定”相矛盾。"}, {"text": "并行不悖", "is_correct": true, "explanation": "正确：“并行不悖”指两件事能同时进行、互不冲突，与“生活很稳定”相合。"}, {"text": "翻脸", "is_correct": false, "explanation": "配价：“翻脸”需要有人作施事，“工作和家庭”这类事物不能翻脸。"}, {"text": "冷战", "is_correct": false, "explanation": "语域：“冷战”是口语化的比喻说法，与这句平实的叙述不协调，也不能表示两者互不影响。"}], "explanations": {"相互冲击": "语义：“相互冲击”指彼此撞击、相互影响，与后文“生活很稳定”相矛盾。", "并行不悖": "正确：“并行不悖”指两件事能同时进行、互不冲突，与“生活很稳定”相合。", "翻脸": "配价：“翻脸”需要有人作施事，“工作和家庭”这类事物不能翻脸。", "冷战": "语域：“冷战”是口语化的比喻说法，与这句平实的叙述不协调，也不能表示两者互不影响。"}, "sentence_index": 6, "correct_answer": "并行不悖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他俩的脾气并行不悖，见面就吵。", "explanation": "这里应该用〈水火不容〉。“并行不悖”表示互不冲突，与“见面就吵”的意思矛盾。"}, {"text": "他写作业和看电视并行不悖，先写完再看。", "explanation": "这里应该用〈依次〉。“并行不悖”表示同时进行，与“先写完再看”的先后次序矛盾。"}, {"text": "这两件事并行不悖，不能同时做。", "explanation": "这里应该用〈相互排斥〉。“并行不悖”表示能同时进行，与“不能同时做”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学英语和练书法并行不悖得展开，我每周都能安排好。", "corrected_sentence": "学英语和练书法并行不悖地展开，我每周都能安排好。", "error_description": "“并行不悖”修饰动词“展开”时应用“地”，不能用“得”。应说“并行不悖地展开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈做饭和看剧很并行不悖，两样都不耽误。", "corrected_sentence": "妈妈做饭和看剧并行不悖，两样都不耽误。", "error_description": "错误：“并行不悖”前加了程度副词“很”。正确：直接说“并行不悖”，“很”不能修饰这个表示“同时进行”的动词性词语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
