INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "阈值是一个界限，到了这个界限，事情就会发生变化。", "primary_collocate": null, "pronunciation": "yù zhí", "ipa": "y˥˩ ʈʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "体重一到这个阈值，医生就要检查。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力超过阈值，人就容易生病。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的安全阈值是一百度。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音高于阈值，灯就会亮起来。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网速低于阈值，视频就不能播放。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每种药都有一个安全阈值，不能多吃。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨量达到阈值，城市就发出警报。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先定好阈值，再开始做实验。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把阈值写在表格最上面。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦越过阈值，情况就完全不同了。", "target_word": "阈值", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "事情到了就会变化的界限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a75f58e-1f3e-45a4-b3b5-1fb54031ee52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是变化的界限，“体重一到这个颜色”不通。"}, {"text": "阈值", "is_correct": true, "explanation": "“阈值”指事情到此会发生变化的界限，与体重达到界限时医生检查的语境相合。"}, {"text": "声音", "is_correct": false, "explanation": "语义：体重不能“到”某个声音，此处与句意不符。"}, {"text": "名堂", "is_correct": false, "explanation": "语域：“名堂”是口语词，不宜用于这一书面语境。"}], "explanations": {"颜色": "语义：“颜色”不是变化的界限，“体重一到这个颜色”不通。", "阈值": "“阈值”指事情到此会发生变化的界限，与体重达到界限时医生检查的语境相合。", "声音": "语义：体重不能“到”某个声音，此处与句意不符。", "名堂": "语域：“名堂”是口语词，不宜用于这一书面语境。"}, "sentence_index": 0, "correct_answer": "阈值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台仪器有一把阈值，超过它就会报警。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，阈值应说“一个阈值”。"}, {"text": "我们在电脑里存了一枚阈值，随时可以调用。", "explanation": "这里应该用〈个〉。“枚”用于小而扁的物件，阈值应说“一个阈值”。"}, {"text": "他在墙上写了一首阈值，供大家阅读。", "explanation": "这里应该用〈个〉。“首”用于诗歌，阈值不是诗，应说“一个阈值”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：雨量不能“达到”某种味道，此处与句意不符。"}, {"text": "阈值", "is_correct": true, "explanation": "“阈值”指事情到此会变化的界限，雨量达到它时城市发出警报，语境相合。"}, {"text": "凳子", "is_correct": false, "explanation": "语义：雨量不能“达到”凳子，与降雨和警报的语境不符。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：雨量不能达到“脚步”，与句中的降雨和警报语境不符。"}], "explanations": {"味道": "语义：雨量不能“达到”某种味道，此处与句意不符。", "阈值": "“阈值”指事情到此会变化的界限，雨量达到它时城市发出警报，语境相合。", "凳子": "语义：雨量不能“达到”凳子，与降雨和警报的语境不符。", "脚步": "语义：雨量不能达到“脚步”，与句中的降雨和警报语境不符。"}, "sentence_index": 6, "correct_answer": "阈值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把阈值擦亮了，机器才能运行。", "explanation": "阈值是数值界限，不能被擦亮，此处应说设定。"}, {"text": "这个阈值很温柔，让人很舒服。", "explanation": "“温柔”形容性情或态度，阈值是数值界限，只能说高或低，不能用温柔来形容。"}, {"text": "他一口把阈值喝了下去。", "explanation": "“喝”指饮用液体的动作，阈值是数值界限，与饮用义不相容，不能被喝下去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套仪器设了两条阈值，分别对应两档报警。", "corrected_sentence": "这套仪器设了两个阈值，分别对应两档报警。", "error_description": "错误：量词“条”用于细长的东西，阈值应用量词“个”，写作“两个阈值”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各个阈值们都需要重新核对。", "corrected_sentence": "各个阈值都需要重新核对。", "error_description": "错误：“各个”已表示多个，“阈值”后不能再加“们”。正确：去掉“们”，说“各个阈值”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
