INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23788, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "充满生气的力量。", "primary_collocate": null, "pronunciation": "huó lì", "ipa": "xu̯ɔ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们很有活力。", "target_word": "活力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市充满了活力。", "target_word": "活力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上跑步让我很有活力。", "target_word": "活力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的脸上有年轻人的活力。", "target_word": "活力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司需要新的活力。", "target_word": "活力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的笑声里有很多活力。", "target_word": "活力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的公园里满是活力。", "target_word": "活力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人的活力让大家很高兴。", "target_word": "活力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝了热茶，我又有了活力。", "target_word": "活力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作时没有一点活力。", "target_word": "活力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股活力", "label": "量词"}, {"form": "青春活力", "label": "复合"}, {"form": "活力四射", "label": "成语"}], "register": "中性", "sense_fingerprint": "人或事物所具有的生气和旺盛的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89628db-2a92-48c4-bb2a-aa8338e4bf66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活力", "is_correct": true, "explanation": "正确。“孩子们很有活力”指孩子们充满生气。"}, {"text": "财富", "is_correct": false, "explanation": "语义：“财富”指钱财等物质资源，与“孩子们很有”的语境不符。"}, {"text": "皱纹", "is_correct": false, "explanation": "体貌：皱纹是老人的特征，不能说孩子们很有皱纹。"}, {"text": "权力", "is_correct": false, "explanation": "语义：“权力”指支配他人的力量，与孩子们的特点不符。"}], "explanations": {"活力": "正确。“孩子们很有活力”指孩子们充满生气。", "财富": "语义：“财富”指钱财等物质资源，与“孩子们很有”的语境不符。", "皱纹": "体貌：皱纹是老人的特征，不能说孩子们很有皱纹。", "权力": "语义：“权力”指支配他人的力量，与孩子们的特点不符。"}, "sentence_index": 0, "correct_answer": "活力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身上有一只活力。", "explanation": "这里应该用〈股〉。活力是抽象名词，量词用“一股活力”；“一只”只用于具体的动物或器物。"}, {"text": "他用活力推开了那扇沉重的门。", "explanation": "这里应该用〈力量〉。推开门要靠体力，活力指充满生气的精神状态，不能用来推门。"}, {"text": "他很快掌握了活力。", "explanation": "这里应该用〈技能〉。“掌握”用于知识、技能等，活力是精神状态，不能被掌握。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活力", "is_correct": true, "explanation": "正确。“春天的公园里满是活力”指公园里生机勃勃。"}, {"text": "雪", "is_correct": false, "explanation": "语义：春天不会满是雪，与“春天”的季节相矛盾。"}, {"text": "冰", "is_correct": false, "explanation": "语义：春天的公园里不会满是冰，与季节不符。"}, {"text": "胡子", "is_correct": false, "explanation": "体貌：胡子长在人身上，不能说公园里满是胡子。"}], "explanations": {"活力": "正确。“春天的公园里满是活力”指公园里生机勃勃。", "雪": "语义：春天不会满是雪，与“春天”的季节相矛盾。", "冰": "语义：春天的公园里不会满是冰，与季节不符。", "胡子": "体貌：胡子长在人身上，不能说公园里满是胡子。"}, "sentence_index": 6, "correct_answer": "活力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一点活力倒进了杯子里。", "explanation": "这里的“活力”是抽象的生气，不是可以倒进杯子的液体，把它当成液体来倒是误用。"}, {"text": "他用刷子刷了一下桌上的活力。", "explanation": "这里的“活力”是抽象的生气，不是可以用刷子刷的有形表面，把它当成实物来刷是误用。"}, {"text": "他把活力切成了几块。", "explanation": "这里的“活力”是抽象的生气，不是可以切成块的有形实物，把它当成实物来切是误用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时有一个活力。", "corrected_sentence": "他年轻时有一股活力。", "error_description": "错误：“一个活力”。正确：“一股活力”。“活力”是抽象名词，量词用“股”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他工作的时候有很活力。", "corrected_sentence": "他工作的时候很有活力。", "error_description": "错误：“有很活力”。正确：“很有活力”。副词“很”要放在“有”前面，修饰“有活力”这个整体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
