INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23790, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放进里面。", "primary_collocate": null, "pronunciation": "nèi qiàn", "ipa": "nei˥˩ tɕʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "工人把小灯内嵌在墙里。", "target_word": "内嵌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子内嵌了一块玻璃。", "target_word": "内嵌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在门上内嵌一块铁片。", "target_word": "内嵌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个盒子内嵌着很小的电池。", "target_word": "内嵌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅想把石头内嵌进地板里。", "target_word": "内嵌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手表内嵌了一块小磁铁。", "target_word": "内嵌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板中间内嵌过一条金属线。", "target_word": "内嵌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的桌面内嵌一个小水池。", "target_word": "内嵌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要把音箱内嵌在沙发里。", "target_word": "内嵌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上内嵌着一盏很小的灯。", "target_word": "内嵌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "内嵌了", "label": "体标"}, {"form": "内嵌着", "label": "体标"}, {"form": "内嵌过", "label": "体标"}, {"form": "内嵌式", "label": "复合"}], "register": "书面语", "sense_fingerprint": "把东西放进某物里面固定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a75f58e-1f3e-45a4-b3b5-1fb54031ee52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内嵌", "is_correct": true, "explanation": "正确。“内嵌”指把小灯嵌进墙内，与“在墙里”相符。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”指悬挂在表面，不能说“挂在墙里”。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”用于采摘或取下，“摘在墙里”说不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：小灯不能被吃，句子语义荒谬。"}], "explanations": {"内嵌": "正确。“内嵌”指把小灯嵌进墙内，与“在墙里”相符。", "挂": "搭配：“挂”指悬挂在表面，不能说“挂在墙里”。", "摘": "搭配：“摘”用于采摘或取下，“摘在墙里”说不通。", "吃": "语义：小灯不能被吃，句子语义荒谬。"}, "sentence_index": 0, "correct_answer": "内嵌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把书内嵌在书架上。", "explanation": "这里应该用〈放〉。“内嵌”指把东西嵌进物体内部、固定下来，书只是放在书架上，要用〈放〉。"}, {"text": "他把花瓶内嵌在桌子旁边。", "explanation": "这里用的是“内嵌”放进里面的含义。花瓶摆在桌子旁边，并不在里面，与此不符。"}, {"text": "我把相框内嵌在墙边的椅子上。", "explanation": "这里用的是“内嵌”放进里面的含义。相框放在椅子上，并不在里面，与此不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内嵌", "is_correct": true, "explanation": "正确。“内嵌”指嵌进地板内部，与“地板中间……过一条金属线”相符。"}, {"text": "游", "is_correct": false, "explanation": "语义：地板不能游泳，“游”与句子的主语不相容。"}, {"text": "晒", "is_correct": false, "explanation": "语义：在地板中间“晒”金属线说不通，句意荒谬。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”用于植物或种子，不能在地板里种金属线。"}], "explanations": {"内嵌": "正确。“内嵌”指嵌进地板内部，与“地板中间……过一条金属线”相符。", "游": "语义：地板不能游泳，“游”与句子的主语不相容。", "晒": "语义：在地板中间“晒”金属线说不通，句意荒谬。", "种": "搭配：“种”用于植物或种子，不能在地板里种金属线。"}, "sentence_index": 6, "correct_answer": "内嵌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在冰箱门上内嵌了一张照片。", "explanation": "这里应该用〈贴〉。“内嵌”指嵌入物体内部，照片只是贴在冰箱门表面，要用〈贴〉。"}, {"text": "他用夹子把纸内嵌在本子上。", "explanation": "这里应该用〈夹〉。“内嵌”指嵌进内部、固定为一体，纸只是用夹子夹在本子上，要用〈夹〉。"}, {"text": "他把纸条内嵌在信封的背面。", "explanation": "这里用的是“内嵌”放进里面的含义。纸条贴在信封背面，并不在里面，与此不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张床头柜内嵌了着一个小抽屉。", "corrected_sentence": "这张床头柜内嵌着一个小抽屉。", "error_description": "体标重复：“着”已表示状态持续，不能再加“了”；应说“内嵌着”，不能说“内嵌了着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "师傅把铜片内嵌木板里。", "corrected_sentence": "师傅把铜片内嵌到木板里。", "error_description": "介词缺失：“内嵌”后要用“在”“到”等介词引出位置，应说“内嵌到木板里”（或“内嵌在木板里”），不能直接接“木板里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83e06318-6323-400a-a087-e878aa79cb0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
