INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人一起打的一场大仗。", "primary_collocate": null, "pronunciation": "zhàn yì", "ipa": "ʈʂan˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "昨天的战役规模很大，很多人参加。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在那场战役里受了伤。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷给我讲过一场大战役。", "target_word": "战役", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场战役有几万人参加。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战役结束了，大家都很累。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里有一场很大的战役。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那次战役，我们的军队赢了。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们准备明天参加一场战役。", "target_word": "战役", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场战役打了三天三夜。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战役中，两边的士兵都很勇敢。", "target_word": "战役", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "戰役", "label": "繁体"}], "register": "中性", "sense_fingerprint": "战役：很多人参加的一场大仗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95756784-a357-49e5-a269-cb900d86ae7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战役", "is_correct": true, "explanation": "正确。“战役”指很多人参加的大仗，与“很多人参加”相符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能有“很多人参加”，也谈不上“很大”的战役规模。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能说“很多人参加”，句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“很多人参加”只能修饰活动，不能修饰手机。"}], "explanations": {"战役": "正确。“战役”指很多人参加的大仗，与“很多人参加”相符。", "蛋糕": "语义：蛋糕是食物，不能有“很多人参加”，也谈不上“很大”的战役规模。", "小猫": "语义：小猫是动物，不能说“很多人参加”，句意不通。", "手机": "搭配：“很多人参加”只能修饰活动，不能修饰手机。"}, "sentence_index": 0, "correct_answer": "战役"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场战役只有几个人参加。", "explanation": "这里应该用〈战斗〉。战役指很多人参加的大仗，只有几个人参加的交火应说战斗。"}, {"text": "这场战役的比分是三比二。", "explanation": "这里应该用〈比赛〉。“比分”属于体育比赛，战役是军事上很多人一起打的大仗。"}, {"text": "两人的战役只有两个人参加。", "explanation": "这里应该用〈对决〉。战役需要很多人一起作战，两人之间的较量不能称战役。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战役", "is_correct": true, "explanation": "正确。“那次战役”指军队参与的一场大仗，与“我们的军队赢了”相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：军队不参加考试，“那次考试，我们的军队赢了”说不通。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“赢”的对象是对手或战争，不能说赢了午饭。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是可以被打赢的对象，“那次雨，我们的军队赢了”说不通。"}], "explanations": {"战役": "正确。“那次战役”指军队参与的一场大仗，与“我们的军队赢了”相符。", "考试": "语义：军队不参加考试，“那次考试，我们的军队赢了”说不通。", "午饭": "搭配：“赢”的对象是对手或战争，不能说赢了午饭。", "雨": "语义：雨不是可以被打赢的对象，“那次雨，我们的军队赢了”说不通。"}, "sentence_index": 6, "correct_answer": "战役"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场战役中，两边的选手互相切磋，没有人受伤。", "explanation": "这里应该用〈比武〉。战役是很多人一起打的大仗，互相切磋、没有人受伤的比试应说比武。"}, {"text": "这场战役的冠军拿到了一块金牌。", "explanation": "这里应该用〈比赛〉。冠军和金牌属于体育比赛，战役是军事上很多人一起打的大仗。"}, {"text": "战役中，双方的论点都很清楚，评委最后做出了判断。", "explanation": "这里应该用〈辩论〉。战役是军事上的大规模作战，口头论争不能称战役。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几万人参加了这只战役。", "corrected_sentence": "几万人参加了这场战役。", "error_description": "“战役”的量词应用“场”，不能用“只”。错误形式：这只战役；正确形式：这场战役。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他爷爷年轻时参加过一只战役。", "corrected_sentence": "他爷爷年轻时参加过一场战役。", "error_description": "“战役”的量词应用“场”，不能用“只”。错误形式：一只战役；正确形式：一场战役。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
