INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23796, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保护某人或某物，不让它受到伤害。", "primary_collocate": null, "pronunciation": "shǒu hù", "ipa": "ʂou˨˩ xu˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈整夜守护在生病的孩子身边。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗守护着主人的家。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发誓要守护她一辈子。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用双手守护着这个家。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑士守护着年轻的公主。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母鸡张开翅膀守护小鸡。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察守护着那位重要的证人。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他张开手臂，守护着身后的妹妹。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶守护着这棵老树很多年了。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士守护着刚出生的宝宝。", "target_word": "守护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "守护了", "label": "体标（了）"}, {"form": "守护着", "label": "体标（着）"}, {"form": "守护过", "label": "体标（过）"}, {"form": "守护神", "label": "复合词"}, {"form": "守護", "label": "繁体"}], "register": "中性", "sense_fingerprint": "守护：陪在某人或某物身边，保护它不受伤害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95756784-a357-49e5-a269-cb900d86ae7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "守护", "is_correct": true, "explanation": "正确：“守护”指陪在身边保护，与“妈妈整夜……在生病的孩子身边”相合。"}, {"text": "游荡", "is_correct": false, "explanation": "语义：“游荡”指无目的地走动，与整夜陪在病孩身边的意思不符。"}, {"text": "藏", "is_correct": false, "explanation": "语义：“藏”是隐藏，与照顾生病孩子的语境相反。"}, {"text": "溜达", "is_correct": false, "explanation": "语义：“溜达”指随意散步，不表示整夜陪在身边保护。"}], "explanations": {"守护": "正确：“守护”指陪在身边保护，与“妈妈整夜……在生病的孩子身边”相合。", "游荡": "语义：“游荡”指无目的地走动，与整夜陪在病孩身边的意思不符。", "藏": "语义：“藏”是隐藏，与照顾生病孩子的语境相反。", "溜达": "语义：“溜达”指随意散步，不表示整夜陪在身边保护。"}, "sentence_index": 0, "correct_answer": "守护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他挺身守护着敌人的进攻。", "explanation": "这里应该用〈抵抗〉。“守护”是保护使不受伤害，对敌人的进攻要说“抵抗”。"}, {"text": "他在屋檐下守护了一场大雨。", "explanation": "这里应该用〈躲过〉。在屋檐下避雨要说“躲过”，雨不是需要保护的对象。"}, {"text": "父亲守护着孩子的哭声。", "explanation": "这里应该用〈忽视〉。对孩子的哭声不理会要说“忽视”，“守护”是保护的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "守护", "is_correct": true, "explanation": "正确：“守护着那位重要的证人”指保护证人，与语境相合。"}, {"text": "赶走", "is_correct": false, "explanation": "语义：“赶走”是驱逐，与保护重要证人的意思相反。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能用于证人这样的人。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”是毁坏，与保护证人的意思相反。"}], "explanations": {"守护": "正确：“守护着那位重要的证人”指保护证人，与语境相合。", "赶走": "语义：“赶走”是驱逐，与保护重要证人的意思相反。", "修理": "搭配：“修理”的对象是器物，不能用于证人这样的人。", "烧毁": "语义：“烧毁”是毁坏，与保护证人的意思相反。"}, "sentence_index": 6, "correct_answer": "守护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他守护了朋友的邀请。", "explanation": "这里应该用〈拒绝〉。拒绝的是邀请，“守护”是保护的意思，不能用于邀请。"}, {"text": "他守护了这个问题。", "explanation": "这里应该用〈回避〉。回避问题是躲开不谈，“守护”是保护的意思，不能用于问题。"}, {"text": "小偷守护了钱包。", "explanation": "这里应该用〈偷走〉。偷钱包要说“偷走”，“守护”是保护，与偷窃的行为完全相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护工把病人守护了好。", "corrected_sentence": "护工把病人守护好了。", "error_description": "补语位置错误：“守护好”中的“好”是结果补语，“了”应放在句尾，说“守护好了”，不能说“守护了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察守护着了那位证人。", "corrected_sentence": "警察守护着那位证人。", "error_description": "体标错误：“守护”后只用“着”表示持续，不能同时加“了”，“着了”重复体标。正确说法是“警察守护着那位证人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
