INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23806, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一定要。", "primary_collocate": null, "pronunciation": "bì xū", "ipa": "pi˥˩ ɕy˥", "syllable_count": 2, "sentences": [{"text": "过马路时必须看红绿灯。", "target_word": "必须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你明天必须早点儿来。", "target_word": "必须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的人必须系安全带。", "target_word": "必须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病好以前，你必须多休息。", "target_word": "必须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须在六点前到家。", "target_word": "必须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课时，学生必须关手机。", "target_word": "必须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想学好中文，就必须每天练习。", "target_word": "必须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很重要，你必须告诉他。", "target_word": "必须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进博物馆必须先买票。", "target_word": "必须", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他必须吃药。", "target_word": "必须", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：表示事理或情况上一定要这样做，后接动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb4457-02e8-4e80-8df6-6e789a775f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必须", "is_correct": true, "explanation": "正确：“必须”表示事理上一定要这样做，与“过马路时看红绿灯”的要求一致。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”多修饰形容词或少数心理动词（如“很喜欢”），不能修饰动作动词“看”，“过马路时很看红绿灯”不通。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”要接形容词或状态词，不能直接修饰动词“看”。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有转折语境，读起来不通。"}], "explanations": {"必须": "正确：“必须”表示事理上一定要这样做，与“过马路时看红绿灯”的要求一致。", "很": "搭配：“很”多修饰形容词或少数心理动词（如“很喜欢”），不能修饰动作动词“看”，“过马路时很看红绿灯”不通。", "太": "搭配：“太”要接形容词或状态词，不能直接修饰动词“看”。", "却": "语义：“却”表示转折，句中没有转折语境，读起来不通。"}, "sentence_index": 0, "correct_answer": "必须"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天必须会下雨。", "explanation": "这里应该用〈一定〉。“必须”表示事理上的要求，不表示推测，推测要用“一定”。"}, {"text": "这是生活的必须品。", "explanation": "这里应该用〈必需〉。“必需品”是固定说法，“必须”不能修饰名词。"}, {"text": "昨天他必须迟到了。", "explanation": "这里应该用〈肯定〉。“必须”不表示对过去的推测，说过去的推测要用“肯定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必须", "is_correct": true, "explanation": "正确：“必须”表示事理上一定要这样做，与“想学好中文就要每天练习”的语境一致。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”多修饰形容词或心理动词（如“非常喜欢”），不能修饰动作动词“练习”，“就非常每天练习”不通。"}, {"text": "比较", "is_correct": false, "explanation": "搭配：“比较”多修饰形容词或心理动词，不能修饰动作动词“练习”，“就比较每天练习”不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“每天”矛盾。"}], "explanations": {"必须": "正确：“必须”表示事理上一定要这样做，与“想学好中文就要每天练习”的语境一致。", "非常": "搭配：“非常”多修饰形容词或心理动词（如“非常喜欢”），不能修饰动作动词“练习”，“就非常每天练习”不通。", "比较": "搭配：“比较”多修饰形容词或心理动词，不能修饰动作动词“练习”，“就比较每天练习”不通。", "偶尔": "语义：“偶尔”表示不常发生，与“每天”矛盾。"}, "sentence_index": 6, "correct_answer": "必须"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "只有努力，才必须成功。", "explanation": "这里应该用〈才能〉。“才能”表示能力或可能，“必须”表示事理上的要求，不能这样替换。"}, {"text": "那个人必须可能是老师。", "explanation": "这里应删去〈必须〉。“必须”表示事理上的要求，不能与表示推测的“可能”连用；去掉“必须”即为“那个人可能是老师”。"}, {"text": "他昨天必须没来。", "explanation": "这里应删去〈必须〉。“必须”表示一定要做某事，不能和“没”一起说过去没发生的事；应说“他昨天没来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天必须早到过。", "corrected_sentence": "我们明天必须早到。", "error_description": "错误：“必须早到过”。正确：“必须早到”。“必须”表示事理上一定要做的事，说的是将来的要求，后面的动词不能加表示过去经历的“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个工作他必须了完成。", "corrected_sentence": "这个工作他必须完成。", "error_description": "错误：“必须了完成”。正确：“必须完成”。“了”表示完成，不能加在“必须”后面，“必须”只表示事理上的要求。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
