INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人或部门应该做的事情和起到的作用。", "primary_collocate": null, "pronunciation": "zhí néng", "ipa": "ʈʂɨ˧˥ nəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "每个部门都有自己的职能。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要先弄清楚自己的职能。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保安的职能是保护大家的安全。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说，每个人的职能不一样。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司销售部门的职能很明确。", "target_word": "职能", "complexity_tier": "T3", "furigana": "wǒ men gōng sī xiāo shòu bù mén de zhí néng hěn míng què.", "sentence_source": "generated"}, {"text": "秘书的职能包括安排会议。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小组的职能是接待客人。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有完成自己职能范围内的工作。", "target_word": "职能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的同事还不了解部门的职能。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家按各自的职能分工合作。", "target_word": "职能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "职能部门", "label": "复合"}, {"form": "職能", "label": "繁体"}], "register": "书面", "sense_fingerprint": "职能：人或部门应做的事和起的作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95756784-a357-49e5-a269-cb900d86ae7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职能", "is_correct": true, "explanation": "正确：“职能”指部门应做的事和起的作用，与“每个部门都有自己的……”相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，部门不说“自己的年龄”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是身体特征，部门没有体重。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的身体特征，部门没有身高，句子说不通。"}], "explanations": {"职能": "正确：“职能”指部门应做的事和起的作用，与“每个部门都有自己的……”相合。", "年龄": "语义：“年龄”指岁数，部门不说“自己的年龄”。", "体重": "体貌：“体重”是身体特征，部门没有体重。", "身高": "体貌：“身高”是人的身体特征，部门没有身高，句子说不通。"}, "sentence_index": 0, "correct_answer": "职能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被提拔为经理，担任了职能。", "explanation": "这里应该用〈职务〉。“担任”后面说的是职务，“职能”不是职位。"}, {"text": "他的职能是厨师。", "explanation": "这里应该用〈职业〉。说一个人做什么工作要用“职业”，“职能”不指人的身份。"}, {"text": "他每个月的职能是八千元。", "explanation": "这里应该用〈工资〉。每月的八千元是工资，“职能”不能用来指金额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职能", "is_correct": true, "explanation": "正确：“职能”指小组应做的事，与“这个小组的……是接待客人”相合。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：“饭量”指吃饭的多少，不能说“是接待客人”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只描述人的外形，小组没有身高。"}, {"text": "哥们儿", "is_correct": false, "explanation": "语域：“哥们儿”是口语，称呼人的词，不能用于小组的职责。"}], "explanations": {"职能": "正确：“职能”指小组应做的事，与“这个小组的……是接待客人”相合。", "饭量": "语义：“饭量”指吃饭的多少，不能说“是接待客人”。", "身高": "体貌：“身高”只描述人的外形，小组没有身高。", "哥们儿": "语域：“哥们儿”是口语，称呼人的词，不能用于小组的职责。"}, "sentence_index": 6, "correct_answer": "职能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他评上了高级职能。", "explanation": "这里应该用〈职称〉。评上的是专业技术职称，“职能”指职责和作用，不能说“评上”。"}, {"text": "他取得了律师职能。", "explanation": "这里应该用〈资格〉。取得的是执业资格，“职能”不能用来指资格。"}, {"text": "他的职能很好听。", "explanation": "这里应该用〈名字〉。好听的是名字，“职能”指职责，不是人的称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他负责一台重要的职能，就是每天检查设备。", "corrected_sentence": "他负责一项重要的职能，就是每天检查设备。", "error_description": "量词错误：“职能”应计量为“项”，不能用“台”。正确说法是“负责一项重要的职能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院除了治病，还有一本重要的社会职能。", "corrected_sentence": "医院除了治病，还有一项重要的社会职能。", "error_description": "量词错误：“职能”不能用“本”（“本”用于书册），应计量为“项”。正确说法是“一项重要的社会职能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fe74a2-2fe3-4043-92c8-5b9f31e7dfce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23810, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防御", "is_correct": true, "explanation": "防御：抵挡、躲避对方的进攻，与“攻击”构成反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运：把物体从一处移到另一处，与“攻击”没有反义关系。"}, {"text": "种植", "is_correct": false, "explanation": "种植：栽种植物，与“攻击”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察：仔细看、了解情况，与“攻击”没有反义关系。"}], "correct_answer": "防御", "explanations": {"防御": "防御：抵挡、躲避对方的进攻，与“攻击”构成反义关系。", "搬运": "搬运：把物体从一处移到另一处，与“攻击”没有反义关系。", "种植": "种植：栽种植物，与“攻击”没有反义关系。", "观察": "观察：仔细看、了解情况，与“攻击”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23810, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防守", "is_correct": true, "explanation": "防守：守住阵地、抵挡对方进攻，与“攻击”构成反义关系。"}, {"text": "阅读", "is_correct": false, "explanation": "阅读：看文字内容并理解，与“攻击”没有反义关系。"}, {"text": "烹饪", "is_correct": false, "explanation": "烹饪：做饭菜，与“攻击”没有反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "休息：停下活动、放松，与“攻击”没有反义关系。"}], "correct_answer": "防守", "explanations": {"防守": "防守：守住阵地、抵挡对方进攻，与“攻击”构成反义关系。", "阅读": "阅读：看文字内容并理解，与“攻击”没有反义关系。", "烹饪": "烹饪：做饭菜，与“攻击”没有反义关系。", "休息": "休息：停下活动、放松，与“攻击”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23810, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打别人。", "primary_collocate": null, "pronunciation": "gōng jī", "ipa": "kʊŋ˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "那个人突然攻击了路过的学生。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗看到陌生人，就会攻击。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝醉了酒，开始攻击身边的人。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫害怕的时候，也会攻击人。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，是他先攻击了老人。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么攻击你的同学？", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟会攻击走近鸟窝的人。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用拳头攻击了对方。", "target_word": "攻击", "complexity_tier": "T3", "furigana": "tā yòng quántou gōngjī le duìfāng", "sentence_source": "generated"}, {"text": "孩子生气时，不应该攻击别人。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤了，因为有人攻击了他。", "target_word": "攻击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "攻击了", "label": "完成体"}, {"form": "攻击着", "label": "持续体"}, {"form": "攻击过", "label": "经历体"}, {"form": "攻击性", "label": "复合词"}, {"form": "攻擊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "攻击：动手打人，对人进行身体上的伤害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c5aa7d-598b-40b2-9bba-04033b920a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "攻击", "is_correct": true, "explanation": "正确答案。攻击（gōng jī）指动手打人，与音频一致。"}, {"text": "供给", "is_correct": false, "explanation": "供给（gōng jǐ）：jǐ（第三声）与 jī（第一声）声调不同，意思是供应、提供。"}, {"text": "功绩", "is_correct": false, "explanation": "功绩（gōng jì）：jì（第四声）与 jī（第一声）声调不同，意思是功劳和成绩。"}, {"text": "公斤", "is_correct": false, "explanation": "公斤（gōng jīn）：jīn 比 jī 多一个韵尾 n，意思是重量单位千克。"}], "explanations": {"攻击": "正确答案。攻击（gōng jī）指动手打人，与音频一致。", "供给": "供给（gōng jǐ）：jǐ（第三声）与 jī（第一声）声调不同，意思是供应、提供。", "功绩": "功绩（gōng jì）：jì（第四声）与 jī（第一声）声调不同，意思是功劳和成绩。", "公斤": "公斤（gōng jīn）：jīn 比 jī 多一个韵尾 n，意思是重量单位千克。"}, "sentence_index": null, "correct_answer": "攻击"}, "level_3": {"options": [{"text": "攻击", "is_correct": true, "explanation": "正确：“攻击”指动手打人，与“突然”和“路过的学生”搭配自然。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”是不及物动词，后面不能直接带宾语“路过的学生”。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：“驾驶”的对象是车辆，不能用来对人做动作，句子说不通。"}, {"text": "养成", "is_correct": false, "explanation": "搭配：“养成”后面接习惯，不说“养成学生”。"}], "explanations": {"攻击": "正确：“攻击”指动手打人，与“突然”和“路过的学生”搭配自然。", "结婚": "配价：“结婚”是不及物动词，后面不能直接带宾语“路过的学生”。", "驾驶": "语义：“驾驶”的对象是车辆，不能用来对人做动作，句子说不通。", "养成": "搭配：“养成”后面接习惯，不说“养成学生”。"}, "sentence_index": 0, "correct_answer": "攻击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我花了一个晚上，终于攻击了那道难题。", "explanation": "这里应该用〈攻克〉。攻击指动手打人或打击对方，攻克用于难题、堡垒，二者不能互换。"}, {"text": "他在大学攻击法律专业。", "explanation": "这里应该用〈攻读〉。攻击表示打击对方，学习某个专业要用攻读，「攻击专业」不成立。"}, {"text": "球队在第八十分钟攻击一球，扳平了比分。", "explanation": "这里应该用〈攻入〉。攻击表示打击对方，足球进球要用攻入，攻击的对象不能是球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23810, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "攻击", "is_correct": true, "explanation": "正确答案。攻击（gōng jī）指动手打人，与音频一致。"}, {"text": "工期", "is_correct": false, "explanation": "工期（gōng qī）：qī 与 jī 只差声母，意思是工程的期限。"}, {"text": "共计", "is_correct": false, "explanation": "共计（gòng jì）：声母韵母相同，但两个字的声调都不同（第四声），意思是总共、合计。"}, {"text": "通缉", "is_correct": false, "explanation": "声母：tōng 与 gōng 只差声母，意思是下令搜捕。"}], "explanations": {"攻击": "正确答案。攻击（gōng jī）指动手打人，与音频一致。", "工期": "工期（gōng qī）：qī 与 jī 只差声母，意思是工程的期限。", "共计": "共计（gòng jì）：声母韵母相同，但两个字的声调都不同（第四声），意思是总共、合计。", "通缉": "声母：tōng 与 gōng 只差声母，意思是下令搜捕。"}, "sentence_index": null, "correct_answer": "攻击"}, "level_3": {"options": [{"text": "攻击", "is_correct": true, "explanation": "正确：“攻击”指动手伤害靠近鸟窝的人，与“会”和“走近鸟窝的人”搭配自然。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，后面不能带宾语“走近鸟窝的人”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能说唱“人”，与“走近鸟窝的人”搭配不通。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”后接活动、比赛等，不说“举办人”。"}], "explanations": {"攻击": "正确：“攻击”指动手伤害靠近鸟窝的人，与“会”和“走近鸟窝的人”搭配自然。", "散步": "配价：“散步”是不及物动词，后面不能带宾语“走近鸟窝的人”。", "唱": "语义：“唱”的对象是歌曲，不能说唱“人”，与“走近鸟窝的人”搭配不通。", "举办": "搭配：“举办”后接活动、比赛等，不说“举办人”。"}, "sentence_index": 6, "correct_answer": "攻击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里来了一只狗，他用棍子把它攻击走了。", "explanation": "这里应该用〈驱赶〉。攻击表示打击、伤害，不表示把人或动物赶走，“攻击走”不成立。"}, {"text": "他用了三个小时才攻击了作业。", "explanation": "这里应该用〈完成〉。攻击表示打击对方，做完作业要说完成，「攻击作业」不成立。"}, {"text": "医生仔细攻击了病人的脸色。", "explanation": "这里应该用〈观察〉。攻击表示打击对方，仔细查看病人的脸色要用观察，「攻击脸色」不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只狗正在攻击了路过的人。", "corrected_sentence": "那只狗正在攻击路过的人。", "error_description": "错误：“正在”表示动作正在进行，不能同时在“攻击”后加“了”（表示完成）。正确应为“正在攻击路过的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天攻击了我两个。", "corrected_sentence": "他昨天攻击了我两次。", "error_description": "错误：动量补语应表示动作次数，要用“次”，“个”只用于计量事物，不能计量“攻击”这一动作。正确应为“攻击了我两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
