INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23812, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把敌人全部消灭掉。", "primary_collocate": null, "pronunciation": "jiān dí", "ipa": "tɕjɛn˥ ti˧˥", "syllable_count": 2, "sentences": [{"text": "部队用了两天，歼敌一千多人。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我军包围了这股敌人，准备歼敌。", "target_word": "歼敌", "complexity_tier": "T3", "furigana": "wǒ jūn bāowéi le zhè gǔ dírén, zhǔnbèi jiān dí", "sentence_source": "generated"}, {"text": "这场战斗歼敌两千，我军很少受伤。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军命令部队：今晚必须歼敌。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小队在山谷里歼敌，一个也没跑。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不但要打退敌人，还要歼敌。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们把敌人围住，一举歼敌。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起努力，终于成功歼敌。", "target_word": "歼敌", "complexity_tier": "T3", "furigana": "dàjiā yìqǐ nǔlì, zhōngyú chénggōng jiān dí", "sentence_source": "generated"}, {"text": "他想了一个好办法，让部队顺利歼敌。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人走进山谷以后，我军马上歼敌。", "target_word": "歼敌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "彻底消灭全部敌人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c5aa7d-598b-40b2-9bba-04033b920a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23812, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘坐", "is_correct": false, "explanation": "配价：“乘坐”的宾语只能是交通工具，不能以“一千多人”作宾语。"}, {"text": "歼敌", "is_correct": true, "explanation": "“歼敌”指把敌人全部消灭，与“部队用了两天”和“一千多人”的语境相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食物，不能说“烹饪一千多人”。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指把书刊印发，不能用来指人，句意不通。"}], "explanations": {"乘坐": "配价：“乘坐”的宾语只能是交通工具，不能以“一千多人”作宾语。", "歼敌": "“歼敌”指把敌人全部消灭，与“部队用了两天”和“一千多人”的语境相符。", "烹饪": "搭配：“烹饪”的对象是食物，不能说“烹饪一千多人”。", "出版": "语义：“出版”指把书刊印发，不能用来指人，句意不通。"}, "sentence_index": 0, "correct_answer": "歼敌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在决赛中歼敌了对手。", "explanation": "这里应该用〈战胜〉。“歼敌”是军事用语，指把敌军全部消灭，比赛中的对手不能说“歼敌”。"}, {"text": "敌人的进攻被我们歼敌了。", "explanation": "这里应该用〈击退〉。“歼敌”的对象是敌人本身，进攻不能被歼敌，只能被击退。"}, {"text": "我们终于歼敌了路上的障碍。", "explanation": "这里应该用〈扫除〉。“歼敌”只用于消灭敌人，障碍物不能作“歼敌”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投降", "is_correct": false, "explanation": "语义：战士们是包围敌人的一方，不会“一举投降”，与前句“把敌人围住”矛盾。"}, {"text": "歼敌", "is_correct": true, "explanation": "“歼敌”指一举把敌人全部消灭，与“把敌人围住”前后衔接。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：句中的战士是围住敌人的一方，不能说战士们“一举逃跑”。"}, {"text": "降温", "is_correct": false, "explanation": "搭配：“降温”指温度下降，不能用于战斗中的动作。"}], "explanations": {"投降": "语义：战士们是包围敌人的一方，不会“一举投降”，与前句“把敌人围住”矛盾。", "歼敌": "“歼敌”指一举把敌人全部消灭，与“把敌人围住”前后衔接。", "逃跑": "语义：句中的战士是围住敌人的一方，不能说战士们“一举逃跑”。", "降温": "搭配：“降温”指温度下降，不能用于战斗中的动作。"}, "sentence_index": 6, "correct_answer": "歼敌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察歼敌了两名小偷。", "explanation": "这里应该用〈抓获〉。“歼敌”指把敌军全部消灭，对罪犯不能用“歼敌”。"}, {"text": "医生歼敌了病人。", "explanation": "这里应该用〈治愈〉。“歼敌”只用于敌军，不能用于患者。"}, {"text": "渔夫在河里歼敌了一条鱼。", "explanation": "这里应该用〈捕捉〉。“歼敌”的对象是敌人，鱼不能作“歼敌”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我军连夜歼敌着三百余人。", "corrected_sentence": "我军连夜歼敌三百余人。", "error_description": "错误：“歼敌”是已完成的消灭动作，不能加表示持续的“着”。正确：去掉“着”，说“歼敌三百余人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我军在山谷里歼敌敌人五百。", "corrected_sentence": "我军在山谷里歼敌五百。", "error_description": "错误：“歼敌”本身已包含宾语“敌”，后面不能再带“敌人”。正确：“歼敌五百”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
