INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23814, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常正确，没有错误。", "primary_collocate": null, "pronunciation": "jīng zhǔn", "ipa": "tɕiŋ˥ ʈʂuən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这只手表的时间很精准。", "target_word": "精准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答非常精准。", "target_word": "精准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报越来越精准了。", "target_word": "精准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用精准的数字说明了问题。", "target_word": "精准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把尺子很精准，量出来没有错。", "target_word": "精准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员精准地把球投进了篮里。", "target_word": "精准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生需要精准的检查结果。", "target_word": "精准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图画得很精准。", "target_word": "精准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他算的数字不太精准，差了一点。", "target_word": "精准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译要精准，不能随便改意思。", "target_word": "精准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精准地", "label": "状语形式"}, {"form": "精准度", "label": "复合"}, {"form": "精準", "label": "繁体"}], "register": "中性", "sense_fingerprint": "非常准确，没有偏差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172f7e52-d98b-43ac-869e-8829631459cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精准", "is_correct": true, "explanation": "正确：“这只手表的时间很精准”指时间准确无误，与句意相符。"}, {"text": "精神", "is_correct": false, "explanation": "语义：“精神”指人的神采或有活力，用来形容时间不合适。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”说外观好看，时间不能用“漂亮”来形容。"}, {"text": "大方", "is_correct": false, "explanation": "搭配：“大方”形容人的举止或态度，不能用来修饰“时间”。"}], "explanations": {"精准": "正确：“这只手表的时间很精准”指时间准确无误，与句意相符。", "精神": "语义：“精神”指人的神采或有活力，用来形容时间不合适。", "漂亮": "语义：“漂亮”说外观好看，时间不能用“漂亮”来形容。", "大方": "搭配：“大方”形容人的举止或态度，不能用来修饰“时间”。"}, "sentence_index": 0, "correct_answer": "精准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他学习很精准，每天都很努力。", "explanation": "这里应该用〈认真〉。精准指准确无误，形容学习态度要用“认真”。"}, {"text": "这件衣服穿起来很精准，我很喜欢。", "explanation": "这里应该用〈合身〉。精准多用于数量、结果、判断，衣服合身不说“精准”。"}, {"text": "她的脾气很精准，大家都怕她。", "explanation": "这里应该用〈严厉〉。精准强调准确无误，形容脾气要用“严厉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精准", "is_correct": true, "explanation": "正确：“医生需要精准的检查结果”指结果准确无误，与句意相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面或气氛，检查结果不能说“热闹”。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容味道、声音或面容，不能用来修饰检查结果。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能用来修饰“检查结果”。"}], "explanations": {"精准": "正确：“医生需要精准的检查结果”指结果准确无误，与句意相符。", "热闹": "语义：“热闹”形容场面或气氛，检查结果不能说“热闹”。", "甜美": "语义：“甜美”形容味道、声音或面容，不能用来修饰检查结果。", "响亮": "搭配：“响亮”形容声音，不能用来修饰“检查结果”。"}, "sentence_index": 6, "correct_answer": "精准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张床很精准，我睡得很香。", "explanation": "这里应该用〈柔软〉。精准指准确无误，形容床的舒适程度要用“柔软”。"}, {"text": "他的笑容很精准，大家都很喜欢。", "explanation": "这里应该用〈灿烂〉。精准形容结果或判断，笑容不说“精准”。"}, {"text": "这盘菜的味道很精准，很好吃。", "explanation": "这里应该用〈鲜美〉。精准描述的是准确程度，味道要用“鲜美”之类的词来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台仪器的测量很精准地。", "corrected_sentence": "这台仪器的测量很精准。", "error_description": "错误形式：“很精准地”；正确形式：“很精准”。“精准地”是副词形式，作谓语时不能带“地”，句末应是形容词“精准”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说很精准。", "corrected_sentence": "他说得很精准。", "error_description": "错误形式：“他说很精准”；正确形式：“他说得很精准”。动词后带程度补语需用“得”，省略“得”后“说很精准”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
