INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "全部的情况。", "primary_collocate": null, "pronunciation": "quán jú", "ipa": "tɕʰɥɛn˧˥ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "经理让大家先了解全局。", "target_word": "全局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张地图能让你了解全局。", "target_word": "全局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先看一下全局，再看细节。", "target_word": "全局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站得高，所以看得清全局。", "target_word": "全局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时，老板先分析全局，再说小问题。", "target_word": "全局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人很难掌握全局。", "target_word": "全局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这份报告没有兼顾全局。", "target_word": "全局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很会从全局想问题。", "target_word": "全局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你不了解全局，别乱说。", "target_word": "全局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "了解全局后，他才做决定。", "target_word": "全局", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "全局观", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情各个方面合起来的全部情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301ef3b3-42bb-4b0c-bc30-88e444fa6ad5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全局", "is_correct": true, "explanation": "全局：各方面合起来的全部情况，“了解全局”符合句意。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“了解脚步”不通，脚步不是需要先了解的整体情况。"}, {"text": "夜晚", "is_correct": false, "explanation": "搭配：“了解”一般不接“夜晚”，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：经理让大家了解的是工作情况，不是“体重”，所指不符。"}], "explanations": {"全局": "全局：各方面合起来的全部情况，“了解全局”符合句意。", "脚步": "语义：“了解脚步”不通，脚步不是需要先了解的整体情况。", "夜晚": "搭配：“了解”一般不接“夜晚”，句意不通。", "体重": "语义：经理让大家了解的是工作情况，不是“体重”，所指不符。"}, "sentence_index": 0, "correct_answer": "全局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全局同学都到齐了。", "explanation": "这里应该用〈全部〉。全部指所有的人或物，全局指情况的整体，不能用来修饰人。"}, {"text": "他全局湿透了。", "explanation": "这里应该用〈全身〉。全身指从头到脚，全局指情况的整体，不能指人的身体。"}, {"text": "他全局工作了一整天。", "explanation": "这里应该用〈全天〉。全天指一整天，全局指情况的整体，不能用来修饰动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全局", "is_correct": true, "explanation": "全局：“兼顾”的对象是全部情况，符合句意。"}, {"text": "溪水", "is_correct": false, "explanation": "语义：“兼顾”的对象不能是溪水，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“兼顾”一般不接“体温”，搭配不当。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：“呼吸”不是可以兼顾的对象，句意不通。"}], "explanations": {"全局": "全局：“兼顾”的对象是全部情况，符合句意。", "溪水": "语义：“兼顾”的对象不能是溪水，句意不通。", "体温": "搭配：“兼顾”一般不接“体温”，搭配不当。", "呼吸": "语义：“呼吸”不是可以兼顾的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "全局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全局陪同着我去医院。", "explanation": "这里应该用〈全程〉。全程指整个过程，全局指情况的整体，不能用来表示陪同。"}, {"text": "他全局支持我的决定。", "explanation": "这里应该用〈全力〉。全力是副词，表示用尽力量，全局是名词，不能作状语。"}, {"text": "全局观众都站起来了。", "explanation": "这里应该用〈全场〉。全场指在场的全部人，全局指情况的整体，不指观众。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他全局很了解。", "corrected_sentence": "他对全局很了解。", "error_description": "错误在于“全局”是名词，不能直接放在“很了解”前作状语；须用介词“对”引出“全局”，说“对全局很了解”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告很好地把握了全局地变化。", "corrected_sentence": "这份报告很好地把握了全局的变化。", "error_description": "「全局」修饰名词「变化」时应用「的」，应说「全局的变化」；这里误用「地」，「地」只用于修饰动词、形容词作状语，不能接在名词修饰语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
