INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23826, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接受不好的事情。", "primary_collocate": null, "pronunciation": "chéng shòu", "ipa": "tʂʰɤŋ˧˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他承受了失去亲人的不幸。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她承受不了这个坏结果。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一次又一次承受失败的打击。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人一个人承受着生活的苦。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨冲走了房子，他们只能承受这个损失。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他默默承受了这次失败。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人每天都要承受很大的痛苦。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的坏消息，谁也很难承受。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，我不该让你承受这些委屈。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承受过很多不公平的对待。", "target_word": "承受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "承受了", "label": "完成体"}, {"form": "承受着", "label": "持续体"}, {"form": "承受过", "label": "经历体"}, {"form": "承受力", "label": "复合词"}, {"form": "承受能力", "label": "复合词"}], "register": "中性", "sense_fingerprint": "承受：接受不幸、损失、委屈等不好的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c5aa7d-598b-40b2-9bba-04033b920a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23826, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "承受", "is_correct": true, "explanation": "承受：接受不幸、损失、委屈等不好的事情。"}, {"text": "成熟", "is_correct": false, "explanation": "chéngshú：shú 与 shòu 韵母（u/ou）和声调都不同，意思是发育完全、有经验。"}, {"text": "乘数", "is_correct": false, "explanation": "shù 与 shòu 的韵母不同（u 与 ou），意思是数学中的乘数。"}, {"text": "称手", "is_correct": false, "explanation": "chènshǒu：chèn 与 chéng 韵母（en/eng）和声调不同，shǒu 与 shòu 声调不同，意思是用起来顺手。"}], "explanations": {"承受": "承受：接受不幸、损失、委屈等不好的事情。", "成熟": "chéngshú：shú 与 shòu 韵母（u/ou）和声调都不同，意思是发育完全、有经验。", "乘数": "shù 与 shòu 的韵母不同（u 与 ou），意思是数学中的乘数。", "称手": "chènshǒu：chèn 与 chéng 韵母（en/eng）和声调不同，shǒu 与 shòu 声调不同，意思是用起来顺手。"}, "sentence_index": null, "correct_answer": "承受"}, "level_3": {"options": [{"text": "承受", "is_correct": true, "explanation": "承受：接受不幸的事情，与“失去亲人的不幸”相合。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指享用愉快的事物，与“不幸”的含义相矛盾。"}, {"text": "收获", "is_correct": false, "explanation": "搭配：“收获”多用于经验、成果，不能与“不幸”搭配。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”表示欢喜地纪念，与“失去亲人”的悲伤相矛盾。"}], "explanations": {"承受": "承受：接受不幸的事情，与“失去亲人的不幸”相合。", "享受": "语义：“享受”指享用愉快的事物，与“不幸”的含义相矛盾。", "收获": "搭配：“收获”多用于经验、成果，不能与“不幸”搭配。", "庆祝": "语义：“庆祝”表示欢喜地纪念，与“失去亲人”的悲伤相矛盾。"}, "sentence_index": 0, "correct_answer": "承受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他承受了一碗热汤。", "explanation": "这里应用〈喝〉。“承受”指接受不好的事情，不能用于喝汤这类动作。"}, {"text": "周末，我们在湖边承受了一下午的微风。", "explanation": "这里应用〈享受〉。“承受”只用于压力、痛苦等不好的事，不能用于惬意的微风。"}, {"text": "他通过努力承受了很多荣誉。", "explanation": "这里应用〈获得〉。“承受”用于不好的事，不能指获得荣誉这类好事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "承受", "is_correct": true, "explanation": "承受：接受并承担痛苦，与“病人”“很大的痛苦”相合。"}, {"text": "享有", "is_correct": false, "explanation": "语义：“享有”指拥有权利或好处，与“痛苦”的含义相矛盾。"}, {"text": "发放", "is_correct": false, "explanation": "搭配：“发放”多用于物资、薪水、补助，不能与“痛苦”搭配。"}, {"text": "点缀", "is_correct": false, "explanation": "语义：“点缀”指装饰美化，与“痛苦”的含义不符。"}], "explanations": {"承受": "承受：接受并承担痛苦，与“病人”“很大的痛苦”相合。", "享有": "语义：“享有”指拥有权利或好处，与“痛苦”的含义相矛盾。", "发放": "搭配：“发放”多用于物资、薪水、补助，不能与“痛苦”搭配。", "点缀": "语义：“点缀”指装饰美化，与“痛苦”的含义不符。"}, "sentence_index": 6, "correct_answer": "承受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他承受了一台新电脑。", "explanation": "这里应用〈购买〉。“承受”指接受不好的事情，不能用于买电脑这类行为。"}, {"text": "大家都在认真承受这幅名画。", "explanation": "这里应用〈欣赏〉。“承受”的对象是不幸、损失等，不能是艺术品。"}, {"text": "他终于承受了大家的认可。", "explanation": "这里应用〈得到〉。“承受”只用于不好的事情，不能指得到认可这样的好事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于承受好了这些委屈。", "corrected_sentence": "他终于承受住了这些委屈。", "error_description": "“承受”后的结果补语应为“住”，表示能够承受下来；“好”不能作“承受”的补语，应为“承受住了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从来没承受了这样的批评。", "corrected_sentence": "她从来没承受过这样的批评。", "error_description": "表示没有经历过某事，要用“没……过”结构。“没承受了”是错误的，应为“没承受过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
