INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23828, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示一起、都，比如“我们一起去”。", "primary_collocate": null, "pronunciation": "gòng", "ipa": "kʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我们三个人共撑一把伞。", "target_word": "共", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "兄弟两人共住一间房。", "target_word": "共", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同学们共读一本书，写出想法。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "四个朋友共乘一辆车去山里。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐妹俩共住一个房间。", "target_word": "共", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家共吃一锅饭，感情很好。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老同学们共坐一张长桌，聊了很久。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家人共养一只狗。", "target_word": "共", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同事们共看一份文件，认真讨论。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们两个人共喝一杯奶茶。", "target_word": "共", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "共同", "label": "复合"}, {"form": "共用", "label": "复合"}, {"form": "共享", "label": "复合"}], "register": "书面", "sense_fingerprint": "副词，几个人一起做同一件事，后面常接动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301ef3b3-42bb-4b0c-bc30-88e444fa6ad5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23828, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共", "is_correct": true, "explanation": "共（gòng）：副词，表示几个人一起做同一件事，与听到的音相符。"}, {"text": "工", "is_correct": false, "explanation": "gōng（第一声）与 gòng（第四声）声调不同，意思是工作。"}, {"text": "攻", "is_correct": false, "explanation": "gōng（第一声）与 gòng（第四声）声调不同，意思是攻打。"}, {"text": "更", "is_correct": false, "explanation": "gèng 与 gòng 韵母不同（eng 与 ong），意思是更加。"}], "explanations": {"共": "共（gòng）：副词，表示几个人一起做同一件事，与听到的音相符。", "工": "gōng（第一声）与 gòng（第四声）声调不同，意思是工作。", "攻": "gōng（第一声）与 gòng（第四声）声调不同，意思是攻打。", "更": "gèng 与 gòng 韵母不同（eng 与 ong），意思是更加。"}, "sentence_index": null, "correct_answer": "共"}, "level_3": {"options": [{"text": "共", "is_correct": true, "explanation": "共：副词，表示三人一起做同一件事，符合“共撑一把伞”的句意。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”强调本人亲身去做，与三个人共用一把伞的意思不符。"}, {"text": "独自", "is_correct": false, "explanation": "搭配：“独自”只说一个人单独做，与“三个人”不搭配。"}, {"text": "单独", "is_correct": false, "explanation": "语义：“单独”表示个别、分开去做，与“共用”的合作义相反。"}], "explanations": {"共": "共：副词，表示三人一起做同一件事，符合“共撑一把伞”的句意。", "亲自": "语义：“亲自”强调本人亲身去做，与三个人共用一把伞的意思不符。", "独自": "搭配：“独自”只说一个人单独做，与“三个人”不搭配。", "单独": "语义：“单独”表示个别、分开去做，与“共用”的合作义相反。"}, "sentence_index": 0, "correct_answer": "共"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "四个朋友各自共乘一辆车去山里。", "explanation": "这里的〈共〉表示“一起”，与“各自”（分别、单独）相矛盾，不能说各自一起乘车。"}, {"text": "他一个人共去了公园。", "explanation": "〈共〉要求几个人一起做同一件事，只有一个主语时不能这样用。"}, {"text": "他和我分别共去了山里。", "explanation": "这里的〈共〉表示“一起”，与“分别”（各自）相矛盾，分别去不能说共去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23828, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "共", "is_correct": true, "explanation": "共（gòng）：副词，表示几个人一起做同一件事，与听到的音相符。"}, {"text": "公", "is_correct": false, "explanation": "gōng（第一声）与 gòng（第四声）声调不同，意思是公共。"}, {"text": "功", "is_correct": false, "explanation": "gōng（第一声）与 gòng（第四声）声调不同，意思是功劳、成功。"}, {"text": "控", "is_correct": false, "explanation": "k 与 g 声母不同（kòng 与 gòng），意思是控制。"}, {"text": "杠", "is_correct": false, "explanation": "ong 与 ang 韵母不同（gàng 与 gòng），意思是杠杆。"}], "explanations": {"共": "共（gòng）：副词，表示几个人一起做同一件事，与听到的音相符。", "公": "gōng（第一声）与 gòng（第四声）声调不同，意思是公共。", "功": "gōng（第一声）与 gòng（第四声）声调不同，意思是功劳、成功。", "控": "k 与 g 声母不同（kòng 与 gòng），意思是控制。", "杠": "ong 与 ang 韵母不同（gàng 与 gòng），意思是杠杆。"}, "sentence_index": null, "correct_answer": "共"}, "level_3": {"options": [{"text": "共", "is_correct": true, "explanation": "共：副词，表示几位同学一起坐一张长桌，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能修饰动词“坐”，句子不通。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”表示徒劳，与“聊了很久”的语境不符。"}, {"text": "差点", "is_correct": false, "explanation": "搭配：“差点”后接未发生的动作，不能与“坐”这种已经实现的动作搭配。"}], "explanations": {"共": "共：副词，表示几位同学一起坐一张长桌，符合句意。", "很": "语法：“很”是程度副词，不能修饰动词“坐”，句子不通。", "白": "语义：“白”表示徒劳，与“聊了很久”的语境不符。", "差点": "搭配：“差点”后接未发生的动作，不能与“坐”这种已经实现的动作搭配。"}, "sentence_index": 6, "correct_answer": "共"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试我们轮流共做一百道题。", "explanation": "这里的〈共〉表示“一起”，与“轮流”（先后交替）相矛盾，轮流做就不能说共做。"}, {"text": "我一个人共看完了那本书。", "explanation": "〈共〉要求几个人一起做同一件事，只有一个主语时不能这样用。"}, {"text": "我们俩分开共喝了两杯奶茶。", "explanation": "这里的〈共〉表示“一起”，与“分开”（分别进行）相矛盾，不能说分开一起喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们四个人独自共租一辆车。", "corrected_sentence": "我们四个人共租一辆车。", "error_description": "错误在于多加了“独自”。“独自”表示一个人单独做，与“四个人”和“共”（一起）相冲突；应去掉“独自”，说“共租”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们四个同学乘共一辆车。", "corrected_sentence": "我们四个同学共乘一辆车。", "error_description": "错误在“共”的位置。“共”是副词，要放在动词“乘”前，说“共乘”，不能放在动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
