INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情有多难。", "primary_collocate": null, "pronunciation": "fù zá dù", "ipa": "fu˥˩ tsa˧˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "这道题的复杂度不高，你可以试试。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭的复杂度比我想的高。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先看任务的复杂度，再分给学生。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事复杂度太高，一个人做不完。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请签证的复杂度让他很头疼。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修车的复杂度不大，十分钟就好了。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先告诉我这个工作的复杂度。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕复杂度高的任务。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们常常低估搬家的复杂度。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的复杂度比上次低。", "target_word": "复杂度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "復雜度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一件事或任务做起来有多难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301ef3b3-42bb-4b0c-bc30-88e444fa6ad5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复杂度", "is_correct": true, "explanation": "正确：“复杂度不高”说题目的难度低，符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：题目不说“价格”，“价格不高”无法描述题目的难易。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色说色彩，与题目的难易无关。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度说冷热，不能用来说题目的难易。"}], "explanations": {"复杂度": "正确：“复杂度不高”说题目的难度低，符合语境。", "价格": "搭配：题目不说“价格”，“价格不高”无法描述题目的难易。", "颜色": "语义：颜色说色彩，与题目的难易无关。", "温度": "语义：温度说冷热，不能用来说题目的难易。"}, "sentence_index": 0, "correct_answer": "复杂度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的复杂度很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，复杂度说事情有多难，不能形容画的颜色。"}, {"text": "这家店的复杂度很便宜。", "explanation": "这里应该用〈价格〉。“便宜”说价钱低，复杂度不能用来说店的价钱。"}, {"text": "这个西瓜的复杂度很甜。", "explanation": "这里应该用〈甜度〉。“甜”说味道，复杂度表示事情有多难，不能用来说水果的甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复杂度", "is_correct": true, "explanation": "正确：“工作的复杂度”指工作有多难，是常见说法。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」说色彩，不用来说工作的难易，句意不通。"}, {"text": "电压", "is_correct": false, "explanation": "语义：「电压」是电学概念，与工作的难易无关，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“工作的体重”不成立，体重只用于人或物体。"}], "explanations": {"复杂度": "正确：“工作的复杂度”指工作有多难，是常见说法。", "颜色": "语义：「颜色」说色彩，不用来说工作的难易，句意不通。", "电压": "语义：「电压」是电学概念，与工作的难易无关，句意不通。", "体重": "搭配：“工作的体重”不成立，体重只用于人或物体。"}, "sentence_index": 6, "correct_answer": "复杂度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的复杂度很高，大家都猜不透他。", "explanation": "这里用的不是复杂度的义项。复杂度指事情的难易，不能用来形容人的性格，应说「性格复杂」。"}, {"text": "这次考试的复杂度比上次长。", "explanation": "这里应该用〈时间〉。“长”说的是时间或距离，复杂度说事情有多难，不能用“长”来比较。"}, {"text": "这次考试的复杂度很红。", "explanation": "这里应该用〈颜色〉。「红」形容颜色，复杂度指事情的难易，不能用来形容红色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门课的复杂度很多，学生跟不上。", "corrected_sentence": "这门课的复杂度很高，学生跟不上。", "error_description": "错误形式：「复杂度很多」。「复杂度」表示程度，只能说高低，不能说多少。正确形式：「复杂度很高」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试有一只复杂度，需要认真复习。", "corrected_sentence": "这次考试有一定的复杂度，需要认真复习。", "error_description": "错误形式：“一只”，是用于动物或小物件的量词。正确形式：“一定的”，用于抽象的程度。“复杂度”是抽象名词，不能用“只”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
