INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23834, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西排成一条直线。", "primary_collocate": null, "pronunciation": "duì qí", "ipa": "tweɪ˥˩ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "请把桌子和墙对齐。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书的边角对齐，放进盒子里。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们站好队，脚尖要对齐。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贴照片时，要把四个角对齐。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这两张纸对齐，再用夹子夹住。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把鞋子对齐放在门口。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两行字没有对齐，看着很乱。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把砖头对齐，再往上放一层。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画框挂歪了，请把它和墙角对齐。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把桌上的杯子一个个对齐。", "target_word": "对齐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对齐了", "label": "完成体"}, {"form": "对齐过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把具体的物体摆成整齐的一条线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301ef3b3-42bb-4b0c-bc30-88e444fa6ad5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对齐", "is_correct": true, "explanation": "对齐：使桌子和墙排成一条线，符合“请把……”的句意。"}, {"text": "融化", "is_correct": false, "explanation": "语义：「融化」指固体受热变为液体，桌子和墙不会融化，句意不通。"}, {"text": "喝光", "is_correct": false, "explanation": "语义：「喝光」指把饮料喝完，桌子和墙不能喝，句意不通。"}, {"text": "漆", "is_correct": false, "explanation": "语义：「漆」指涂刷颜料，句意是涂装，与「排成一条线」的要求无关。"}], "explanations": {"对齐": "对齐：使桌子和墙排成一条线，符合“请把……”的句意。", "融化": "语义：「融化」指固体受热变为液体，桌子和墙不会融化，句意不通。", "喝光": "语义：「喝光」指把饮料喝完，桌子和墙不能喝，句意不通。", "漆": "语义：「漆」指涂刷颜料，句意是涂装，与「排成一条线」的要求无关。"}, "sentence_index": 0, "correct_answer": "对齐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对齐了自己的生日。", "explanation": "这里的〈对齐〉要求两个或多个事物的位置、标准一致，“自己的生日”只有一个，不能对齐，应说〈庆祝〉。"}, {"text": "他对齐了自己的心情。", "explanation": "这里应该用〈调整〉。对齐指使物体排成一条线，心情不是物体，不能对齐。"}, {"text": "老师对齐了学生的早餐。", "explanation": "这里应该用〈准备〉。对齐指使物体排成一条线，早餐不能排成一线，应说〈准备〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对齐", "is_correct": true, "explanation": "对齐：使两行字排成一条线，符合“没有……看着很乱”的句意。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：“切割”的对象是材料或物体，不能用于“字”和“行”。"}, {"text": "煮熟", "is_correct": false, "explanation": "语义：「煮熟」指用水或火使食物变熟，字不能煮熟，句意不通。"}, {"text": "染色", "is_correct": false, "explanation": "语义：「染色」指给物体上色，与字行是否整齐无关，句意不通。"}], "explanations": {"对齐": "对齐：使两行字排成一条线，符合“没有……看着很乱”的句意。", "切割": "搭配：“切割”的对象是材料或物体，不能用于“字”和“行”。", "煮熟": "语义：「煮熟」指用水或火使食物变熟，字不能煮熟，句意不通。", "染色": "语义：「染色」指给物体上色，与字行是否整齐无关，句意不通。"}, "sentence_index": 6, "correct_answer": "对齐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她对齐了那段时光。", "explanation": "这里的〈对齐〉指使物体排成一条线或标准一致，“那段时光”不能对齐，应说〈度过〉。"}, {"text": "她把桌上的杯子一个个对齐干净。", "explanation": "这里应该用〈擦〉。对齐指使物体排成一条线，不表示清洁。"}, {"text": "她对齐了那个孩子的感冒。", "explanation": "这里应该用〈治疗〉。感冒不是能排成一条线的东西，对齐不能用于此，应说〈治疗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把三张照片的边缘很对齐。", "corrected_sentence": "请把三张照片的边缘对齐。", "error_description": "错误在于在「很」修饰「对齐」。「把」字句中「很」一般不直接修饰动词「对齐」，应去掉「很」；若要描述程度，可用「整齐」，如「边缘很整齐」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把瓦片的对齐，再往上铺一层。", "corrected_sentence": "工人把瓦片对齐，再往上铺一层。", "error_description": "错误在于在“对齐”前多加了“的”。“把”字句中“对齐”是动词，应直接跟在宾语“瓦片”后面；加“的”把它变成了名词，句子不通，应说“把瓦片对齐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
