INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23840, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们共同相信的一些想法。", "primary_collocate": null, "pronunciation": "yì shí xíng tài", "ipa": "i˥˩ ʂɻ̩˧˥ ɕiŋ˧˥ tʰaɪ˥˩", "syllable_count": 4, "sentences": [{"text": "这个国家的人有共同的意识形态。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们因为意识形态不同，常常吵架。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，意识形态就是大家共同相信的想法。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个群体的意识形态会影响成员的选择。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子慢慢接受了家庭的意识形态。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的社会有不同的意识形态。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的意识形态很相近，所以成了朋友。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里常常能看到当时的意识形态。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改变意识形态不是一件容易的事。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人的意识形态和老人不太一样。", "target_word": "意识形态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "意識形態", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人们共同相信的想法和观念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94b4d57c-ba46-40c9-9d83-b3978f6c429b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意识形态", "is_correct": true, "explanation": "正确：指人们共同相信的想法，符合“共同的”语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是人们共同相信的想法，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是个人的身体属性，不能说“共同的身高”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是个人的身体属性，不能说“共同的体重”。"}], "explanations": {"意识形态": "正确：指人们共同相信的想法，符合“共同的”语境。", "天空": "语义：天空不是人们共同相信的想法，句意不通。", "身高": "搭配：“身高”是个人的身体属性，不能说“共同的身高”。", "体重": "搭配：“体重”是个人的身体属性，不能说“共同的体重”。"}, "sentence_index": 0, "correct_answer": "意识形态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的意识形态很便宜。", "explanation": "这里应该用〈价格〉。“便宜”形容价格，意识形态是抽象观念，不能说便宜。"}, {"text": "他的意识形态是当医生。", "explanation": "这里应该用〈职业〉。意识形态指群体共同相信的想法，说一个人的工作要用职业。"}, {"text": "她的意识形态是画画。", "explanation": "这里应该用〈爱好〉。画画是个人的兴趣，不是人们共同相信的想法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意识形态", "is_correct": true, "explanation": "正确：指人们共同相信的想法，符合“很相近、所以成了朋友”的语境。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与人们是否结交朋友无关，句意不通。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味不是人的想法，不能说“想法很相近”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的价钱，不能用来说人们的想法相近，句意不通。"}], "explanations": {"意识形态": "正确：指人们共同相信的想法，符合“很相近、所以成了朋友”的语境。", "体重": "语义：体重与人们是否结交朋友无关，句意不通。", "气味": "语义：气味不是人的想法，不能说“想法很相近”。", "价格": "语义：“价格”指商品的价钱，不能用来说人们的想法相近，句意不通。"}, "sentence_index": 6, "correct_answer": "意识形态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有晚睡的意识形态。", "explanation": "这里应该用〈习惯〉。晚睡是个人的生活习惯，意识形态指群体共同的想法，不能这样用。"}, {"text": "这道菜的意识形态很鲜。", "explanation": "这里应该用〈味道〉。鲜是用来形容味道的，意识形态不能用鲜来形容。"}, {"text": "她的意识形态很苗条。", "explanation": "这里应该用〈身材〉。苗条是用来形容身材的，意识形态不能用来形容体型。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家的人有一只共同的意识形态。", "corrected_sentence": "这个国家的人有一种共同的意识形态。", "error_description": "量词错误：“意识形态”是抽象概念，应使用量词“种”，“只”多用于动物。错误形式是“一只共同的意识形态”，正确形式是“一种共同的意识形态”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些意识形态们很不一样。", "corrected_sentence": "这些意识形态很不一样。", "error_description": "“意识形态”是抽象名词，不能加“们”表示复数；此处误加“们”。正确：这些意识形态很不一样。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3a74a9a-679b-4ecf-85be-2858191ca49d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
