INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23844, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "两者程度差不多，可以相比。", "primary_collocate": null, "pronunciation": "kān bǐ", "ipa": "kʰan˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "她做的菜堪比饭店大厨做的。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小路的风景堪比公园。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的速度堪比运动员。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学生的水平堪比老师。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的南方，冷得堪比北方。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的价格堪比一顿大餐。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇的夜晚热闹，堪比大城市。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的记忆力堪比电脑。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子的租金堪比我的月薪。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的力气堪比大人。", "target_word": "堪比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "两者程度差不多，可以相提并论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301ef3b3-42bb-4b0c-bc30-88e444fa6ad5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堪比", "is_correct": true, "explanation": "正确：“堪比”表示相当，菜的水平可以与大厨相比。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」指清扫地方，菜不能打扫，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "配价：「吃」需要能吃东西的主语，「菜」不能吃东西。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“菜做得好”的语境相反。"}], "explanations": {"堪比": "正确：“堪比”表示相当，菜的水平可以与大厨相比。", "打扫": "语义：「打扫」指清扫地方，菜不能打扫，句意不通。", "吃": "配价：「吃」需要能吃东西的主语，「菜」不能吃东西。", "讨厌": "语义：“讨厌”表示厌恶，与“菜做得好”的语境相反。"}, "sentence_index": 0, "correct_answer": "堪比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一公里堪比一千米。", "explanation": "这里应该用〈等于〉。“堪比”表示差不多、可以相比，不用于精确的换算。"}, {"text": "我喜欢各种颜色，堪比红色和蓝色。", "explanation": "这里应该用〈比如〉。“堪比”表示相当，不能用来举例。"}, {"text": "这个学生的成绩堪比五十分。", "explanation": "这里应该用〈超过〉。“堪比”表示相当，不表示数量超出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堪比", "is_correct": true, "explanation": "正确：“堪比”表示相当，与“热闹”的描述相配。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”需要有意愿的主语，“夜晚”不能欢迎大城市。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”是厌恶，与“热闹”的赞赏语境不符。"}, {"text": "认识", "is_correct": false, "explanation": "语义：“认识”指知道对方，句子无法表达两者的比较。"}], "explanations": {"堪比": "正确：“堪比”表示相当，与“热闹”的描述相配。", "欢迎": "配价：“欢迎”需要有意愿的主语，“夜晚”不能欢迎大城市。", "嫌弃": "语义：“嫌弃”是厌恶，与“热闹”的赞赏语境不符。", "认识": "语义：“认识”指知道对方，句子无法表达两者的比较。"}, "sentence_index": 6, "correct_answer": "堪比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书堪比一读。", "explanation": "这里应该用〈值得〉。“堪比”表示相当，不表示“值得”。"}, {"text": "这件事按规定堪比执行。", "explanation": "这里应该用〈比照〉。“堪比”表示相当，不表示“依照”。"}, {"text": "他堪比这份好工作。", "explanation": "这里应该用〈配得上〉。“堪比”表示相当，不能用来说某人配不配得上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家咖啡馆的装修堪比。", "corrected_sentence": "这家咖啡馆的装修堪比五星级酒店。", "error_description": "错误形式：“堪比”后漏掉比较对象，句子不完整。正确形式：“堪比五星级酒店”，“堪比”必须带出被比较的事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作的强度堪比了一场马拉松。", "corrected_sentence": "这份工作的强度堪比一场马拉松。", "error_description": "错误形式：「堪比了」，多了「了」。「堪比」是表示相当的动词，一般不与「了」连用，应删去「了」，改为「堪比一场马拉松」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '136c9343-0608-4efd-9ed6-a63c6b2b4b3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
