INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做科学实验的房间。", "primary_collocate": null, "pronunciation": "shí yàn shì", "ipa": "ʂɻ̩˧˥ jɛn˥˩ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "这间实验室很干净，桌上摆着各种仪器。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，老师带我们去实验室做化学实验。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室的门锁着，我们只好在外面等。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的实验室在三楼，里面有很多仪器。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校新盖了一座楼，里面有六个实验室。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把实验结果记在本子上，然后离开了实验室。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，进实验室的学生都要戴眼镜。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里的显微镜是学校去年买的。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家安静地坐在实验室里，看老师做实验。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里有一台冰箱，专门放药品。", "target_word": "实验室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "物理实验室", "label": "复合"}, {"form": "實驗室", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做科学实验的房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0386e50b-4800-4808-a4ad-7332e842d2a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实验室", "is_correct": true, "explanation": "“实验室”是做科学实验的房间，桌上摆仪器符合句意。"}, {"text": "花店", "is_correct": false, "explanation": "语义：花店的桌上不会摆科学仪器。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆的桌上不摆实验用的仪器。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店卖的是书，桌上不会摆科学仪器。"}], "explanations": {"实验室": "“实验室”是做科学实验的房间，桌上摆仪器符合句意。", "花店": "语义：花店的桌上不会摆科学仪器。", "饭馆": "语义：饭馆的桌上不摆实验用的仪器。", "书店": "语义：书店卖的是书，桌上不会摆科学仪器。"}, "sentence_index": 0, "correct_answer": "实验室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去实验室买了一束花送给妈妈。", "explanation": "这里应该用〈花店〉。买花要去花店；实验室是做科学实验的房间，不卖东西。"}, {"text": "农民们每天在实验室里收割庄稼。", "explanation": "这里应该用〈农田〉。收割庄稼要在农田里进行；实验室是做科学实验的房间，不是收割农作物的地方。"}, {"text": "他牙疼，就去实验室看牙。", "explanation": "这里应该用〈诊所〉。看牙要去诊所，实验室是做科学实验的房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实验室", "is_correct": true, "explanation": "“实验室”是需要戴眼镜防护的场所，符合“为了安全”的语境。"}, {"text": "课程", "is_correct": false, "explanation": "语义：课程不是可以“进”的场所。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不是可以“进”的场所。"}, {"text": "教材", "is_correct": false, "explanation": "搭配：“进”后要接场所，教材不是场所，不能说“进教材”。"}], "explanations": {"实验室": "“实验室”是需要戴眼镜防护的场所，符合“为了安全”的语境。", "课程": "语义：课程不是可以“进”的场所。", "故事": "语义：故事不是可以“进”的场所。", "教材": "搭配：“进”后要接场所，教材不是场所，不能说“进教材”。"}, "sentence_index": 6, "correct_answer": "实验室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了，就去实验室买了一碗面条。", "explanation": "这里应该用〈饭馆〉。买饭吃要去饭馆；实验室是做科学实验的房间。"}, {"text": "病人躺在实验室里，护士给他打针。", "explanation": "这里应该用〈病房〉。病人住在病房里接受治疗；实验室是做科学实验的房间。"}, {"text": "我们在实验室里借了三本小说。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆；实验室是做科学实验的房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "实验员实验室里清洗玻璃器皿。", "corrected_sentence": "实验员在实验室里清洗玻璃器皿。", "error_description": "介词错误：处所要用“在”引出，应说“在实验室里”。漏掉“在”，直接说“实验室里”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "物理老师终于有了一条新实验室。", "corrected_sentence": "物理老师终于有了一间新实验室。", "error_description": "量词错误：“实验室”是房间，应说“一间实验室”。“条”用于细长的东西，不能用于房间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
