INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23858, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把线或绳子交叉绕在一起做成东西。", "primary_collocate": null, "pronunciation": "biān zhī chéng", "ipa": "pjɛn˥ ʈʂɻ̩˥ ʈʂʰɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "她正在把红线编织成一个小包。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用绳子编织成一张网。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们学着把草编织成小篮子。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这些毛线编织成一件毛衣。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们把彩线编织成漂亮的手链。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用白线编织成一块桌布。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把细竹条编织成一个圆圆的盒子。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把细草绳编织成一根粗绳，用来拴船。", "target_word": "编织成", "complexity_tier": "T3", "furigana": "yé ye bǎ xì cǎo shéng biān zhī chéng yì gēn cū shéng, yòng lái shuān chuán.", "sentence_source": "generated"}, {"text": "这位老人能把麦秆编织成各种小动物。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用蓝色的线编织成了一顶小帽子。", "target_word": "编织成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "编织", "label": "原形"}, {"form": "编织成了", "label": "体标"}, {"form": "編織成", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把线或绳子交叉绕在一起做成东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0386e50b-4800-4808-a4ad-7332e842d2a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "编织成", "is_correct": true, "explanation": "正确：“编织成”表示用线交叉制作成东西，与“一个小包”搭配，符合句意。"}, {"text": "剪成", "is_correct": false, "explanation": "语义：“剪”是剪断，不能把红线做成一个小包。"}, {"text": "熔成", "is_correct": false, "explanation": "搭配：“熔成”用于金属等材料受热变液体后成型，不用于红线。"}, {"text": "砌成", "is_correct": false, "explanation": "搭配：“砌成”用于砖石、墙体等，不能用红线砌成小包。"}], "explanations": {"编织成": "正确：“编织成”表示用线交叉制作成东西，与“一个小包”搭配，符合句意。", "剪成": "语义：“剪”是剪断，不能把红线做成一个小包。", "熔成": "搭配：“熔成”用于金属等材料受热变液体后成型，不用于红线。", "砌成": "搭配：“砌成”用于砖石、墙体等，不能用红线砌成小包。"}, "sentence_index": 0, "correct_answer": "编织成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "沙子编织成了一座小山。", "explanation": "这里应该用〈堆成〉。沙子是松散颗粒，要堆积成山，不能编织。"}, {"text": "他把西瓜编织成了几块。", "explanation": "这里应该用〈切成〉。西瓜要切开才能分成几块，编织只适用于线、绳等材料。"}, {"text": "几块木板编织成了一个棚子。", "explanation": "这里应该用〈搭成〉。木板是硬材料，要搭建组装而成，不能用编织的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "编织成", "is_correct": true, "explanation": "正确：用细竹条交叉编织，可以做成圆盒子，符合句意。"}, {"text": "劈成", "is_correct": false, "explanation": "语义：“劈”是把竹条劈开，不能使竹条形成一个盒子。"}, {"text": "烧成", "is_correct": false, "explanation": "搭配：“烧成”用于陶瓷、泥土等，不说竹条烧成盒子。"}, {"text": "熔成", "is_correct": false, "explanation": "搭配：“熔成”用于金属等受热熔化的材料，不能用于竹条。"}], "explanations": {"编织成": "正确：用细竹条交叉编织，可以做成圆盒子，符合句意。", "劈成": "语义：“劈”是把竹条劈开，不能使竹条形成一个盒子。", "烧成": "搭配：“烧成”用于陶瓷、泥土等，不说竹条烧成盒子。", "熔成": "搭配：“熔成”用于金属等受热熔化的材料，不能用于竹条。"}, "sentence_index": 6, "correct_answer": "编织成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂把铁水编织成了一个零件。", "explanation": "这里应该用〈铸成〉。铁水是熔化的金属，要浇入模具铸造成型，编织只适用于线、绳等材料。"}, {"text": "工人把树编织成了木材。", "explanation": "这里应该用〈砍成〉。树要砍伐、锯开才能成为木材，编织只适用于线、绳等材料。"}, {"text": "农民把甘蔗编织成了汁。", "explanation": "这里应该用〈压成〉。甘蔗要压榨出汁，不能用编织的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸用粗绳子编织到一个网兜。", "corrected_sentence": "爸爸用粗绳子编织成一个网兜。", "error_description": "错误：“编织到”。正确：“编织成”。结果补语应为“成”，表示编织出来的结果，“到”不能表示成品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐用粉色的线编织着成了一条小围巾。", "corrected_sentence": "姐姐用粉色的线编织成了一条小围巾。", "error_description": "错误：“编织着成了”。正确：“编织成了”。“着”表示动作进行，与表示完成的结果补语“成了”不能同时用在“编织”和“成”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
