INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23860, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国籍就是你是哪个国家的人。", "primary_collocate": null, "pronunciation": "guó jí", "ipa": "kuɔ˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "你的国籍是哪国？", "target_word": "国籍", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他有中国国籍，也会说英语。", "target_word": "国籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在表格里写上你的国籍。", "target_word": "国籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的朋友国籍不同，但是我们都爱踢球。", "target_word": "国籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出生在法国，可是她的国籍是日本。", "target_word": "国籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "办护照的时候，要先确认国籍。", "target_word": "国籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想改变国籍，所以去了移民局。", "target_word": "国籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些人有双重国籍。", "target_word": "国籍", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司的员工国籍各不相同。", "target_word": "国籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们每个人的国籍和母语。", "target_word": "国籍", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "双重国籍", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人属于哪个国家的身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305dd323-afa7-44a8-b982-43b80d121d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23860, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国籍", "is_correct": true, "explanation": "正确答案。国籍指一个人属于哪个国家的身份。"}, {"text": "国际", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是国际。"}, {"text": "国旗", "is_correct": false, "explanation": "qí 与 jí 声母不同（q 与 j），意思是国旗。"}, {"text": "过季", "is_correct": false, "explanation": "guò 与 guó、jì 与 jí 声调都不同，意思是过季。"}], "explanations": {"国籍": "正确答案。国籍指一个人属于哪个国家的身份。", "国际": "jì（第四声）与 jí（第二声）声调不同，意思是国际。", "国旗": "qí 与 jí 声母不同（q 与 j），意思是国旗。", "过季": "guò 与 guó、jì 与 jí 声调都不同，意思是过季。"}, "sentence_index": null, "correct_answer": "国籍"}, "level_3": {"options": [{"text": "国籍", "is_correct": true, "explanation": "正确答案。问“你的……是哪国”时，所填的是国籍。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是国家，不能用“是哪国”来问。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是数字，不能用“是哪国”来问。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体特征，不能指国家归属。"}], "explanations": {"国籍": "正确答案。问“你的……是哪国”时，所填的是国籍。", "名字": "语义：“名字”不是国家，不能用“是哪国”来问。", "年龄": "语义：“年龄”是数字，不能用“是哪国”来问。", "身高": "体貌：“身高”是身体特征，不能指国家归属。"}, "sentence_index": 0, "correct_answer": "国籍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国籍有很多湖泊。", "explanation": "这里应该用〈国家〉。国籍是身份归属，不是地方，不能说“这个国籍有湖泊”。"}, {"text": "他的国籍是浙江。", "explanation": "这里应该用〈籍贯〉。籍贯是出生或祖籍的地方，浙江是省份，不能用作国籍。"}, {"text": "我把国籍迁到了北京。", "explanation": "这里应该用〈户口〉。户口可以迁移，国籍是国家归属，不能迁到某个城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国籍", "is_correct": true, "explanation": "正确答案。“想改变国籍”才会去移民局，与“去了移民局”相符。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：“饮食”指吃喝，改变饮食不需要去移民局。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体数据，与移民局无关。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：“容貌”指外形，改变容貌不是去移民局的理由。"}], "explanations": {"国籍": "正确答案。“想改变国籍”才会去移民局，与“去了移民局”相符。", "饮食": "语义：“饮食”指吃喝，改变饮食不需要去移民局。", "体重": "语义：“体重”是身体数据，与移民局无关。", "容貌": "体貌：“容貌”指外形，改变容貌不是去移民局的理由。"}, "sentence_index": 6, "correct_answer": "国籍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出国要带国籍。", "explanation": "这里应该用〈护照〉。国籍是身份归属，不是可以携带的证件，“带国籍”不成立。"}, {"text": "中国的国籍超过十四亿。", "explanation": "这里应该用〈国民〉。国籍是国家归属，不能用来计数人口，数人口应说“国民超过十四亿”。"}, {"text": "他是这个城市的国籍。", "explanation": "这里应该用〈居民〉。居民指住在某地的人，国籍指国家归属，不能用来说某个城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想申请了英国国籍。", "corrected_sentence": "我想申请英国国籍。", "error_description": "体标错误：「想」表示打算，事情还没有发生，不能在「申请」后加「了」，应说「我想申请英国国籍」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他十年前就放弃了中国籍国。", "corrected_sentence": "他十年前就放弃了中国国籍。", "error_description": "字序错误：“国籍”是固定词，应说“国籍”，不能颠倒成“籍国”，所以应说“中国国籍”，不能说“中国籍国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "“一致”指彼此相同、没有差异，与“两条路的走向相反”构成反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足，与“对立”无反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”形容温度低，与“对立”无反义关系。"}, {"text": "灵活", "is_correct": false, "explanation": "“灵活”形容动作敏捷或处理方式不死板，与“对立”无反义关系。"}], "correct_answer": "一致", "explanations": {"一致": "“一致”指彼此相同、没有差异，与“两条路的走向相反”构成反义关系。", "明亮": "“明亮”形容光线充足，与“对立”无反义关系。", "寒冷": "“寒冷”形容温度低，与“对立”无反义关系。", "灵活": "“灵活”形容动作敏捷或处理方式不死板，与“对立”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "“一致”指看法相同，与“观点完全对立”构成反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面喧闹，与“对立”无反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容没有污物，与“对立”无反义关系。"}, {"text": "遥远", "is_correct": false, "explanation": "“遥远”形容距离很远，与“对立”无反义关系。"}], "correct_answer": "一致", "explanations": {"一致": "“一致”指看法相同，与“观点完全对立”构成反义关系。", "热闹": "“热闹”形容场面喧闹，与“对立”无反义关系。", "干净": "“干净”形容没有污物，与“对立”无反义关系。", "遥远": "“遥远”形容距离很远，与“对立”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "两个东西互相不一样，一个和另一个相反。", "primary_collocate": null, "pronunciation": "duì lì", "ipa": "twei˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这幅画用黑和白形成了鲜明的对立。", "target_word": "对立", "complexity_tier": "T3", "furigana": "zhè fú huà yòng hēi hé bái xíng chéng le xiān míng de duì lì.", "sentence_source": "generated"}, {"text": "这两个词的意思正好对立。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱甜，我爱辣，我们的口味形成对立。", "target_word": "对立", "complexity_tier": "T3", "furigana": "tā ài tián, wǒ ài là, wǒ men de kǒu wèi xíng chéng duì lì.", "sentence_source": "generated"}, {"text": "这两条路的走向形成对立，一条向北，一条向南。", "target_word": "对立", "complexity_tier": "T3", "furigana": "zhè liǎng tiáo lù de zǒu xiàng xíng chéng duì lì, yì tiáo xiàng běi, yì tiáo xiàng nán.", "sentence_source": "generated"}, {"text": "姐姐和妹妹的性格对立，一个爱说，一个爱静。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台的左边和右边形成对立。", "target_word": "对立", "complexity_tier": "T3", "furigana": "wǔ tái de zuǒ biān hé yòu biān xíng chéng duì lì.", "sentence_source": "generated"}, {"text": "“大”和“小”的意思是对立的。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队的打法截然对立，一队攻，一队守。", "target_word": "对立", "complexity_tier": "T3", "furigana": "liǎng duì de dǎ fǎ jié rán duì lì, yī duì gōng, yī duì shǒu.", "sentence_source": "generated"}, {"text": "热情和冷淡是对立的态度。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的观点完全对立，一个赞成，一个反对。", "target_word": "对立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对立着", "label": "体标"}, {"form": "对立了", "label": "体标"}, {"form": "对立面", "label": "复合"}, {"form": "對立", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个东西互相不一样，彼此相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0386e50b-4800-4808-a4ad-7332e842d2a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对立", "is_correct": true, "explanation": "“黑和白”形成的是相反的对照，“鲜明的对立”符合句意。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字不能与黑白形成鲜明的对照。"}, {"text": "答案", "is_correct": false, "explanation": "语义：答案不是可以与颜色形成对照的事物。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“鲜明”修饰可以看见的对比，不修饰时间。"}], "explanations": {"对立": "“黑和白”形成的是相反的对照，“鲜明的对立”符合句意。", "数字": "语义：数字不能与黑白形成鲜明的对照。", "答案": "语义：答案不是可以与颜色形成对照的事物。", "时间": "搭配：“鲜明”修饰可以看见的对比，不修饰时间。"}, "sentence_index": 0, "correct_answer": "对立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两条河的走向对立，几乎重叠在一起。", "explanation": "这里应该用〈重叠〉。“对立”指两者不一样、相反，走向几乎重叠时不能说“对立”。"}, {"text": "两个人的步子对立，走起路来总是合拍。", "explanation": "这里应该用〈合拍〉。“对立”指两者不一样、相反，步子合拍时不能说“对立”。"}, {"text": "他们在婚姻问题上始终对立，看法完全一样。", "explanation": "这里应该用〈一样〉。“对立”指两者不一样、相反，看法一样时不能说“对立”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对立", "is_correct": true, "explanation": "“大”和“小”意思正好相反，“对立的”符合句意。"}, {"text": "相同", "is_correct": false, "explanation": "语义：“大”和“小”的意思相反，不能说“相同的”。"}, {"text": "相近", "is_correct": false, "explanation": "语义：“大”和“小”的意思正好相反，不能说“相近的”。"}, {"text": "对等", "is_correct": false, "explanation": "语义：“对等”指双方相当、相等，“大”和“小”的意思正好相反，不能说“对等的”。"}], "explanations": {"对立": "“大”和“小”意思正好相反，“对立的”符合句意。", "相同": "语义：“大”和“小”的意思相反，不能说“相同的”。", "相近": "语义：“大”和“小”的意思正好相反，不能说“相近的”。", "对等": "语义：“对等”指双方相当、相等，“大”和“小”的意思正好相反，不能说“对等的”。"}, "sentence_index": 6, "correct_answer": "对立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两块布的颜色完全对立，看不出区别。", "explanation": "这里应该用〈相同〉。“对立”指两者不一样、相反，颜色相同时不能用“对立”。"}, {"text": "两兄弟长得很对立，连妈妈都分不清。", "explanation": "这里应该用〈相像〉。长相相似不能用“对立”来形容。"}, {"text": "这两份文件的内容完全对立，一份是照抄的另一份。", "explanation": "这里应该用〈一致〉。“对立”指不一样、相反，内容照抄时不能说“对立”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两条路的方向正好对立面。", "corrected_sentence": "这两条路的方向正好对立。", "error_description": "词形错误：此处应用动词“对立”，不能用名词“对立面”（对立的一方）。多了“面”，句子变成指一方，不再表示两者相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两种颜色鲜明的对立。", "corrected_sentence": "这两种颜色形成鲜明的对立。", "error_description": "省略错误：“形成”不能省略，应说“形成鲜明的对立”，省略后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
