INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23868, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人一起加入的团体。", "primary_collocate": null, "pronunciation": "gōng huì", "ipa": "kʊŋ˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我在游戏里加入了一个公会。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公会有两百多个玩家。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公会会长每天晚上带大家打怪。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他因为不活跃，离开了公会。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公会里的朋友都很热情。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公会的成员一起做任务，很开心。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想不想和我一起建一个公会？", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公会群里每天都有人聊天。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公会准备下周举行比赛。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新朋友可以先申请进公会看看。", "target_word": "公会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "公會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公会：很多人一起加入的团体（如游戏里的团体）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0386e50b-4800-4808-a4ad-7332e842d2a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公会", "is_correct": true, "explanation": "正确：“加入了一个公会”指加入游戏中的团体，符合语境。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是工具书，不是团体，不能被“加入”。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“加入”不能和考试搭配，应说“参加考试”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是团体，不能被“加入”。"}], "explanations": {"公会": "正确：“加入了一个公会”指加入游戏中的团体，符合语境。", "字典": "语义：字典是工具书，不是团体，不能被“加入”。", "考试": "搭配：“加入”不能和考试搭配，应说“参加考试”。", "雨伞": "语义：雨伞不是团体，不能被“加入”。"}, "sentence_index": 0, "correct_answer": "公会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的公会今年八岁，去上小学了。", "explanation": "这里应该用〈孩子〉。说年龄、上学要用指人的词；公会是团体，没有年龄，也不去上学。"}, {"text": "我每天晚上在公会里洗澡。", "explanation": "这里应该用〈浴室〉。洗澡要在浴室里；公会是团体，不是洗澡的地方。"}, {"text": "我因为感冒去公会打针。", "explanation": "这里应该用〈诊所〉。打针要去诊所；公会是团体，不是看病的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公会", "is_correct": true, "explanation": "正确：“建一个公会”指组建游戏中的团体，与“一起”的语境相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能被“建”，“建一个歌曲”不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被建造，与“建”无法搭配。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：“建”搭配的是组织、建筑等，不能搭配地毯。"}], "explanations": {"公会": "正确：“建一个公会”指组建游戏中的团体，与“一起”的语境相符。", "歌曲": "语义：歌曲不能被“建”，“建一个歌曲”不成立。", "天气": "语义：天气不能被建造，与“建”无法搭配。", "地毯": "搭配：“建”搭配的是组织、建筑等，不能搭配地毯。"}, "sentence_index": 6, "correct_answer": "公会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去公会买了一瓶牛奶。", "explanation": "这里应该用〈超市〉。买东西要去超市；公会是团体，不卖牛奶。"}, {"text": "他因为生病住进了公会。", "explanation": "这里应该用〈医院〉。住院要去医院；公会是团体，不是治病的地方。"}, {"text": "我们每天早上七点去公会上课。", "explanation": "这里应该用〈学校〉。上课要去学校；公会是团体，不是教学场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "玩家们在游戏里组建了一只新公会。", "corrected_sentence": "玩家们在游戏里组建了一个新公会。", "error_description": "错误：量词“只”不能用于“公会”，“公会”的量词应为“个”。正确形式：“一个新公会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个公会们每天都有人聊天。", "corrected_sentence": "这个公会每天都有人聊天。", "error_description": "错误：“公会”是事物，不能加“们”表示复数。正确形式：“这个公会每天都有人聊天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
