INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或两个国家互相不喜欢，想要打架。", "primary_collocate": null, "pronunciation": "dí duì", "ipa": "ti˧˥ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这两个国家已经敌对很多年了。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们两个人敌对了很久，见面就吵架。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们是朋友，不要互相敌对。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个村子为了水互相敌对，常常打架。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两家人从前敌对过，现在已经和好了。", "target_word": "敌对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和弟弟总是互相敌对，一见面就想打架。", "target_word": "敌对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国敌对的时候，没有人去对方那里旅游。", "target_word": "敌对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不想让班上的同学互相敌对。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为那件事，他们两家敌对了二十年。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个国家不再敌对，边境又开放了。", "target_word": "敌对", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "敵對", "label": "繁体"}, {"form": "敌对状态", "label": "复合"}], "register": "中性", "sense_fingerprint": "敌对：两个人或两国互相不喜欢、想要打架（作谓语的动作）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0386e50b-4800-4808-a4ad-7332e842d2a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敌对", "is_correct": true, "explanation": "正确：“敌对”是动词，表示两个国家互相对立，与“很多年”搭配，符合句意。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”只用于人，不能说国家结婚。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”用于书刊等出版物，不能用于国家。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是体育活动，与两国的关系毫无关联，句子不通。"}], "explanations": {"敌对": "正确：“敌对”是动词，表示两个国家互相对立，与“很多年”搭配，符合句意。", "结婚": "搭配：“结婚”只用于人，不能说国家结婚。", "出版": "搭配：“出版”用于书刊等出版物，不能用于国家。", "游泳": "语义：“游泳”是体育活动，与两国的关系毫无关联，句子不通。"}, "sentence_index": 0, "correct_answer": "敌对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个国家共同开发油田，敌对得很顺利。", "explanation": "这里应该用〈合作〉。合作是共同努力做事，敌对是互相不喜欢、想打架，与“共同开发、顺利”的意思相反。"}, {"text": "他敌对地招待了远方来的朋友。", "explanation": "这里应该用〈热情〉。热情是友好的待人态度，敌对是互相仇视、想打架，用来修饰招待会自相矛盾。"}, {"text": "两个孩子玩得很开心，互相敌对了一下午。", "explanation": "这里应该用〈玩耍〉。玩得开心与“敌对”（互相不喜欢、想打架）的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敌对", "is_correct": true, "explanation": "正确：“敌对”表示两国互相对立，与“没有人去对方那里旅游”的语境相符。"}, {"text": "往来", "is_correct": false, "explanation": "语义：“往来”指彼此频繁交往，与“没有人去对方那里旅游”的状况相矛盾。"}, {"text": "交好", "is_correct": false, "explanation": "语义：“交好”指双方友好相处，与两国互相隔绝的状况不符。"}, {"text": "建交", "is_correct": false, "explanation": "语义：“建交”指两国建立正式友好关系，与“没有人去对方那里旅游”的状况相矛盾。"}], "explanations": {"敌对": "正确：“敌对”表示两国互相对立，与“没有人去对方那里旅游”的语境相符。", "往来": "语义：“往来”指彼此频繁交往，与“没有人去对方那里旅游”的状况相矛盾。", "交好": "语义：“交好”指双方友好相处，与两国互相隔绝的状况不符。", "建交": "语义：“建交”指两国建立正式友好关系，与“没有人去对方那里旅游”的状况相矛盾。"}, "sentence_index": 6, "correct_answer": "敌对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个孩子敌对得很融洽。", "explanation": "这里应该用〈相处〉。相处是融洽地在一起，敌对是互相不喜欢、想打架，与“融洽”的意思相反。"}, {"text": "两家人互相敌对，关系一直很好。", "explanation": "这里应该用〈帮助〉。帮助是互相支持，敌对是互相不喜欢、想打架，前后语义矛盾。"}, {"text": "两家店互相敌对，还常常互相介绍客人。", "explanation": "这里应该用〈合作〉。互相介绍客人是合作往来，与“敌对”（互相不喜欢、想打架）相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个部落为了草场对方敌对了很多年。", "corrected_sentence": "两个部落为了草场与对方敌对了很多年。", "error_description": "错误：“对方敌对”缺少介词“与”。正确：“与对方敌对”。“敌对”的对象要用介词“与”引出，放在“敌对”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个部落不再敌对敌对，草场又变绿了。", "corrected_sentence": "两个部落不再敌对，草场又变绿了。", "error_description": "错误：“敌对”表示对立状态，不宜重叠成“敌对敌对”。“不再”后直接接“敌对”即可。正确形式：“不再敌对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22a6ca7c-abe6-426c-9c03-4ad9147ff31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
