INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23874, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "和你比赛的人。", "primary_collocate": null, "pronunciation": "jìng zhēng duì shǒu", "ipa": "tɕiŋ˥˩ tʂɤŋ˥ tuei˥˩ ʂou˨˩˦", "syllable_count": 4, "sentences": [{"text": "今天的竞争对手很强。", "target_word": "竞争对手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛前，我看了竞争对手的视频。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次跑步比赛，我的竞争对手是同班同学。", "target_word": "竞争对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在决赛中遇到了最强的竞争对手。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下棋时，竞争对手想了很久才走。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和竞争对手握了手，然后开始比赛。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明把竞争对手当成学习的目标。", "target_word": "竞争对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的竞争对手比她高，也比她快。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天的竞争对手是邻校的队。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网球比赛里，我没有害怕竞争对手。", "target_word": "竞争对手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个竞争对手", "label": "量词：个"}, {"form": "一位竞争对手", "label": "量词：位"}, {"form": "两个竞争对手", "label": "量词：个"}], "register": "中性", "sense_fingerprint": "和自己比赛的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e678d-e779-4e69-98d1-8a3c0c702b1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞争对手", "is_correct": true, "explanation": "正确：句中指今天要和你比赛的人，与“很强”相符。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众不参加比赛，句中“很强”指参赛者的实力，观众不符合。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“很强”形容人的能力，不能用来形容作业。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气没有强弱之分，也不是比赛的对手。"}], "explanations": {"竞争对手": "正确：句中指今天要和你比赛的人，与“很强”相符。", "观众": "语义：观众不参加比赛，句中“很强”指参赛者的实力，观众不符合。", "作业": "搭配：“很强”形容人的能力，不能用来形容作业。", "空气": "语义：空气没有强弱之分，也不是比赛的对手。"}, "sentence_index": 0, "correct_answer": "竞争对手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位竞争对手每天给我们安排训练。", "explanation": "这里应该用〈教练〉。竞争对手是和你比赛的人，不负责给你安排训练；安排训练的是〈教练〉。"}, {"text": "这位竞争对手判定了比赛结果，大家都很满意。", "explanation": "这里应该用〈裁判〉。竞争对手是和你比赛的人，不能判定比赛结果；判定结果的是〈裁判〉。"}, {"text": "这位竞争对手每天给我们留很多作业。", "explanation": "这里应该用〈老师〉。竞争对手是和你比赛的人，不会给你留作业；留作业的是〈老师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b5100e-03f4-48f2-b382-cac91cf39870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞争对手", "is_correct": true, "explanation": "正确：句中要被当成学习目标的是和你比赛的人，与句意相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被当成学习的目标，句中的对象应是人。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：公交车是交通工具，不能被当成学习的目标。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“当成……的目标”要求能作学习对象的人或事，“雨”不搭配。"}], "explanations": {"竞争对手": "正确：句中要被当成学习目标的是和你比赛的人，与句意相符。", "天空": "语义：天空不能被当成学习的目标，句中的对象应是人。", "公交车": "语义：公交车是交通工具，不能被当成学习的目标。", "雨": "搭配：“当成……的目标”要求能作学习对象的人或事，“雨”不搭配。"}, "sentence_index": 6, "correct_answer": "竞争对手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "网球比赛里，我没有害怕那条竞争对手。", "explanation": "量词：〈条〉用于长条形的东西。竞争对手指和你比赛的人，这里应该用〈个〉。"}, {"text": "网球比赛里，我没有害怕这棵竞争对手。", "explanation": "量词：〈棵〉用于树木等植物。竞争对手指和你比赛的人，这里应该用〈个〉。"}, {"text": "网球比赛里，我没有害怕那块竞争对手。", "explanation": "量词：〈块〉用于块状的东西。竞争对手指和你比赛的人，这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b5100e-03f4-48f2-b382-cac91cf39870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛我遇到三个竞争对手们。", "corrected_sentence": "这次比赛我遇到三个竞争对手。", "error_description": "错误：“竞争对手”前有数量词“三个”，后面不能再加“们”。应说“三个竞争对手”，不说“三个竞争对手们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b5100e-03f4-48f2-b382-cac91cf39870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们队有两本竞争对手。", "corrected_sentence": "他们队有两个竞争对手。", "error_description": "量词错误：“竞争对手”指人，量词应用“个”，不用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b5100e-03f4-48f2-b382-cac91cf39870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
