INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23880, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b5100e-03f4-48f2-b382-cac91cf39870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23880, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "排行榜是一个名单，上面写着谁最好、谁第二好。", "primary_collocate": null, "pronunciation": "pái háng bǎng", "ipa": "pʰai˧˥ xɑŋ˧˥ pɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "排行榜上，小明是第一名。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把排行榜贴在墙上。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在排行榜上找到了自己的名字。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个排行榜每天都会变。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看一下排行榜，谁是第二名？", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想让自己的名字上排行榜。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟天天看游戏排行榜。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排行榜里有十个人，我排第五。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张排行榜是学校做的。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排行榜第一名能得到一个小礼物。", "target_word": "排行榜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "写着谁第一、谁第二的名单", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e678d-e779-4e69-98d1-8a3c0c702b1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排行榜", "is_correct": true, "explanation": "正确：句中指写着谁第一、谁第二的名单，与“小明是第一名”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱上不能写名次，与句意不符。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服上不写名次，不能说小明在衣服上是第一名。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“上”后接的载体要能列出名次，“闹钟”不搭配。"}], "explanations": {"排行榜": "正确：句中指写着谁第一、谁第二的名单，与“小明是第一名”相符。", "冰箱": "语义：冰箱上不能写名次，与句意不符。", "衣服": "语义：衣服上不写名次，不能说小明在衣服上是第一名。", "闹钟": "搭配：“上”后接的载体要能列出名次，“闹钟”不搭配。"}, "sentence_index": 0, "correct_answer": "排行榜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试，他的排行榜是第五。", "explanation": "这里应该用〈名次〉。排行榜是写着谁排第几的名单；说某人排第几要用〈名次〉，不能说“排行榜是第五”。"}, {"text": "比赛排行榜上写着每天的比赛时间。", "explanation": "这里应该用〈日程表〉。排行榜按成绩排出名次，不写每天的比赛时间；列出时间安排的是〈日程表〉。"}, {"text": "这个排行榜上记着每个人的电话。", "explanation": "这里应该用〈通讯录〉。排行榜按成绩排出名次，不记录电话号码；记录联系方式的是〈通讯录〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b5100e-03f4-48f2-b382-cac91cf39870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排行榜", "is_correct": true, "explanation": "正确：弟弟看的是列出游戏名次的名单，与“游戏”相符。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是游戏名单，弟弟不会看饼干。"}, {"text": "袜子", "is_correct": false, "explanation": "语义：袜子不能被用来看游戏，也不是名单。"}, {"text": "水杯", "is_correct": false, "explanation": "搭配：“看”后接的应是可观看的对象，“水杯”不能与“看游戏”搭配。"}], "explanations": {"排行榜": "正确：弟弟看的是列出游戏名次的名单，与“游戏”相符。", "饼干": "语义：饼干不是游戏名单，弟弟不会看饼干。", "袜子": "语义：袜子不能被用来看游戏，也不是名单。", "水杯": "搭配：“看”后接的应是可观看的对象，“水杯”不能与“看游戏”搭配。"}, "sentence_index": 6, "correct_answer": "排行榜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座排行榜第一名能得到一个小礼物。", "explanation": "量词：〈座〉用于山、楼房等大型固定物，排行榜是名单，这里应该用〈个〉。"}, {"text": "他胸前戴着排行榜，上面写着他的名字。", "explanation": "这里应该用〈名牌〉。排行榜是写着谁最好、谁第二好的名单，不能戴在胸前；戴在胸前写名字的是〈名牌〉。"}, {"text": "那只排行榜第一名能得到一个小礼物。", "explanation": "量词：〈只〉多用于动物或成对的东西，排行榜是名单，这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b5100e-03f4-48f2-b382-cac91cf39870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在排行榜上看了到自己的名字。", "corrected_sentence": "我在排行榜上看到了自己的名字。", "error_description": "错误：“看到”是动补结构，“了”应放在“看到”之后，不能插在“看”和“到”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b5100e-03f4-48f2-b382-cac91cf39870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟天天看一条游戏排行榜。", "corrected_sentence": "弟弟天天看一个游戏排行榜。", "error_description": "量词错误：“排行榜”是名单，量词应用“个”，不用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b5100e-03f4-48f2-b382-cac91cf39870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
