INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23882, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里想要做到的事或到达的地方。", "primary_collocate": null, "pronunciation": "mù biāo", "ipa": "mu˥˩ piɑʊ˥", "syllable_count": 2, "sentences": [{"text": "我的目标是学好中文。", "target_word": "目标", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天都为自己的目标努力。", "target_word": "目标", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你今年有什么目标？", "target_word": "目标", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的目标是三个月看懂中文书。", "target_word": "目标", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的目标很清楚，就是考上大学。", "target_word": "目标", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明定了一个目标：每天跑步半小时。", "target_word": "目标", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个目标太高了，我现在做不到。", "target_word": "目标", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了实现目标，他放弃了很多休息时间。", "target_word": "目标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了目标，学习就有了力量。", "target_word": "目标", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师要我们先写下这个月的目标。", "target_word": "目标", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个目标", "label": "量词"}, {"form": "奋斗目标", "label": "复合"}], "register": "中性", "sense_fingerprint": "想要实现或到达的结果、方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 小明 (Zipf 3.37), 跑步 (Zipf 3.84), 半小时 (Zipf 3.95)']::text[], '22aa5821-43c2-4f1a-bd68-eccc7ce09b8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目标", "is_correct": true, "explanation": "正确：“目标”是心里想要做到的事，与“学好中文”相符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不是人要做到的事，不能作为“学好中文”的目的。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，不能作为要做到的事。"}, {"text": "老师", "is_correct": false, "explanation": "配价：“是”后面要接一件要做成的事，“老师”是人，不能充当“学好中文”的内容。"}], "explanations": {"目标": "正确：“目标”是心里想要做到的事，与“学好中文”相符。", "房间": "语义：房间不是人要做到的事，不能作为“学好中文”的目的。", "手机": "语义：手机是物品，不能作为要做到的事。", "老师": "配价：“是”后面要接一件要做成的事，“老师”是人，不能充当“学好中文”的内容。"}, "sentence_index": 0, "correct_answer": "目标"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天骑着一辆目标去上班。", "explanation": "这里应该用〈自行车〉。“骑”的对象是自行车等车辆，“目标”是想要做到的事或到达的地方，不能当交通工具。"}, {"text": "我们学校的目标里有很多树。", "explanation": "这里应该用〈校园〉。校园是学校里的地方，可以有树；“目标”是想要做到的事，里面不会有树。"}, {"text": "我口渴了，想喝一杯目标。", "explanation": "这里应该用〈水〉。水可以喝；“目标”是想要做到的事，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目标", "is_correct": true, "explanation": "正确：“目标”是想要达到的结果，“太高了”和“做不到”与之相符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“做不到”不能直接用于价格，说价格高应说“负担不起”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能被说成“太高了”而“做不到”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能用“太高了”来形容，句子意思不通。"}], "explanations": {"目标": "正确：“目标”是想要达到的结果，“太高了”和“做不到”与之相符。", "价格": "搭配：“做不到”不能直接用于价格，说价格高应说“负担不起”。", "书包": "语义：书包是物品，不能被说成“太高了”而“做不到”。", "天气": "语义：天气不能用“太高了”来形容，句子意思不通。"}, "sentence_index": 6, "correct_answer": "目标"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这瓶牛奶上贴着一个目标，写着保质期。", "explanation": "这里应该用〈标签〉。标签是贴在物品上标明内容的纸片，“目标”是想要做到的事，不能贴在瓶子上。"}, {"text": "这首歌的目标很好听，大家都喜欢。", "explanation": "这里应该用〈标题〉。标题是作品的名字，可以说“好听”；“目标”是想要达到的结果，不能用“好听”来形容。"}, {"text": "句子的最后要加一个目标。", "explanation": "这里应该用〈标点〉。句末要加的是标点符号，“目标”是想要做到的事，不能加在句子后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从没实现了这个目标。", "corrected_sentence": "他从没实现过这个目标。", "error_description": "“从没”表示从未有过的经历，应与“过”搭配。正确是“实现过”，错误是“实现了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她已经定了下新的目标。", "corrected_sentence": "她已经定下了新的目标。", "error_description": "“下”是结果补语，应紧跟动词“定”。正确是“定下了”，错误是“定了下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
