INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23888, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "互信就是两个人或两边的人相信对方。", "primary_collocate": null, "pronunciation": "hù xìn", "ipa": "xu˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我们两个人互信，从来不怀疑对方。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国要互信，才能谈好合作。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们俩互信多年，从不吵架。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双方互信，所以合同写得很简单。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们互信互助，班级很团结。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有互信的队友才能一起走到最后。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夫妻应该互信，不要偷看对方的手机。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合作的时候，大家要互信。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们彼此互信，所以不用写保证书。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板和员工互信，工作气氛就好。", "target_word": "互信", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "双方彼此相信对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305dd323-afa7-44a8-b982-43b80d121d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "互信", "is_correct": true, "explanation": "正确：「互信」是动词，表示彼此相信对方，「我们两个人互信，从来不怀疑对方」符合句意。"}, {"text": "猜忌", "is_correct": false, "explanation": "语义：「猜忌」指怀疑、猜疑，与后句「从来不怀疑对方」的句意相反。"}, {"text": "对峙", "is_correct": false, "explanation": "语义：「对峙」指敌对双方相持，与「互信」的友好语境不符。"}, {"text": "戒备", "is_correct": false, "explanation": "语义：「戒备」指提防、防备，与「从来不怀疑对方」的句意相反。"}], "explanations": {"互信": "正确：「互信」是动词，表示彼此相信对方，「我们两个人互信，从来不怀疑对方」符合句意。", "猜忌": "语义：「猜忌」指怀疑、猜疑，与后句「从来不怀疑对方」的句意相反。", "对峙": "语义：「对峙」指敌对双方相持，与「互信」的友好语境不符。", "戒备": "语义：「戒备」指提防、防备，与「从来不怀疑对方」的句意相反。"}, "sentence_index": 0, "correct_answer": "互信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两人在门口互信，谁也不肯先进去。", "explanation": "这里应该用〈礼让〉。互信表示彼此相信，不表示彼此谦让；两人都不肯先进门说的是礼让。"}, {"text": "这两个学生上课时互信，老师很生气。", "explanation": "这里应该用〈传纸条〉。互信表示彼此相信，不表示上课时互相递纸条；老师生气说的是传纸条。"}, {"text": "这两家公司互信多年，你追我赶，从不松懈。", "explanation": "这里应该用〈竞争〉。互信表示彼此相信，不表示你追我赶、互不松懈；这种局面说的是竞争。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互信", "is_correct": true, "explanation": "正确：「夫妻应该互信」指彼此相信对方，与后句「不要偷看对方的手机」相呼应，符合句意。"}, {"text": "检查", "is_correct": false, "explanation": "搭配：「检查」需要带对象（检查什么），「夫妻应该检查」说不完整。"}, {"text": "窥视", "is_correct": false, "explanation": "语义：「窥视」就是偷偷地看，与后句「不要偷看」的意思矛盾，句意不通。"}, {"text": "怀疑", "is_correct": false, "explanation": "搭配：「怀疑」通常要带对象（怀疑谁），「夫妻应该怀疑」说不完整。"}], "explanations": {"互信": "正确：「夫妻应该互信」指彼此相信对方，与后句「不要偷看对方的手机」相呼应，符合句意。", "检查": "搭配：「检查」需要带对象（检查什么），「夫妻应该检查」说不完整。", "窥视": "语义：「窥视」就是偷偷地看，与后句「不要偷看」的意思矛盾，句意不通。", "怀疑": "搭配：「怀疑」通常要带对象（怀疑谁），「夫妻应该怀疑」说不完整。"}, "sentence_index": 6, "correct_answer": "互信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩为一个小问题互信了很久。", "explanation": "这里应该用〈争执〉。互信指彼此相信，不表示因小事争论、僵持不下；为小问题争执说的是争执。"}, {"text": "我们每个月互信一次，聊聊近况。", "explanation": "这里应该用〈见面〉。互信表示彼此相信的状态，不能用来计算次数；「每个月一次」说的是见面。"}, {"text": "孩子摔倒了，互信了起来。", "explanation": "这里应该用〈哭〉。互信表示彼此相信，不表示哭泣；孩子摔倒后哭起来说的是哭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩从小就互信对方，什么事都说。", "corrected_sentence": "我们俩从小就互信，什么事都说。", "error_description": "带宾语错误：「互信」是不及物动词，后面不能直接带「对方」。应说「我们俩从小就互信」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只要把双方互信，合作就能顺利进行。", "corrected_sentence": "只要双方互信，合作就能顺利进行。", "error_description": "句式错误：「互信」是不及物动词，不能用「把」字句引出对象。应说「双方互信」，不说「把双方互信」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
