INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "很多人一起做的事。", "primary_collocate": null, "pronunciation": "qún tǐ xíng wéi", "ipa": "tɕʰyn˧˥ tʰi˨˩˦ ɕiŋ˧˥ weɪ˧˥", "syllable_count": 4, "sentences": [{"text": "跳广场舞是一种群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节回家是中国人的群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在球场上喊加油是球迷的群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们一起打扫教室，这是群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起唱歌，这就是群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游行是一种群体行为，很多人一起走上街头。", "target_word": "群体行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们一起玩游戏是一种群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看电影时大家一起笑，也是群体行为。", "target_word": "群体行为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司组织的爬山是群体行为，不是个人行为。", "target_word": "群体行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁里很多人同时低头看手机，这是群体行为。", "target_word": "群体行为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "群體行為", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多人一起做的事，如一起唱歌、一起游行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3dbc89-ce33-4c46-bf50-d7b1a6a2b937') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群体行为", "is_correct": true, "explanation": "正确。“跳广场舞”是很多人一起做的事，属于群体行为。"}, {"text": "数学定理", "is_correct": false, "explanation": "语义：“数学定理”是学科中的命题，与跳广场舞无关。"}, {"text": "八卦", "is_correct": false, "explanation": "语义：“八卦”指闲言碎语，不是跳广场舞这一类活动，句意不通。"}, {"text": "化学反应", "is_correct": false, "explanation": "语义：“化学反应”指物质之间的变化，与跳广场舞这种活动无关。"}], "explanations": {"群体行为": "正确。“跳广场舞”是很多人一起做的事，属于群体行为。", "数学定理": "语义：“数学定理”是学科中的命题，与跳广场舞无关。", "八卦": "语义：“八卦”指闲言碎语，不是跳广场舞这一类活动，句意不通。", "化学反应": "语义：“化学反应”指物质之间的变化，与跳广场舞这种活动无关。"}, "sentence_index": 0, "correct_answer": "群体行为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们一起打扫教室，这是一只群体行为。", "explanation": "量词用错。〈只〉用于动物或成对的物品，不能计量抽象的行为；这里应该用〈种〉。"}, {"text": "同学们一起打扫教室，这很群体行为。", "explanation": "〈群体行为〉是名词，不能用“很”修饰作谓语。应说“这是一种群体行为”。"}, {"text": "他一个人在房间里唱歌，这是群体行为。", "explanation": "这里应该用〈个人行为〉。〈群体行为〉要求很多人一起做，这里只有一个人唱歌，应说〈个人行为〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群体行为", "is_correct": true, "explanation": "正确。“一起玩游戏”是很多人共同做的事，属于群体行为。"}, {"text": "个人爱好", "is_correct": false, "explanation": "语义：“个人爱好”强调个人的兴趣，与“一起玩”的共同性相悖。"}, {"text": "独处方式", "is_correct": false, "explanation": "语义：“独处方式”指一个人的生活方式，与“孩子们一起玩”的语境相反。"}, {"text": "数学题", "is_correct": false, "explanation": "搭配：“玩游戏”与“数学题”不能归为同一类活动，类别搭配不当。"}], "explanations": {"群体行为": "正确。“一起玩游戏”是很多人共同做的事，属于群体行为。", "个人爱好": "语义：“个人爱好”强调个人的兴趣，与“一起玩”的共同性相悖。", "独处方式": "语义：“独处方式”指一个人的生活方式，与“孩子们一起玩”的语境相反。", "数学题": "搭配：“玩游戏”与“数学题”不能归为同一类活动，类别搭配不当。"}, "sentence_index": 6, "correct_answer": "群体行为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们周末一起群体行为，去郊外玩。", "explanation": "这里应该用动词〈行动〉。〈群体行为〉是名词，不能直接用在“一起”之后充当动词。"}, {"text": "他驾驶了这个群体行为。", "explanation": "〈驾驶〉只用于车辆、船只等，不能以“群体行为”作宾语。应说“这是一种群体行为”。"}, {"text": "我一个人在家看书，这也是群体行为。", "explanation": "这里应该用〈个人行为〉。〈群体行为〉要求很多人一起做，这里只有一个人看书，应说〈个人行为〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运动会上大家一起加油，也是一种的群体行为。", "corrected_sentence": "运动会上大家一起加油，也是一种群体行为。", "error_description": "“的”不能插在量词“种”和“群体行为”之间，应去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场演唱会的观众一起挥手，是一只群体行为。", "corrected_sentence": "这场演唱会的观众一起挥手，是一种群体行为。", "error_description": "“只”用于动物或成对的物品，不能计量抽象的“群体行为”；这里应该用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
