INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23892, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里学到的东西。", "primary_collocate": null, "pronunciation": "xīn dé", "ipa": "ɕin˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "参加完活动，每个人都说了心得。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次实习，你有什么心得？", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把读书的心得写在本子上。", "target_word": "心得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学游泳的心得，我愿意和你分享。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们写一份实习心得。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐常常和我谈她带孩子的心得。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对种花很有心得。", "target_word": "心得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看完比赛，爸爸讲了他的心得。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你学钢琴有什么心得？", "target_word": "心得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王的心得写得又短又清楚。", "target_word": "心得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "点", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "实习心得", "label": "复合词"}], "register": "中性", "sense_fingerprint": "自己学习或经历后心里的体会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3dbc89-ce33-4c46-bf50-d7b1a6a2b937') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心得", "is_correct": true, "explanation": "正确：心得指学习或经历后心里的体会，“每个人都说了……”指大家讲出了各自的体会。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“说礼物”不成立，礼物是送出去的东西，不能被说出来。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是一顿饭，与活动后讲体会的语境无关。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“说账单”与活动后大家讲体会的语境不搭配。"}], "explanations": {"心得": "正确：心得指学习或经历后心里的体会，“每个人都说了……”指大家讲出了各自的体会。", "礼物": "搭配：“说礼物”不成立，礼物是送出去的东西，不能被说出来。", "早饭": "语义：早饭是一顿饭，与活动后讲体会的语境无关。", "账单": "搭配：“说账单”与活动后大家讲体会的语境不搭配。"}, "sentence_index": 0, "correct_answer": "心得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈今天的心得很好，一直在笑。", "explanation": "这里应该用〈心情〉。心得指学习或经历后的认识，不用来形容情绪。"}, {"text": "他在山里迷路的心得很惊险。", "explanation": "这里应该用〈经历〉。心得是学习或经历后的认识，指一段亲身经过的事要用经历。"}, {"text": "他的心得很胖，买衣服要买大号。", "explanation": "这里应该用〈身材〉。心得是学习后的认识，不能用来形容体型；形容人胖瘦要用身材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心得", "is_correct": true, "explanation": "正确：心得指学习或经历后得到的体会，“对种花很有……”指在种花方面有体会。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指身体的高矮，与“对种花很有”搭配不当，句意不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“对种花很有工资”不成立，工资不能与“很有”构成对种花的认识。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑的一部分，不能说“对种花很有窗户”。"}], "explanations": {"心得": "正确：心得指学习或经历后得到的体会，“对种花很有……”指在种花方面有体会。", "身高": "语义：身高指身体的高矮，与“对种花很有”搭配不当，句意不通。", "工资": "搭配：“对种花很有工资”不成立，工资不能与“很有”构成对种花的认识。", "窗户": "语义：窗户是建筑的一部分，不能说“对种花很有窗户”。"}, "sentence_index": 6, "correct_answer": "心得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他心里一直有个心得：成为一名医生。", "explanation": "这里应该用〈心愿〉。心得指学习或经历后的认识，不能表示希望；心里一直想实现的愿望要用心愿。"}, {"text": "这套房子的心得每月五千元。", "explanation": "这里应该用〈房租〉。心得是学习后的认识，不能用来计算费用；租房每月要付的钱要用房租。"}, {"text": "这家饭店的心得很实惠，菜量也大。", "explanation": "这里应该用〈价格〉。心得是学习后的认识，不能用来形容饭菜的价钱；饭菜的售价要用价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看了他心得，学到很多。", "corrected_sentence": "我看了他的心得，学到很多。", "error_description": "结构错误：表示领属的“他的心得”需要加“的”，“他心得”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐写了一只心得，很有道理。", "corrected_sentence": "姐姐写了一篇心得，很有道理。", "error_description": "量词错误：「只」多用于动物，不能计量心得；写成文字的心得用「篇」，如「一篇心得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
