INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23894, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23894, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身份就是你是谁，比如你是学生还是老师。", "primary_collocate": null, "pronunciation": "shēn fen", "ipa": "ʂən˥ fən", "syllable_count": 2, "sentences": [{"text": "他的身份是学校的新老师。", "target_word": "身份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问他的真实身份。", "target_word": "身份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有两个身份，是妈妈，也是医生。", "target_word": "身份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进门以前，请先说明你的身份。", "target_word": "身份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直隐藏着自己的身份。", "target_word": "身份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以学生的身份参加了这次比赛。", "target_word": "身份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不知道她的真实身份。", "target_word": "身份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的新身份是公司经理。", "target_word": "身份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的身份很特别。", "target_word": "身份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先证明自己的身份。", "target_word": "身份", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "身份证", "label": "复合词"}], "register": "中性", "sense_fingerprint": "一个人在社会中的职业、地位或角色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca8c494-ae71-4330-9c72-7312641af8a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身份", "is_correct": true, "explanation": "身份：指一个人是谁或社会角色，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是数字，不能说明一个人是学校的新老师。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能说明一个人的角色，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体的数值，不能说明一个人的职业角色。"}], "explanations": {"身份": "身份：指一个人是谁或社会角色，符合句意。", "年龄": "语义：年龄是数字，不能说明一个人是学校的新老师。", "颜色": "语义：颜色不能说明一个人的角色，句意不通。", "体重": "体貌：体重是身体的数值，不能说明一个人的职业角色。"}, "sentence_index": 0, "correct_answer": "身份"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身份是一米八。", "explanation": "这里应该用〈身高〉。身份指一个人是谁或社会角色，不能用来说明身高这类体貌数值。"}, {"text": "他的身份是三十岁。", "explanation": "这里应该用〈年龄〉。身份指一个人是谁或社会角色，不能用来表示岁数；说岁数要用年龄。"}, {"text": "我有一只身份。", "explanation": "这里量词用错。身份应用〈个〉或〈种〉，〈只〉多用于动物或成对物品中的一个，不能用来数身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身份", "is_correct": true, "explanation": "身份：指一个人在社会中的身份，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是人的身份，「真实价格」用在人身上句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：人没有「真实味道」的说法，句意不通。"}, {"text": "容量", "is_correct": false, "explanation": "搭配：「容量」用于容器，不能用于描述一个人。"}], "explanations": {"身份": "身份：指一个人在社会中的身份，符合句意。", "价格": "语义：价格不是人的身份，「真实价格」用在人身上句意不通。", "味道": "语义：人没有「真实味道」的说法，句意不通。", "容量": "搭配：「容量」用于容器，不能用于描述一个人。"}, "sentence_index": 6, "correct_answer": "身份"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出门要带身份。", "explanation": "这里应该用〈身份证〉。身份是人的社会角色，不能直接携带；出门要带的是身份证。"}, {"text": "他的身份很健康。", "explanation": "这里应该用〈身体〉。身份不能用来形容健康状况，说健康要用身体。"}, {"text": "他有一条身份。", "explanation": "这里量词用错。身份应用〈个〉或〈种〉，〈条〉用于细长的东西，不能用来数身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一本新身份。", "corrected_sentence": "他有一个新身份。", "error_description": "错误：「身份」的量词应用「个」或「种」，不能用「本」（本用于书册）。应说「一个新身份」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我要确认他的身份们。", "corrected_sentence": "我要确认他的身份。", "error_description": "错误：「身份」指人的社会角色，是事物，不能加表示人的复数词尾「们」。应说「我要确认他的身份」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
