INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "所有部分都相同的样子。", "primary_collocate": null, "pronunciation": "tǒng yī xìng", "ipa": "tʰʊŋ˨˩ i˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这条街的房子有很强的统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两本书的封面缺乏统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校要求校服保持统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套杯子在大小和样子上都有很强的统一性。", "target_word": "统一性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的楼房在外观上很有统一性。", "target_word": "统一性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画里的颜色看起来很有统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家穿同样的衣服，显得很有统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些桌子的高度没有统一性。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢这套碗，它们的样式很有统一性。", "target_word": "统一性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的花瓶没有统一性，有大有小。", "target_word": "统一性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "統一性", "label": "繁体"}, {"form": "统一", "label": "词根"}, {"form": "统一体", "label": "复合词"}], "register": "书面", "sense_fingerprint": "各个部分样子完全相同的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3dbc89-ce33-4c46-bf50-d7b1a6a2b937') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "统一性", "is_correct": true, "explanation": "正确。“很强的统一性”指房屋外观的一致程度，与句意相合。"}, {"text": "攻击性", "is_correct": false, "explanation": "语义：“攻击性”指对外的冲击倾向，用来形容房屋外观不合语境。"}, {"text": "导电性", "is_correct": false, "explanation": "搭配：“房子”不谈“导电性”，二者搭配不当。"}, {"text": "时效性", "is_correct": false, "explanation": "语义：“时效性”指在一定时期内有效，与描述房屋外观的语境无关。"}], "explanations": {"统一性": "正确。“很强的统一性”指房屋外观的一致程度，与句意相合。", "攻击性": "语义：“攻击性”指对外的冲击倾向，用来形容房屋外观不合语境。", "导电性": "搭配：“房子”不谈“导电性”，二者搭配不当。", "时效性": "语义：“时效性”指在一定时期内有效，与描述房屋外观的语境无关。"}, "sentence_index": 0, "correct_answer": "统一性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套杯子在大小和样子上都很统一性。", "explanation": "“统一性”是名词，不能直接用“很”修饰作谓语。应说“都很统一”或“都有很强的统一性”。"}, {"text": "这套杯子在大小上有一只统一性。", "explanation": "量词用错。“只”用于动物或成对的物品，不能计量“统一性”这类抽象名词，这里应该用〈种〉。"}, {"text": "这套杯子各不相同，每只都有很强的统一性。", "explanation": "这里应该用〈独特性〉。“统一性”指所有部分都相同，与“各不相同”正好相反；说每件都与众不同，应用〈独特性〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "统一性", "is_correct": true, "explanation": "正确。“显得很有统一性”指大家穿同样的衣服所呈现的一致效果，与句意相合。"}, {"text": "多样性", "is_correct": false, "explanation": "语义：“多样性”指形式繁多，与“穿同样的衣服”的语境正相反。"}, {"text": "差异性", "is_correct": false, "explanation": "搭配：“差异性”常与“不同”“各异”连用，与“同样”不搭配。"}, {"text": "独特性", "is_correct": false, "explanation": "语义：“独特性”指与众不同的特点，与大家穿同样衣服的情形相悖。"}], "explanations": {"统一性": "正确。“显得很有统一性”指大家穿同样的衣服所呈现的一致效果，与句意相合。", "多样性": "语义：“多样性”指形式繁多，与“穿同样的衣服”的语境正相反。", "差异性": "搭配：“差异性”常与“不同”“各异”连用，与“同样”不搭配。", "独特性": "语义：“独特性”指与众不同的特点，与大家穿同样衣服的情形相悖。"}, "sentence_index": 6, "correct_answer": "统一性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这个人很有统一性，前后说的话总是不一样。", "explanation": "“统一性”指各部分都相同，与“前后说的话总是不一样”矛盾。应说“说话前后不一”。"}, {"text": "工人搬运了桌子的统一性。", "explanation": "这里应该用〈物品〉作宾语。〈搬运〉的对象是具体物品，“统一性”是抽象特征，不能被搬运。"}, {"text": "我们要把桌子的样式统一性起来。", "explanation": "这里应该用动词〈统一〉。“统一性”是名词，不能接“起来”作补语，“把样式统一起来”才正确。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这排路灯的样式很有统一。", "corrected_sentence": "这排路灯的样式很有统一性。", "error_description": "“统一性”是名词，“性”不能省略；去掉“性”后，“统一”不能作“有”的宾语。应为“很有统一性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些杯子的统一性强很，大小和样式都一样。", "corrected_sentence": "这些杯子的统一性很强，大小和样式都一样。", "error_description": "“很”应放在形容词“强”前面，说“统一性很强”；“统一性强很”的语序不对，“很”不能放在“强”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf833b0-83c5-4ff8-92a8-24923357637d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
