INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西像水一样容易流来流去的性质。", "primary_collocate": null, "pronunciation": "liú dòng xìng", "ipa": "ljou̯˧˥ tʊŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "水的流动性很好。", "target_word": "流动性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "油比水黏，流动性差一些。", "target_word": "流动性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "蜂蜜的流动性比牛奶差。", "target_word": "流动性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气冷了，油的流动性变差了。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙子很细的时候，也有一点流动性。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热巧克力酱的流动性很强，能慢慢流下来。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种墨水流动性好，写字很顺畅。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加水以后，泥浆的流动性变大了。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火山的岩浆流动性强，流得很快很远。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种涂料的流动性太好，刷在墙上会往下流。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流動性", "label": "繁体"}, {"form": "流动", "label": "词根"}], "register": "通用", "sense_fingerprint": "液体或类似液体的物质容易流动的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c34999df-c2a8-41e6-84de-552383229488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形状", "is_correct": false, "explanation": "语义：水没有固定的形状，“形状”与“很好”的评价不搭配。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：说水的好坏不用“重量”，“水的重量很好”不通。"}, {"text": "流动性", "is_correct": true, "explanation": "“流动性”指液体容易流动的性质，水的流动性好，语境相合。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只用于人或生物，不能说水的年龄。"}], "explanations": {"形状": "语义：水没有固定的形状，“形状”与“很好”的评价不搭配。", "重量": "搭配：说水的好坏不用“重量”，“水的重量很好”不通。", "流动性": "“流动性”指液体容易流动的性质，水的流动性好，语境相合。", "年龄": "搭配：“年龄”只用于人或生物，不能说水的年龄。"}, "sentence_index": 0, "correct_answer": "流动性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河水的流动性很快，几分钟就冲到了下游。", "explanation": "这里应该用〈流速〉。流动性指液体容易流动的性质，形容水流快慢要说“流速”，不能说流动性。"}, {"text": "这块石头的流动性很高，锤子都敲不碎。", "explanation": "这里应该用〈硬度〉。流动性指东西容易像水一样流动的性质，石头是固体，说它的坚硬程度要用“硬度”，不能说流动性。"}, {"text": "这块铁的流动性很大，放在水里会沉下去。", "explanation": "这里应该用〈密度〉。流动性指液体容易流动的性质，说铁放进水里沉不沉要用“密度”，铁是固体，不能说流动性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身份", "is_correct": false, "explanation": "语义：“身份”指人的社会地位，墨水没有身份。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“学历”只用于人，不能用于墨水。"}, {"text": "流动性", "is_correct": true, "explanation": "“流动性”好指墨水容易流动，写字才会顺畅，语境相合。"}, {"text": "辈分", "is_correct": false, "explanation": "语义：“辈分”指人际或家族中的代际关系，与墨水无关。"}], "explanations": {"身份": "语义：“身份”指人的社会地位，墨水没有身份。", "学历": "搭配：“学历”只用于人，不能用于墨水。", "流动性": "“流动性”好指墨水容易流动，写字才会顺畅，语境相合。", "辈分": "语义：“辈分”指人际或家族中的代际关系，与墨水无关。"}, "sentence_index": 6, "correct_answer": "流动性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的流动性很深，不能下去游泳。", "explanation": "这里应该用〈水〉。流动性指东西容易流动的性质，没有深浅之分；说河深要说“河水很深”，不能说流动性很深。"}, {"text": "这瓶牛奶的流动性很甜，孩子很喜欢喝。", "explanation": "这里应该用〈味道〉。流动性指液体容易流动的性质，和甜不甜无关；说牛奶甜要说“味道很甜”。"}, {"text": "这种墨水的流动性是蓝色的。", "explanation": "这里应该用〈颜色〉。流动性指液体容易流动的性质，不是颜色；说墨水是蓝色要说“颜色是蓝色的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种油漆的流动性好很，刷起来很均匀。", "corrected_sentence": "这种油漆的流动性很好，刷起来很均匀。", "error_description": "语序错误：程度副词“很”应放在形容词“好”前面，应说“流动性很好”，不能说“流动性好很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种涂料的流动性很多，刷上去很快就流下来了。", "corrected_sentence": "这种涂料的流动性很强，刷上去很快就流下来了。", "error_description": "搭配错误：“流动性”是一种性质，用“强/弱、好/差”来说程度，不能说“流动性很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
