INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人心里怎么想事情或对事情有什么看法。", "primary_collocate": null, "pronunciation": "yì jiàn", "ipa": "i˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他心里有自己的意见，不说出来。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做决定之前，要先有自己的意见。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对这件事还没有形成意见。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，对很多事都有自己的意见。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个问题的意见一直没变。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的意见是慢慢改变的。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了朋友的话，我改变了原来的意见。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的意见都写在这张纸上了。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末去哪儿玩，我想听听你的意见。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人对爱情的意见都不太一样。", "target_word": "意见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "条", "label": "量词"}, {"form": "意见书", "label": "复合"}, {"form": "意見", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人心里对事情形成的想法、看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f917e74-ef1d-49a8-a590-87211bbc2e31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23904, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意见", "is_correct": true, "explanation": "意见 yì jiàn：心里对事情形成的想法或看法，是本题正确答案。"}, {"text": "一键", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是一个按键，如“一键启动”。"}, {"text": "一间", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，“一”读 yì，意思是一个房间。"}, {"text": "器件", "is_correct": false, "explanation": "qì 与 yì 声母不同（qì 有声母 q，yì 没有声母），意思是电子或机械的零部件。"}, {"text": "寄件", "is_correct": false, "explanation": "jì 与 yì 声母不同（jì 有声母 j，yì 没有声母），寄件指寄送物件。"}], "explanations": {"意见": "意见 yì jiàn：心里对事情形成的想法或看法，是本题正确答案。", "一键": "yí（第二声）与 yì（第四声）声调不同，意思是一个按键，如“一键启动”。", "一间": "jiān（第一声）与 jiàn（第四声）声调不同，“一”读 yì，意思是一个房间。", "器件": "qì 与 yì 声母不同（qì 有声母 q，yì 没有声母），意思是电子或机械的零部件。", "寄件": "jì 与 yì 声母不同（jì 有声母 j，yì 没有声母），寄件指寄送物件。"}, "sentence_index": null, "correct_answer": "意见"}, "level_3": {"options": [{"text": "意见", "is_correct": true, "explanation": "意见：心里对事情的想法或看法，与“心里有”搭配，句意通顺。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：“钱包”是物品，不能放在“心里”，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”一般说“几岁”，不说“心里有自己的年龄”。"}, {"text": "车", "is_correct": false, "explanation": "语义：“车”是交通工具，不能存在于“心里”，句子不通。"}], "explanations": {"意见": "意见：心里对事情的想法或看法，与“心里有”搭配，句意通顺。", "钱包": "语义：“钱包”是物品，不能放在“心里”，句子不通。", "年龄": "搭配：“年龄”一般说“几岁”，不说“心里有自己的年龄”。", "车": "语义：“车”是交通工具，不能存在于“心里”，句子不通。"}, "sentence_index": 0, "correct_answer": "意见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的意见很美，让人看了很感动。", "explanation": "这里应该用〈意境〉。意境指作品中的境界和情调，意见指个人的看法，不能用来形容画的境界。"}, {"text": "这项研究的意见很深远，影响了很多学者。", "explanation": "这里应该用〈意义〉。意义指事情的重要价值，意见指个人的看法，不能用来形容研究的影响。"}, {"text": "他很有时间意见，每次都准时到。", "explanation": "这里应该用〈意识〉。时间意识指对时间的重视和察觉，意见指看法，不能用来表示对时间的重视。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23904, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "意见", "is_correct": true, "explanation": "意见 yì jiàn：心里对事情形成的想法或看法，是本题正确答案。"}, {"text": "一件", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是一个物件。"}, {"text": "一箭", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是一支箭，如“一箭双雕”。"}, {"text": "一见", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是看一眼，如“一见如故”。"}, {"text": "一剑", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是一次剑击，如“一剑封喉”。"}], "explanations": {"意见": "意见 yì jiàn：心里对事情形成的想法或看法，是本题正确答案。", "一件": "yí（第二声）与 yì（第四声）声调不同，意思是一个物件。", "一箭": "yí（第二声）与 yì（第四声）声调不同，意思是一支箭，如“一箭双雕”。", "一见": "yí（第二声）与 yì（第四声）声调不同，意思是看一眼，如“一见如故”。", "一剑": "yí（第二声）与 yì（第四声）声调不同，意思是一次剑击，如“一剑封喉”。"}, "sentence_index": null, "correct_answer": "意见"}, "level_3": {"options": [{"text": "意见", "is_correct": true, "explanation": "意见：对事情的看法，“改变了原来的”后接“意见”，句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体特征，听朋友的话不会改变它，句子不通。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是固定的日期，不能因听话而改变，句子不通。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是先天的生理特征，不能因听话而改变，句子不通。"}], "explanations": {"意见": "意见：对事情的看法，“改变了原来的”后接“意见”，句意通顺。", "身高": "体貌：身高是身体特征，听朋友的话不会改变它，句子不通。", "生日": "语义：生日是固定的日期，不能因听话而改变，句子不通。", "血型": "语义：血型是先天的生理特征，不能因听话而改变，句子不通。"}, "sentence_index": 6, "correct_answer": "意见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息出乎我的意见，我完全没想到。", "explanation": "这里应该用〈意料〉。固定说“出乎……的意料”，意见指看法，不能用来表示预料之外。"}, {"text": "这次事故完全是意见，没人能预料。", "explanation": "这里应该用〈意外〉。意外指没有预料到的不幸事件，意见指看法，不能用来指事故。"}, {"text": "那时他意见风发，谁都不放在眼里。", "explanation": "这里应该用〈意气〉。意气风发形容精神饱满、充满干劲，意见指看法，不能用来形容精神状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这件事提出了一本意见，大家都听了。", "corrected_sentence": "他对这件事提出了一条意见，大家都听了。", "error_description": "量词错误：“意见”应用“条”或“个”计数，“本”用于书册，不能用来数意见。应改为“一条意见”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的意见我们都听了过。", "corrected_sentence": "他的意见我们都听过了。", "error_description": "体标错误：“过”表示经历，应紧跟动词“听”，应说“听过了”，不能说“听了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
