INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23906, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "也，表示同样。", "primary_collocate": null, "pronunciation": "yì", "ipa": "i˥˩", "syllable_count": 1, "sentences": [{"text": "他爱读书，亦爱写字。", "target_word": "亦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说得对，我亦这样想。", "target_word": "亦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事说难亦不难。", "target_word": "亦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会唱歌，亦会跳舞。", "target_word": "亦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有你的路，我亦有我的路。", "target_word": "亦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是坏人，亦不是好人。", "target_word": "亦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥是医生，姐姐亦是医生。", "target_word": "亦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山很美，水亦很美。", "target_word": "亦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这里的人，亦喜欢这里的菜。", "target_word": "亦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了对不起，我亦说了对不起。", "target_word": "亦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，书面语的“也”，表示两件事同样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '449b634c-ae74-4ccb-8934-b82cc0828b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亦", "is_correct": true, "explanation": "「亦」是正确答案，读作 yì（第四声），意思是“也”。"}, {"text": "以", "is_correct": false, "explanation": "「yǐ（第三声）」与「yì（第四声）」声调不同，「以」意思是“用、凭借”。"}, {"text": "一", "is_correct": false, "explanation": "「yī（第一声）」与「yì（第四声）」声调不同，「一」是数字“一”。"}, {"text": "疑", "is_correct": false, "explanation": "「yí（第二声）」与「yì（第四声）」声调不同，「疑」意思是“怀疑”。"}], "explanations": {"亦": "「亦」是正确答案，读作 yì（第四声），意思是“也”。", "以": "「yǐ（第三声）」与「yì（第四声）」声调不同，「以」意思是“用、凭借”。", "一": "「yī（第一声）」与「yì（第四声）」声调不同，「一」是数字“一”。", "疑": "「yí（第二声）」与「yì（第四声）」声调不同，「疑」意思是“怀疑”。"}, "sentence_index": null, "correct_answer": "亦"}, "level_3": {"options": [{"text": "亦", "is_correct": true, "explanation": "「亦」表示“也”，与前后并列的“爱读书”“爱写字”相呼应。"}, {"text": "只", "is_correct": false, "explanation": "语义：「只」表示限定，与“爱读书”的并列关系矛盾，句子说不通。"}, {"text": "都", "is_correct": false, "explanation": "搭配：「都」要求表示“全部”的对象，这里“他”的两个爱好不能用「都」连接。"}, {"text": "才", "is_correct": false, "explanation": "语义：「才」表示“到那时才”，与“爱读书，爱写字”的并列关系不合。"}], "explanations": {"亦": "「亦」表示“也”，与前后并列的“爱读书”“爱写字”相呼应。", "只": "语义：「只」表示限定，与“爱读书”的并列关系矛盾，句子说不通。", "都": "搭配：「都」要求表示“全部”的对象，这里“他”的两个爱好不能用「都」连接。", "才": "语义：「才」表示“到那时才”，与“爱读书，爱写字”的并列关系不合。"}, "sentence_index": 0, "correct_answer": "亦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我亦你是好朋友。", "explanation": "这里应该用〈和〉。亦表示同样，不能用来连接两个名词，表示并列的“和”要用〈和〉。"}, {"text": "他一看见我，亦跑了过去。", "explanation": "这里应该用〈立刻〉。亦表示同样，不表示动作紧接发生，看见就立刻跑过去要用〈立刻〉。"}, {"text": "你喜欢茶亦咖啡？", "explanation": "这里应该用〈还是〉。亦表示同样，不能用于选择问句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23906, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亦", "is_correct": true, "explanation": "「亦」是正确答案，读作 yì（第四声），意思是“也”。"}, {"text": "已", "is_correct": false, "explanation": "「yǐ（第三声）」与「yì（第四声）」声调不同，「已」意思是“已经”。"}, {"text": "衣", "is_correct": false, "explanation": "「yī（第一声）」与「yì（第四声）」声调不同，「衣」意思是“衣服”。"}, {"text": "姨", "is_correct": false, "explanation": "「yí（第二声）」与「yì（第四声）」声调不同，「姨」意思是“姨妈”。"}], "explanations": {"亦": "「亦」是正确答案，读作 yì（第四声），意思是“也”。", "已": "「yǐ（第三声）」与「yì（第四声）」声调不同，「已」意思是“已经”。", "衣": "「yī（第一声）」与「yì（第四声）」声调不同，「衣」意思是“衣服”。", "姨": "「yí（第二声）」与「yì（第四声）」声调不同，「姨」意思是“姨妈”。"}, "sentence_index": null, "correct_answer": "亦"}, "level_3": {"options": [{"text": "亦", "is_correct": true, "explanation": "「亦」表示“也”，与前句“哥哥是医生”形成同样的判断，句意通顺。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：「正在」表示进行中的动作，不能与判断动词「是」连用。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「很」不能与判断句“姐姐是医生”连用，「很是医生」说不通。"}, {"text": "最", "is_correct": false, "explanation": "搭配：「最」不能修饰判断动词「是」加身份名词，「最是医生」说不通。"}], "explanations": {"亦": "「亦」表示“也”，与前句“哥哥是医生”形成同样的判断，句意通顺。", "正在": "体貌：「正在」表示进行中的动作，不能与判断动词「是」连用。", "很": "搭配：「很」不能与判断句“姐姐是医生”连用，「很是医生」说不通。", "最": "搭配：「最」不能修饰判断动词「是」加身份名词，「最是医生」说不通。"}, "sentence_index": 6, "correct_answer": "亦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "直到昨天亦见面。", "explanation": "这里应该用〈才〉。「亦」表示同样，不能表示“直到某时才”的限定关系，这里要说〈才〉。"}, {"text": "你去亦不去？", "explanation": "这里应该用〈还是〉。亦表示同样，不能用于选择式提问，要在两种情况中选择时用〈还是〉。"}, {"text": "我买了苹果亦香蕉。", "explanation": "这里应该用〈和〉。亦是副词，不能连接两个名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们也亦去了那里。", "corrected_sentence": "他们亦去了那里。", "error_description": "叠用错误。「也」与「亦」都表示“同样”，不能叠用，应去掉「也」，说「他们亦去了那里」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "亦我喜欢这首歌。", "corrected_sentence": "我亦喜欢这首歌。", "error_description": "语序错误。副词「亦」应放在主语之后、动词之前，「亦我喜欢这首歌」中「亦」位于主语之前，应为「我亦喜欢这首歌」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
